fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self.try_read() {
            Some(guard) => f
                .debug_struct("SpinRwLock")
                .field("data", &&*guard)
                .finish(),
            None => f
                .debug_struct("SpinRwLock")
                .field("data", &"<locked>")
                .finish(),
        }
    }

fn insert_cache(&self, name: String, entry: Dentry) -> Option<Dentry> {
        if self.can_cache_children() && entry.can_cache_as_child() {
            let mut children = self.0.children.lock();
            if let Some(existing) = children
                .get(&name)
                .and_then(|entry| entry.upgrade().map(Dentry))
            {
                return Some(existing);
            }
            children.insert(name, Arc::downgrade(&entry.0));
            drop(children);
            if let Some(super_block) = entry.super_block() {
                super_block.cache_dentry(entry);
            }
        }
        None
    }

fn test_parallel_lookup_candidate_does_not_escape_cache_snapshot() {
    let fs = Arc::new(MockFilesystem);
    let (dir, _) = make_non_cacheable_dir(fs, 2, None, "dir");
    let candidate = Dentry::new_negative(Some(dir.clone()), String::from("ptmx"));
    candidate.begin_parallel_lookup();
    assert!(dir.cache_lookup_candidate("ptmx", &candidate).is_none());

    let observed = dir.lookup_cache_entry("ptmx");
    dir.uncache_lookup_candidate("ptmx", &candidate);
    candidate.end_parallel_lookup();

    assert!(observed.is_none());
    assert!(dir.lookup_cache_entry("ptmx").is_none());
}

fn test_tree() -> TestTree {
    let root_ops = Arc::new(TestDir::new(1));
    let root_inode =
        VfsInode::new_openable_dir(root_ops.clone(), inode_init(1, NodeType::Directory, 0));
    let root = Dentry::new_dir_from_inode(root_inode, None, String::new());
    let target = file_entry(2, &root, "target", NodeType::RegularFile, b"target", None);
    root_ops.insert("target", target.clone());

    let link = file_entry(3, &root, "link", NodeType::Symlink, b"/target", None);
    root_ops.insert("link", link);

    let (target_dir, target_dir_ops) = dir_entry(4, &root, "dir");
    let leaf = file_entry(5, &target_dir, "leaf", NodeType::RegularFile, b"leaf", None);
    target_dir_ops.insert("leaf", leaf.clone());
    root_ops.insert("dir", target_dir.clone());

    let dir_link = file_entry(6, &root, "dirlink", NodeType::Symlink, b"/dir", None);
    root_ops.insert("dirlink", dir_link);

    let autodir_inode = VfsInode::new_dir(
        Arc::new(TestFile::new(9, NodeType::Directory, &[], None)),
        inode_init(9, NodeType::Directory, 0),
    );
    let autodir =
        Dentry::new_dir_from_inode(autodir_inode, Some(root.clone()), String::from("autodir"));
    root_ops.insert("autodir", autodir);

    let fs = SuperBlock::new(&TEST_FILE_SYSTEM_TYPE, &TEST_SUPER_BLOCK_OPERATIONS, |_| {
        root.clone()
    });
    let mount = Mount::new_root(&fs);
    let root_location = mount.root_path();
    let target_location = Path::new(mount.clone(), target);
    let target_dir_location = Path::new(mount.clone(), target_dir);

    let magic_file = Arc::new(TestMagicLink::new(
        "/display/target",
        target_location.clone(),
    ));
    let magic_entry = file_entry(
        7,
        &root,
        "magic",
        NodeType::Symlink,
        b"/display/target",
        Some(magic_file.clone()),
    );
    root_ops.insert("magic", magic_entry);

    let magic_dir = Arc::new(TestMagicLink::new(
        "/display/dir",
        target_dir_location.clone(),
    ));
    let magic_dir_entry = file_entry(
        8,
        &root,
        "magicdir",
        NodeType::Symlink,
        b"/display/dir",
        Some(magic_dir.clone()),
    );
    root_ops.insert("magicdir", magic_dir_entry);

    TestTree {
        fs,
        root: root_location.clone(),
        base: root_location,
        target: target_location,
        magic_file,
        magic_dir,
    }
}

fn graft_tree(&self, mount: Mount) -> VfsResult<Arc<Mount>> {
        let inode = self.inode();
        let _namespace_guard = inode.lock_namespace_exclusive();
        if mount.mnt.mnt_root.as_dir().is_ok() != self.is_dir() {
            // Linux `graft_tree()` returns `ENOTDIR` for either direction of
            // a directory/non-directory mismatch.
            return Err(VfsError::NotADirectory);
        }
        let result = mount.into_arc_at(Some(self.clone()));
        if let Some(old) = self.mnt.install_child_mount(&self.dentry, &result) {
            *result.covers.lock() = Some(old);
        }
        Ok(result)
    }

fn detach_mount_subtree(&self, mounts: &[Arc<Mount>]) -> VfsResult<()> {
        if !self.dentry.ptr_eq(&self.mnt.mnt.mnt_root) {
            return Err(VfsError::InvalidInput);
        }
        if !mounts
            .first()
            .is_some_and(|root| Arc::ptr_eq(root, &self.mnt))
        {
            return Err(VfsError::InvalidInput);
        }

        let parent_path = self.mnt.location().ok_or(VfsError::InvalidInput)?;
        let inode = parent_path.inode();
        let _namespace_guard = inode.lock_namespace_exclusive();
        if !parent_path
            .mnt
            .child_mount_at(&parent_path.dentry)
            .is_some_and(|mount| Arc::ptr_eq(&mount, &self.mnt))
        {
            return Err(VfsError::InvalidInput);
        }

        let covered = self.mnt.covers.lock().take();
        match covered {
            Some(ref mount) => {
                parent_path
                    .mnt
                    .install_child_mount(&parent_path.dentry, mount);
            }
            None => parent_path.mnt.remove_child_mount(&parent_path.dentry),
        }

        // All fallible checks complete before this commit phase. The namespace
        // entry point also validates registry membership for every layer. The
        // remaining operations are infallible, so an overmount cannot be
        // restored halfway and leave stale registry entries.
        for mount in mounts {
            mount.mnt_mounts.lock().clear();
            mount.covers.lock().take();
            mount.detach();
        }
        Ok(())
    }

fn mount_filesystem_with_requested_superblock_flags(
        &self,
        fs: &Arc<SuperBlock>,
        flags: MountFlags,
        devname: Option<&str>,
        requested_superblock_flags: Option<SuperBlockFlags>,
    ) -> VfsResult<Arc<Mount>> {
        // A second mount of the same superblock at its own root cannot make
        // any new filesystem state visible, but stacking it would hide every
        // child mount attached below the existing mount. Keep the existing
        // mount when it is at least as restrictive as the request; otherwise
        // let the new mount replace it so stricter flags take effect. A
        // request for looser flags is left to MS_REMOUNT rather than silently
        // weakening the live mount. A bind mount of a subdirectory is not the
        // superblock root, so it is always replaced by a full-filesystem mount.
        if requested_superblock_flags.is_none_or(|flags| flags.is_empty())
            && self.is_mount_root()
            && Arc::ptr_eq(self.mount().super_block(), fs)
            && self.mount().root_path().dentry.ptr_eq(&fs.root_dir())
            && self.mount().flags().contains(flags)
        {
            return Ok(self.mount().clone());
        }
        let mount = Mount::try_new_detached(fs, flags, devname, requested_superblock_flags)?
            .ok_or(VfsError::ResourceBusy)?;
        self.graft_tree(mount)
    }

fn poll(&self) -> IoEvents {
        let source = self.source.poll();
        let destination = self.destination.poll();
        if destination.contains(IoEvents::ERR) {
            IoEvents::ERR
        } else if source.contains(IoEvents::IN) && destination.contains(IoEvents::OUT) {
            IoEvents::IN | IoEvents::OUT
        } else if source.contains(IoEvents::HUP) && !source.contains(IoEvents::IN) {
            IoEvents::HUP
        } else {
            IoEvents::empty()
        }
    }

fn chown_mode(mode: Umode, old_gid: u32, new_gid: Option<u32>, cred: &Cred) -> NodePermission {
        let permission = mode.permission();
        if mode.node_type() == NodeType::Directory {
            return permission;
        }

        let mut result = permission;
        result.remove(NodePermission::SET_UID);
        if permission.contains(NodePermission::SET_GID) {
            let old_group_ok = cred.has_cap(kcred::CAP_FSETID) || cred.in_group(old_gid);
            if permission.contains(NodePermission::GROUP_EXEC) || !old_group_ok {
                result.remove(NodePermission::SET_GID);
            }
        }
        if result.bits() != permission.bits()
            && new_gid.is_some_and(|gid| !cred.has_cap(kcred::CAP_FSETID) && !cred.in_group(gid))
        {
            result.remove(NodePermission::SET_GID);
        }
        result
    }

fn verify_write_area(&self, pos: u64, count: usize) -> VfsResult<()> {
        self.verify_mode(FMode::WRITE)?;
        if !self.mode().contains(FMode::CAN_WRITE) {
            return Err(VfsError::InvalidInput);
        }
        self.verify_io_area(pos, count)?;
        if self.node_type().is_special() {
            Ok(())
        } else {
            self.path().check_writable_mount()
        }
    }

fn test_pivot_root_rejects_put_old_outside_new_root() {
    let root_fs = mock_filesystem(StatFsFlags::empty());
    let new_root_fs = mock_filesystem(StatFsFlags::empty());
    let other_fs = mock_filesystem(StatFsFlags::empty());
    let namespace = MntNamespace::build_initial_mount_tree(&root_fs).unwrap();
    let visible = namespace.visible_root_path();
    let cred = kcred::initial_cred();
    let new_mnt = namespace
        .attach(
            &visible
                .mkdir("newroot", NodePermission::default(), &cred)
                .unwrap(),
            &new_root_fs,
        )
        .unwrap();
    let other_mnt = namespace
        .attach(
            &visible
                .mkdir("other", NodePermission::default(), &cred)
                .unwrap(),
            &other_fs,
        )
        .unwrap();
    let put_old = other_mnt
        .root_path()
        .mkdir("oldroot", NodePermission::default(), &cred)
        .unwrap();

    assert_eq!(
        namespace.pivot_root(
            &new_mnt.root_path(),
            &put_old,
            &namespace.visible_root_path()
        ),
        Err(VfsError::InvalidInput),
        "put_old must be reachable from new_root"
    );
}

