fn mock_filesystem(mount_flags: StatFsFlags) -> Arc<SuperBlock> {
    let inode =
        VfsInode::new_openable_dir(Arc::new(MockDirOps::new(mount_flags, 1)), inode_init(1));
    let root = Dentry::new_dir_from_inode(inode, None, String::new());
    mock_superblock(root, mount_flags)
}

fn list_xattrs(&self, cred: &Cred, sink: &mut dyn XattrNameSink) -> VfsResult<()> {
        let inode = self.inode();
        let mut filtering_sink = CredentialFilteringSink {
            inner: sink,
            can_read_trusted: cred.has_sys_admin(),
        };
        inode.list_xattrs(self.dentry(), &mut filtering_sink)
    }

fn set_xattr(
        &self,
        name: &XattrName,
        value: &[u8],
        flags: XattrSetFlags,
        cred: &Cred,
    ) -> VfsResult<()> {
        self.check_writable_mount()?;
        let inode = self.inode();
        check_xattr_permission(&inode, name, XattrAccess::Write, cred)?;
        let _data_guard = inode.lock_data();
        inode.set_xattr(self.dentry(), name, value, flags)
    }

fn block_file_retains_open_identity_across_device_number_reuse() {
    use core::sync::atomic::Ordering::Relaxed;
    let old = OpenBlockDevice::new(8);
    let disk =
        block::Gendisk::alloc(String::from("open-old"), 242, 0, 1, Box::new(old.clone())).unwrap();
    let device = block::add_disk(disk).unwrap();
    let rdev = device.device_number();
    let flags =
        crate::OpenFlags::READ_WRITE | crate::OpenFlags::EXCLUSIVE | crate::OpenFlags::NONBLOCK;
    let (file, _) = open_block_device_file_with(rdev, flags).unwrap();
    let mode = BlockOpenMode::READ
        | BlockOpenMode::WRITE
        | BlockOpenMode::EXCLUSIVE
        | BlockOpenMode::NONBLOCK;
    assert_eq!(old.modes.lock().as_slice(), &[mode]);
    assert!(matches!(
        open_block_device_file_with(rdev, flags),
        Err(VfsError::ResourceBusy)
    ));
    block::del_gendisk(rdev).unwrap();
    assert_eq!(file.size(), 4096);
    file.fsync(false).unwrap();

    let replacement = OpenBlockDevice::new(16);
    let disk = block::Gendisk::alloc(
        String::from("open-new"),
        242,
        0,
        1,
        Box::new(replacement.clone()),
    )
    .unwrap();
    let new_device = block::add_disk(disk).unwrap();
    assert_eq!(file.llseek(0, SEEK_END).unwrap(), 4096);
    assert_eq!(new_device.size(), 8192);
    let mut offset = 0;
    file.write_from(&[0xa5; 512], &mut offset).unwrap();
    let mut output = [0; 512];
    let mut read_offset = 0;
    file.read_from(&mut output, &mut read_offset).unwrap();
    assert_eq!(output, [0xa5; 512]);
    assert!(
        replacement
            .memory
            .storage
            .lock()
            .iter()
            .all(|&byte| byte == 0x35)
    );
    let cred = kcred::initial_cred();
    assert_eq!(file.ioctl(&cred, u32::MAX, 0), Ok(17));
    file.set_nonblocking(false);
    assert_eq!(file.ioctl(&cred, u32::MAX, 0), Ok(17));
    assert_eq!(
        old.ioctl_modes.lock().as_slice(),
        &[mode, mode & !BlockOpenMode::NONBLOCK]
    );
    assert!(replacement.ioctl_modes.lock().is_empty());
    let duplicate = file.clone();
    drop(file);
    assert_eq!(old.releases.load(Relaxed), 0);
    drop(duplicate);
    assert_eq!(old.releases.load(Relaxed), 1);
    assert_eq!(replacement.releases.load(Relaxed), 0);
    device.open(BlockOpenMode::EXCLUSIVE, None).unwrap().release();
    assert_eq!(old.releases.load(Relaxed), 2);
    block::del_gendisk(rdev).unwrap();
}

fn named_entry(device: DeviceId) -> Arc<ChrdevEntry> {
    let mut entry = ChrdevEntry::new(device, 1, Arc::new(Backend)).unwrap();
    entry.identity = Some(CharacterDeviceIdentity {
        name: String::from("registration_test"),
        class: String::from("test"),
    });
    Arc::new(entry)
}

fn poll() {
    static INIT: Once<usize> = Once::new();

    assert!(INIT.poll().is_none());
    INIT.call_once(|| 3);
    assert_eq!(INIT.poll().map(|r| *r), Some(3));
}

fn truncate_publishes_i_size_before_two_mapping_invalidations() {
    let inode = VfsInode::new_file_with_address_space_and_flags(
        Arc::new(TruncateOps),
        NodeFlags::ALWAYS_CACHE,
        &TRUNCATE_OPERATIONS,
        VfsInodeInit::new(
            1,
            (PAGE_SIZE_4K * 2) as u64,
            Umode::new(NodeType::RegularFile, NodePermission::default()),
        ),
    );
    let address_space = inode.address_space();
    address_space
        .i_pages
        .filemap_add_folio(super::folio_from_bytes(1, b"cached tail"))
        .unwrap_or_else(|_| panic!("fixture index is absent"));
    let notifier = Arc::new(RecordingNotifier {
        address_space: Arc::downgrade(&address_space),
        observed_sizes: Mutex::new(Vec::new()),
    });
    let _view = address_space.register_view(MappingViewSpec {
        mm_id: 1,
        vma_start: 0x4000,
        vma_len: PAGE_SIZE_4K * 2,
        object_start: 0,
        object_len: PAGE_SIZE_4K * 2,
        kind: MappingViewKind::Private,
        notifier: Some(notifier.clone()),
    });

    inode.set_len(0).expect("truncate succeeds");

    assert_eq!(inode.size(), 0);
    assert_eq!(address_space.nrpages(), 0);
    assert_eq!(*notifier.observed_sizes.lock(), [0, 0]);
}

fn eq(&self, other: &Self) -> bool {
        self.name == other.name
            && match (&self.parent, &other.parent) {
                (Some(parent), Some(other_parent)) => Weak::ptr_eq(parent, other_parent),
                (None, None) => true,
                _ => false,
            }
    }

fn with_pinned_file_page<R>(
        &self,
        index: PageIndex,
        f: impl FnOnce(PinnedFolio) -> VfsResult<R>,
    ) -> VfsResult<R> {
        let _invalidate_guard = self.invalidate_lock.read();
        let offset = index
            .checked_mul(PAGE_SIZE_4K as u64)
            .ok_or(VfsError::BadAddress)?;
        if offset >= self.visible_len()? {
            return Err(VfsError::BadAddress);
        }
        let pin = self
            .i_pages
            .pin_folio_or_create(index, |folio| self.ops.read_folio(self, folio))?;
        f(pin)
    }

fn open(&self, _disk: &block::Gendisk, mode: BlockOpenMode) -> VfsResult<()> {
        self.modes.lock().push(mode);
        if self.fail_open.load(core::sync::atomic::Ordering::Relaxed) {
            Err(VfsError::Io)
        } else {
            Ok(())
        }
    }

fn lookup_open(
        &mut self,
        file: &mut VfsFileBuilder,
        flags: &OpenParams,
        umask: NodePermission,
        cred: &Cred,
    ) -> VfsResult<Path> {
        file.clear_created();

        let name = self
            .last
            .as_ref()
            .map(Qstr::as_str)
            .ok_or(VfsError::InvalidInput)?;
        let dir = self.path.dentry().as_dir()?;
        if !flags.is_exclusive_create() {
            match dir.lookup(name) {
                Ok(entry) => return Ok(self.path.with_dentry(entry)),
                Err(err) if err.canonicalize() == VfsError::NotFound => {}
                Err(err) => return Err(err),
            }
        }

        if !flags.will_create() {
            return Err(VfsError::NotFound);
        }

        match dir.lookup_or_create_with(name, flags.is_exclusive_create(), |candidate| {
            self.path.vfs_create(
                candidate,
                flags.mode(),
                umask,
                flags.is_exclusive_create(),
                cred,
            )
        })? {
            LookupCreateResult::Existing(entry) => Ok(self.path.with_dentry(entry)),
            LookupCreateResult::Created(entry) => {
                file.mark_created();
                // Captured here, under the parent's namespace lock: the created
                // dentry's location is mutable afterwards, so the inotify
                // create event must use this snapshot of where and under what
                // name the entry was born.
                file.set_created_under(self.path.inode(), name);
                Ok(self.path.with_dentry(entry))
            }
        }
    }

fn validates_xattr_names() {
    assert_eq!(
        XattrName::new(vec![b'a'; super::XATTR_NAME_MAX])
            .unwrap()
            .as_bytes()
            .len(),
        super::XATTR_NAME_MAX
    );
    assert!(matches!(
        XattrName::new(vec![b'a'; super::XATTR_NAME_MAX + 1]),
        Err(err) if LinuxError::from(err) == LinuxError::ERANGE
    ));
    assert!(matches!(
        XattrName::new(vec![]),
        Err(err) if LinuxError::from(err) == LinuxError::ERANGE
    ));

    let split = XattrNameRef::from_parts(b"trusted.", b"test").unwrap();
    assert_eq!(split.encoded_len(), b"trusted.test".len());
    assert!(split.is_trusted());
    assert!(matches!(
        XattrNameRef::from_parts(b"user.", b"bad\0name"),
        Err(err) if LinuxError::from(err) == LinuxError::ERANGE
    ));
}

fn new_dir<T>(node: Arc<T>, init: VfsInodeInit) -> Arc<Self>
    where
        T: Any + Send + Sync + InodeOperations,
    {
        let private_data: Arc<dyn Any + Send + Sync> = node.clone();
        let inode_operations: Arc<dyn InodeOperations> = node;
        Self::new_dir_with_inode_operations(
            private_data,
            inode_operations,
            NodeFlags::empty(),
            init,
        )
    }

fn block_on(&self, blocker: Blocker, wake: &mut WakeQueue) -> KResult<()> {
        let mut blocker = blocker.0;
        let mut blocked = BLOCKED_OWNERS.lock();
        // A pending notification still owns the intrusive links. Never allow
        // a second insertion to overwrite their recorded parent relationship.
        let state = self.0.state(&mut blocked);
        assert!(state.blocker.is_none() && state.wait.is_none());
        // A retry may meet a different blocker; descendants must retry too.
        self.0.wake_blocked(&mut blocked, wake);
        // SAFETY: only Waiter::new creates this handle; its range is immutable.
        let request = unsafe { self.0.record() };
        if has_deadlock(&mut blocked, &request, blocker.owner) {
            return Err(LinuxError::EDEADLK.into());
        }
        loop {
            let next = LockNode::find(&blocker.state(&mut blocked).requests, |other| {
                // SAFETY: only this method populates blocked requests, always
                // from a Waiter. Their ranges never become installed/mutable.
                request.conflicts_with(&unsafe { other.record() })
            });
            match next {
                Some(next) => blocker = next,
                None => break,
            }
        }
        self.0.state(&mut blocked).blocker = Some(Arc::downgrade(&blocker));
        blocker
            .state(&mut blocked)
            .requests
            .push_back(self.0.clone());
        blocker.note_push();
        // Indexing depends on the actual blocker, not detection eligibility.
        if blocker.owner.is_posix() {
            blocked
                .entry(self.0.owner)
                .or_default()
                .insert(Arc::as_ptr(&self.0).addr(), self.0.clone());
        }
        Ok(())
    }

fn execute_with_parents_locked<F>(
        &self,
        old_dir_inode: &Arc<VfsInode>,
        new_dir_inode: &Arc<VfsInode>,
        is_cross_directory: bool,
        trap: Option<&Dentry>,
        may_rename_fn: F,
    ) -> VfsResult<()>
    where
        F: FnOnce(&Dentry, &Dentry) -> VfsResult<()>,
    {
        let source = self
            .old_parent
            .lookup_positive_locked(old_dir_inode, self.old_name)?;
        let target = self
            .new_parent
            .lookup_locked(new_dir_inode, self.new_name)?;
        if target.is_negative() && self.flags.contains(RenameFlags::EXCHANGE) {
            return Err(VfsError::NotFound);
        }
        if target.is_really_positive() && self.flags.contains(RenameFlags::NOREPLACE) {
            return Err(VfsError::AlreadyExists);
        }

        self.validate_topology(&source, &target, trap)?;
        if target.is_really_positive() && source.is_same_inode(&target) {
            return Ok(());
        }

        let is_exchange = self.flags.contains(RenameFlags::EXCHANGE);
        let target_is_positive = target.is_really_positive();
        let target_is_directory = target_is_positive && target.is_dir();
        let source_inode = source.vfs_inode();
        let target_inode = target_is_positive.then(|| target.vfs_inode());
        let is_parent_inode = |inode: &Arc<VfsInode>| {
            Arc::ptr_eq(inode, old_dir_inode) || Arc::ptr_eq(inode, new_dir_inode)
        };
        let (first_participant, second_participant) = match (source.is_dir(), target_is_directory) {
            (true, _) => {
                let source_participant = if is_cross_directory && !is_parent_inode(&source_inode) {
                    Some(source_inode)
                } else {
                    None
                };
                let should_lock_target = target_is_positive
                    && (!target_is_directory || is_cross_directory || !is_exchange);
                let target_participant =
                    target_inode.filter(|inode| should_lock_target && !is_parent_inode(inode));
                (source_participant, target_participant)
            }
            (false, true) => {
                let target_participant = target_inode.filter(|inode| {
                    (is_cross_directory || !is_exchange) && !is_parent_inode(inode)
                });
                (target_participant, Some(source_inode))
            }
            (false, false) => match target_inode {
                None => (Some(source_inode), None),
                Some(target_inode) if Arc::ptr_eq(&source_inode, &target_inode) => {
                    (Some(source_inode), None)
                }
                Some(target_inode) if Arc::as_ptr(&source_inode) < Arc::as_ptr(&target_inode) => {
                    (Some(source_inode), Some(target_inode))
                }
                Some(target_inode) => (Some(target_inode), Some(source_inode)),
            },
        };
        let _first_guard = first_participant
            .as_ref()
            .map(|inode| inode.lock_namespace_exclusive());
        let _second_guard = second_participant
            .as_ref()
            .map(|inode| inode.lock_namespace_exclusive());
        self.execute_locked(
            old_dir_inode,
            new_dir_inode,
            &source,
            &target,
            may_rename_fn,
        )
    }

