fn test_replace_lookup_candidate_preserves_replacer() {
    let fs = Arc::new(MockFilesystem);
    let dir = make_dir_entry(fs.clone(), 2, "dir");
    let sb = SuperBlock::new(&MOCK_FILE_SYSTEM_TYPE, &MOCK_SUPER_OPERATIONS, |_| {
