fn truncate_opened(&self, len: u64) -> VfsResult<()> {
        self.check_writable_mount()?;
        if self.is_dir() {
            return Err(VfsError::IsADirectory);
        }
        if !self.is_regular_file() {
            // Only regular files have a truncatable size. Linux returns EINVAL
            // for pipes, sockets, devices and other special files, so refuse
            // the length change at the common truncate boundary instead of
            // letting a resident metadata update publish a fake `i_size`.
            return Err(VfsError::InvalidInput);
        }

        let inode = self.inode();
        if len > self.max_file_size() {
            return Err(VfsError::FileTooLarge);
        }
        if !inode.flags().contains(NodeFlags::NON_CACHEABLE) {
            inode.set_len(len)?;
        } else {
            self.dentry.update_metadata(MetadataUpdate {
                size: Some(len),
                ..Default::default()
            })?;
        }
        Ok(())
    }

fn write(&self) -> SpinRwLockWriteGuard<'_, G, T> {
        let guard_state = G::acquire();
        #[cfg(feature = "stats")]
        let mut did_wait = false;

        while self
            .state
            .compare_exchange(0, WRITE_LOCKED, Ordering::Acquire, Ordering::Relaxed)
            .is_err()
        {
            #[cfg(feature = "stats")]
            {
                did_wait = true;
            }
            core::hint::spin_loop();
        }

        #[cfg(feature = "stats")]
        self.record_write_acquisition(did_wait);
        SpinRwLockWriteGuard {
            lock: self,
            guard_state,
        }
    }

