    let (entry, _) = make_file_entry(fs, 2, None, "leaf");
    let mut updated = entry.metadata();
    updated.nlink = 2;
    updated.size = 11;

    entry
        .update_metadata_after_backing_change(&updated)
        .unwrap();
    assert_eq!(entry.metadata().nlink, 2);
    assert_eq!(entry.metadata().size, 11);

    updated.inode = 3;
    assert_eq!(
        entry.update_metadata_after_backing_change(&updated),
        Err(VfsError::InvalidInput)
    );

    let negative = Dentry::new_negative(None, String::from("missing"));
    assert_eq!(
        negative.update_metadata_after_backing_change(&updated),
        Err(VfsError::NotFound)
    );
}

fn cdev_callbacks_and_backend_destruction_run_without_registry_lock() {
    struct Backend;
    impl DeviceFileOps for Backend {
        fn open(&self, _: &VfsInode, _: &mut VfsFileBuilder) -> VfsResult<()> {
            assert!(CHRDEV_MAP.try_lock().is_some());
            Err(VfsError::Io)
        }
    }
    impl Drop for Backend {
        fn drop(&mut self) {
            assert!(CHRDEV_MAP.try_lock().is_some());
        }
    }
    let first = DeviceId::new(242, 30);
    let registration = TestRegistration::new(first, 1, Arc::new(Backend));
    assert_eq!(
        cdev_add(first, 1, Arc::new(Backend)),
        Err(VfsError::ResourceBusy)
    );
    assert_eq!(
        cdev_add(first, 0, Arc::new(Backend)),
        Err(VfsError::InvalidInput)
    );
    let inode = test_character_inode(first);
    let mount = crate::Mount::new_root(&crate::nullfs::new_superblock());
    let dentry = crate::Dentry::new_file_from_inode(inode, None, String::from("range"));
    let path = crate::Path::new(mount, dentry);
    assert_eq!(
        VfsFileBuilder::allocate(crate::OpenFlags::READ_WRITE, kcred::initial_cred())
            .unwrap()
            .vfs_open(path)
            .err(),
        Some(VfsError::Io)
    );
    drop(registration);
}

fn lookup_no_follow(path: &Path, name: &str) -> VfsResult<Path> {
    use crate::path::{DOT, DOTDOT};

    Ok(match name {
        DOT => path.clone(),
        DOTDOT => path.parent().unwrap_or_else(|| path.clone()),
        _ => lookup_child_in_mount(path, name)?.resolve_final_mount(),
    })
}

