fn fill_next_extent(
        &mut self,
        logical: u64,
        physical: u64,
        length: u64,
        mut flags: FiemapExtentFlags,
    ) -> VfsResult<bool> {
        if length == 0
            || logical.checked_add(length).is_none()
            || physical.checked_add(length).is_none()
        {
            return Err(VfsError::InvalidInput);
        }
        if flags.contains(FiemapExtentFlags::DELALLOC) {
            flags.insert(FiemapExtentFlags::UNKNOWN);
        }
        if flags.contains(FiemapExtentFlags::DATA_ENCRYPTED) {
            flags.insert(FiemapExtentFlags::ENCODED);
        }
        if flags.intersects(FiemapExtentFlags::DATA_INLINE | FiemapExtentFlags::DATA_TAIL) {
            flags.insert(FiemapExtentFlags::NOT_ALIGNED);
        }

        if self.extents_max == 0 {
            self.extents_mapped = self
                .extents_mapped
                .checked_add(1)
                .ok_or(VfsError::OutOfRange)?;
            return Ok(!flags.contains(FiemapExtentFlags::LAST));
        }
        if self.extents_mapped >= self.extents_max {
            return Ok(false);
        }

        self.writer
            .write_extent(self.extents_mapped, logical, physical, length, flags)?;
        self.extents_mapped = self
            .extents_mapped
            .checked_add(1)
            .ok_or(VfsError::OutOfRange)?;
        Ok(self.extents_mapped < self.extents_max && !flags.contains(FiemapExtentFlags::LAST))
    }

fn splice_write(
        &self,
        nonblocking: bool,
        scratch: &mut [u8],
        mut read_fn: impl FnMut(&mut [u8]) -> KResult<usize>,
    ) -> KResult<usize> {
        if scratch.is_empty() {
            return Ok(0);
        }
        let result = block_on(poll_file_io(self, IoEvents::OUT, nonblocking, || {
            let mut state = self.state.lock();
            if state.readers == 0 {
                drop(state);
                let _ = send_sig_current(Signo::SIGPIPE);
                return Ok(Err(KError::BrokenPipe));
            }
            let count = scratch.len().min(state.available());
            if count == 0 {
                return Err(KError::WouldBlock);
            }
            let result = read_fn(&mut scratch[..count]);
            if let Ok(read) = result {
                if read > count {
                    return Ok(Err(KError::Io));
                }
                state.write_from(&scratch[..read]);
            }
            Ok(result)
        }))?;
        if matches!(result, Ok(count) if count > 0) {
            ktask::with_wake_sync(|| self.rd_wait.wake());
        }
        result
    }

fn stampede_once() {
    static O: Once = Once::new();
    static RUN: AtomicBool = AtomicBool::new(false);

    let (tx, rx) = channel();
    let mut ts = Vec::new();
    for _ in 0..10 {
        let tx = tx.clone();
        ts.push(thread::spawn(move || {
            for _ in 0..4 {
                thread::yield_now()
            }
            O.call_once(|| {
                assert!(!RUN.load(Ordering::Acquire));
                RUN.store(true, Ordering::Release);
            });
            assert!(RUN.load(Ordering::Acquire));
            tx.send(()).unwrap();
        }));
    }

    O.call_once(|| {
        assert!(!RUN.load(Ordering::Acquire));
        RUN.store(true, Ordering::Release);
    });
    assert!(RUN.load(Ordering::Acquire));

    for _ in 0..10 {
        rx.recv().unwrap();
    }

    for t in ts {
        t.join().unwrap();
    }
}

fn completed_folio_read_survives_eof_growth() {
    let inode = read_inode(&GROWING_READ_OPS, 17);
    let mapping = inode.address_space();
    let mut output = [0xff; PAGE_SIZE_4K];
    let mut iter = iov_iter_kvec_dest(&mut output);
    assert_eq!(mapping.read_from_page_cache(&mut iter, 0), Ok(PAGE_SIZE_4K));
    assert!(output[..17].iter().all(|byte| *byte == 0x6b));
    assert!(output[17..].iter().all(|byte| *byte == 0));
}

fn failed_try_lock_restores_state() {
    let m = TestSpinIrq::new(());
    let a = m.lock();
    assert_eq!(IRQ_CNT.load(Ordering::Relaxed), 1);

    let b = m.try_lock();
    assert!(b.is_none());
    assert_eq!(IRQ_CNT.load(Ordering::Relaxed), 1);

