fn walk_path_component(
        &mut self,
        last_type: LastType,
        name: &str,
        walk_component: WalkComponent,
        cred: &Cred,
    ) -> VfsResult<()> {
        if last_type == LastType::Norm {
            self.last_type = LastType::Norm;
            return match walk_component {
                WalkComponent::More => self.walk_component(name, WalkComponent::More, cred),
                WalkComponent::Final => {
                    self.hash_name(name);
                    Ok(())
                }
            };
        }
        self.last_type = last_type;
        self.hash_name(name);
        if walk_component == WalkComponent::More {
            self.handle_dots(last_type);
        }
        Ok(())
    }

fn on_miss(
        &mut self,
        index: PageIndex,
        request_pages: u64,
        history: impl FnOnce(u64) -> u64,
    ) -> (Range<PageIndex>, Option<PageIndex>) {
        let max = self.ra_pages;
        if max == 0 {
            return (index..index + 1, None);
        }
        let sequential = self.prev_pos_bytes.is_some_and(|pos| {
            index
                .checked_sub(pos / PAGE_SIZE_4K as u64)
                .is_some_and(|delta| delta <= 1)
        });
        if index == 0 || request_pages > max || sequential {
            self.start = index;
            self.size_pages = Self::initial_size(request_pages, max);
            self.async_size_pages = if self.size_pages > request_pages {
                self.size_pages - request_pages
            } else {
                self.size_pages / 2
            };
        } else {
            let mut contiguous = history(max);
            if contiguous <= request_pages {
                // A small random miss must not overwrite a sequential stream's history.
                return (index..index.saturating_add(request_pages.min(max)), None);
            }
            if contiguous == index {
                contiguous *= 2;
            }
            self.start = index;
            self.size_pages = contiguous.saturating_add(request_pages).min(max);
            self.async_size_pages = 1;
        }
        self.window()
    }

fn new_with_inode_attribute_operations<T>(
        node: Arc<T>,
        flags: NodeFlags,
        address_space_operations: &'static dyn AddressSpaceOperations,
        mut init: VfsInodeInit,
    ) -> Arc<Self>
    where
        T: Any + Send + Sync + InodeOperations + FileOperations + InodeAttributeOperations,
    {
        let node_type = init.node_type();
        let private_data: Arc<dyn Any + Send + Sync> = node.clone();
        let inode_operations: Arc<dyn InodeOperations> = node.clone();
        let attribute_operations: Arc<dyn InodeAttributeOperations> = node.clone();
        let (file_operations, address_space_operations) = match node_type {
            NodeType::Directory => {
                let file_operations: Arc<dyn FileOperations> = node.clone();
                (Some(file_operations), empty_address_space_operations())
            }
            NodeType::RegularFile | NodeType::Unknown => {
                let file_operations: Arc<dyn FileOperations> = node.clone();
                (Some(file_operations), address_space_operations)
            }
            NodeType::Symlink => (None, address_space_operations),
            NodeType::CharacterDevice
            | NodeType::BlockDevice
            | NodeType::Fifo
            | NodeType::Socket => {
                let (file_operations, rdev) = init_special_inode(node_type, init.rdev);
                init.rdev = rdev;
                (file_operations, empty_address_space_operations())
            }
        };
        Self::from_parts_with_attribute_operations(
            InodeParts {
                private_data,
                inode_operations,
                file_operations,
                flags,
                address_space_operations,
                init,
            },
            attribute_operations,
        )
    }

fn test_pivot_root_swaps_visible_root_and_relocates_old() {
    let root_fs = mock_filesystem(StatFsFlags::empty());
    let new_root_fs = mock_filesystem(StatFsFlags::empty());
    let namespace = MntNamespace::build_initial_mount_tree(&root_fs).unwrap();
    let old_visible_root = namespace.visible_root_path();
    let old_root_mount = old_visible_root.mount().clone();
    let cred = kcred::initial_cred();

    // New root: a fresh filesystem mounted at a directory of the old root
    // (the OCI pattern mounts the container rootfs there and binds it).
    let mnt_dir = lookup_child_in_mount(&old_visible_root, "mnt").unwrap();
    let new_mnt = namespace.attach(&mnt_dir, &new_root_fs).unwrap();

    // put_old lives inside the new root's own filesystem (`/.pivot_root`).
    let put_old = new_mnt
        .root_path()
        .mkdir("oldroot", NodePermission::default(), &cred)
        .unwrap();

    namespace
        .pivot_root(
            &new_mnt.root_path(),
            &put_old,
            &namespace.visible_root_path(),
        )
        .unwrap();

    // `/` now resolves to the new root's filesystem.
    assert!(Arc::ptr_eq(namespace.visible_root_path().mount(), &new_mnt));
    // The old root is reachable at put_old, inside the new root.
    let relocated = lookup_child_in_mount(&new_mnt.root_path(), "oldroot")
        .unwrap()
        .resolve_final_mount();
    assert!(Arc::ptr_eq(relocated.mount(), &old_root_mount));
    // The structural root resolves through the new mount without gaps.
    assert!(Arc::ptr_eq(
        namespace.root_path().resolve_final_mount().mount(),
        &new_mnt
    ));
    assert!(!Arc::ptr_eq(
        namespace.visible_root_path().mount(),
        &old_root_mount
    ));
}

fn unlink_with_pathname_tracked(
        &self,
        name: &str,
        has_trailing_slash: bool,
        cred: &Cred,
    ) -> VfsResult<Option<RemovedEntry>> {
        self.check_writable_mount()?;
        // Captured under the namespace lock, from the dentry the removal
        // actually unlinks -- the event identity must describe that object,
        // not whatever a separate lookup saw before the lock was taken.
        let mut removed = None;
        self.dentry.as_dir()?.unlink_with(name, |victim| {
            if has_trailing_slash {
                return Err(VfsError::NotADirectory);
            }
            self.may_modify_directory(cred)?;
            let victim_path = self.with_dentry(victim.clone());
            self.check_sticky(&victim_path, cred)?;
            victim_path.check_not_mountpoint()?;
            // Pre-unlink `nlink`: the FS decrements it when the unlink below
            // runs, and the retired-or-survives decision is about that move.
            // This one field must be authoritative, so it comes from `getattr`
            // -- a backend (9p) may leave the cached copy stale -- and a
            // failure means no retirement decision is taken at all rather than
            // a wrong one. Parent and victim references pin the event objects
            // independently of the mount used to reach them.
            removed = Some(RemovedEntry {
                parent: self.inode(),
                name: alloc::string::String::from(name),
                // Authoritative when the backend answers, cached otherwise:
                // a removal whose link count cannot be decided would leave the
                // watch pinned to a dead object forever, which is worse than
                // acting on a possibly stale count.
                victim_nlink: Some(
                    victim_path
                        .getattr()
                        .map_or_else(|_| victim_path.identity().nlink, |meta| meta.nlink),
                ),
                victim_dentry: victim.clone(),
            });
            Ok(())
        })?;
        Ok(removed)
    }

fn try_call_once_error_allows_retry() {
    let once = Once::<u32>::new();

    let result = once.try_call_once(|| Err::<u32, &'static str>("retry"));
    assert_eq!(result, Err("retry"));
    assert!(!once.is_completed());
    assert!(once.get().is_none());
    assert!(once.poll().is_none());

    let value = once.call_once(|| 11);
    assert_eq!(*value, 11);
    assert!(once.is_completed());
}

fn cdev_add_named(
    device: DeviceId,
    name: String,
    class: String,
    operations: Arc<dyn DeviceFileOps>,
) -> VfsResult<CharacterDeviceRegistration> {
    if !valid_component(&name) || !valid_component(&class) {
        return Err(VfsError::InvalidInput);
    }
    let mut entry = ChrdevEntry::new(device, 1, operations)?;
    entry.identity = Some(CharacterDeviceIdentity { name, class });
    let entry = Arc::new(entry);
    let subscribers = {
        let mut registry = CHRDEV_MAP.lock();
        registry.add(&entry)?;
        registry.subscribers.clone()
    };
    for subscriber in subscribers {
        subscriber();
    }
    Ok(CharacterDeviceRegistration(entry))
}

fn uncache_lookup_candidate(&self, name: &str, candidate: &Dentry) {
        let mut children = self.0.children.lock();
        let is_candidate = children
            .get(name)
            .is_some_and(|entry| Weak::ptr_eq(entry, &Arc::downgrade(&candidate.0)));
        if is_candidate {
            children.remove(name);
        }
        drop(children);
        if is_candidate && let Some(super_block) = candidate.super_block() {
            super_block.uncache_dentry(candidate);
        }
    }

fn instantiate(&self, inode: Arc<VfsInode>) -> VfsResult<()> {
        let mut attached = self.0.inode.lock();
        if attached.is_some() {
            return Err(VfsError::AlreadyExists);
        }
        if !inode.add_dentry_alias(self) {
            return Err(VfsError::InvalidInput);
        }
        let mut flags = self.0.flags.lock();
        let retained =
            *flags & (DentryFlags::PAR_LOOKUP | DentryFlags::DONTCACHE | DentryFlags::PERSISTENT);
        *flags = DentryFlags::for_inode(&inode) | retained;
        drop(flags);
        *attached = Some(inode.clone());
        drop(attached);
        if let Some(super_block) = self.super_block() {
            inode.bind_super_block(&super_block);
        }
        Ok(())
    }

fn remove_xattr(&self, name: &XattrName, cred: &Cred) -> VfsResult<()> {
        self.check_writable_mount()?;
        let inode = self.inode();
        check_xattr_permission(&inode, name, XattrAccess::Write, cred)?;
        let _data_guard = inode.lock_data();
        inode.remove_xattr(self.dentry(), name)
    }

fn resize(&self, new_size: usize) -> KResult<()> {
        let pages = new_size
            .checked_add(PAGE_SIZE_4K - 1)
            .ok_or(KError::InvalidInput)?
            / PAGE_SIZE_4K;
        let pages = pages
            .max(1)
            .checked_next_power_of_two()
            .ok_or(KError::InvalidInput)?;
        let new_size = pages
            .checked_mul(PAGE_SIZE_4K)
            .ok_or(KError::InvalidInput)?;
        if new_size > PIPE_MAX_SIZE {
            return Err(KError::OperationNotPermitted);
        }

        let should_wake_writers = {
            let mut state = self.state.lock();
            let old_size = state.capacity;
            if new_size == old_size {
                return Ok(());
            }
            if new_size < state.buffer.len() {
                return Err(KError::ResourceBusy);
            }

            let mut new_buffer = VecDeque::with_capacity(new_size);
            new_buffer.extend(state.buffer.iter().copied());
            state.buffer = new_buffer;
            state.capacity = new_size;
            new_size > old_size
        };

        if should_wake_writers {
            self.wr_wait.wake();
        }
        Ok(())
    }

fn link(&self, name: &str, source: &Self, cred: &Cred) -> VfsResult<Self> {
        self.dentry
            .as_dir()?
            .create_exclusive_with(name, |candidate| self.vfs_link(candidate, source, cred))
            .map(|entry| self.with_dentry(entry))
    }

