fn read_iter(&self, iocb: &mut Kiocb<'_>, iter: &mut IovIterDest<'_>) -> VfsResult<usize> {
        let mut total = 0usize;
        let mut chunk = [0u8; memaddr::PAGE_SIZE_4K];
        while iter.count() != 0 {
            let want = chunk.len().min(iter.count());
            if want == 0 {
                break;
            }
            let read = match self.read(iocb.file(), &mut chunk[..want], iocb.ki_pos()) {
                Ok(read) => read,
                Err(_) if total != 0 => break,
                Err(err) => return Err(err),
            };
            if read == 0 {
                break;
            }
            let copied = iter.copy_to_iter(&chunk[..read])?;
            total += copied;
            iocb.advance(copied);
            if copied < read || read < want {
                break;
            }
        }
        Ok(total)
    }

fn registry_lookup_defers_final_superblock_drop_until_after_unlock() {
    let backend = Arc::new(OpenLifecycleDevice {
        modes: crate::Mutex::new(alloc::vec::Vec::new()),
        releases: AtomicUsize::new(0),
        fail_open: core::sync::atomic::AtomicBool::new(false),
    });
    let device = block::Gendisk::alloc(
        String::from("lookup-drop"),
        0,
        0,
        1,
        Box::new(backend.clone()),
    )
    .unwrap()
    .part0();
    let registry = super_block_registry();
    let sb = registry
        .get_or_try_init_bdev(
            &BDEV_TEST_FILE_SYSTEM_TYPE,
            device.clone(),
            SuperBlockFlags::empty(),
            |sb| initialize_test_bdev(sb, &BDEV_TEST_SUPER_OPERATIONS),
        )
        .unwrap();
    let mut live_refs = alloc::vec::Vec::new();
