fn assert_other_metadata_unchanged(actual: &Metadata, cached: &Metadata) -> TestResult {
    assert_eq!(actual.device, cached.device);
    assert_eq!(actual.inode, cached.inode);
    assert_eq!(actual.mode, cached.mode);
    assert_eq!(actual.uid, cached.uid);
    assert_eq!(actual.gid, cached.gid);
    assert_eq!(actual.size, cached.size);
    // getattr uses the node's block_size (0 for this directory), whereas
    // metadata() reconstructs 1 << block_bits (1). Compare only same-source
    // fields here; their pre-existing normalization difference is unrelated
    // to the dynamic link-count callback.
    assert_eq!(actual.blocks, cached.blocks);
    assert_eq!(actual.rdev, cached.rdev);
    assert_eq!(actual.atime, cached.atime);
    assert_eq!(actual.mtime, cached.mtime);
    assert_eq!(actual.ctime, cached.ctime);
    TestResult::Ok
}

fn write_iter(&self, iocb: &mut Kiocb<'_>, iter: &mut IovIterSource<'_>) -> VfsResult<usize> {
        const MAX_COMMAND_SIZE: usize = 4096;
        let count = iter.count();
        if count == 0 {
            return Ok(0);
        }
        if count > MAX_COMMAND_SIZE {
            return Err(VfsError::FileTooLarge);
        }
        let mut command = alloc::vec![0; count];
        let mut copied = 0;
        while copied < count {
            let read = match iter.copy_from_iter(&mut command[copied..]) {
                Ok(read) => read,
                Err(error) => {
                    iter.revert(copied)?;
                    return Err(error);
                }
            };
            if read == 0 {
                iter.revert(copied)?;
                return Err(VfsError::BadAddress);
            }
            copied += read;
        }
        let written = match self.write(iocb.file(), &command, iocb.ki_pos()) {
            Ok(written) => written,
            Err(error) => {
                iter.revert(count)?;
                return Err(error);
            }
        };
        if written > count {
            iter.revert(count)?;
            return Err(VfsError::InvalidData);
        }
        iter.revert(count - written)?;
        if written == 0 {
            return Err(VfsError::WriteZero);
        }
        iocb.advance(written);
        Ok(written)
    }

fn read_with(
        &self,
        nonblocking: bool,
        mut read: impl FnMut(&mut PipeState) -> KResult<usize>,
    ) -> KResult<usize> {
        block_on(poll_file_io(self, IoEvents::IN, nonblocking, || {
            let (read, has_writers) = {
                let mut state = self.state.lock();
                let read = read(&mut state)?;
                (read, state.writers > 0)
            };

            if read > 0 {
                ktask::with_wake_sync(|| self.wr_wait.wake());
                Ok(read)
            } else if !has_writers {
                Ok(0)
            } else {
                Err(KError::WouldBlock)
            }
        }))
    }

