fn wake_blocked(&self, blocked: &mut MutexGuard<'_, BlockedOwners>, wake: &mut WakeQueue) {
        while let Some(waiter) = self.state(blocked).requests.pop_front() {
            self.note_pop();
            waiter.state(blocked).blocker = None;
            remove_blocked_owner(blocked, &waiter);
            // The registration moves with its existing request node. A
            // pending notification keeps `wait` populated until dequeue, so
            // even a spurious poll cannot reuse these links prematurely.
            if waiter.state(blocked).wait.is_some() {
                wake.0.push_back(waiter);
            }
        }
        debug_assert_eq!(self.waiter_count.load(Ordering::Relaxed), 0);
    }

fn poll(&self) -> Option<&T> {
        loop {
            // Check current initialization state
            let current_state = self.state.load(Ordering::Acquire);

            match current_state {
                Status::Uninitialized => return None,
                Status::Initializing => {
                    // Spin while another thread is initializing
                    core::hint::spin_loop();
                }
                Status::Ready => {
                    // SAFETY: `Status::Ready` is only observable after the
                    // initialized value has been published to `storage`.
                    return Some(unsafe { self.get_value_unchecked() });
                }
                #[expect(
                    clippy::panic,
                    reason = "CG-021-no-panic-on-reachable-failure: A previous initializer \
                              panicked and left no value; like std's poisoned Once and LazyLock, \
                              the value can never be produced"
                )]
                Status::Failed => {
                    panic!("OnceCell was contaminated by a previous panic")
                }
            }
        }
    }

