fn mkdir_at_entry(
        &self,
        root: &Path,
        base: &Path,
        permission: NodePermission,
        umask: NodePermission,
        cred: &Cred,
    ) -> VfsResult<CreatedEntry> {
        let (parent, last, _) = self
            .parent_at(root, base, LookupIntent::Open, cred)?
            .into_create()?;
        let name = last.as_str();

        let path = parent
            .dentry()
            .as_dir()?
            .create_exclusive_with(name, |candidate| {
                parent.vfs_mkdir(candidate, permission, umask, cred)
            })
            .map(|entry| parent.with_dentry(entry))?;
        Ok(CreatedEntry {
            path,
            name: String::from(name),
            parent: parent.inode(),
        })
    }

fn readahead_pages(&self) -> usize {
        if self.node_type() == NodeType::BlockDevice {
            return block::lookup_block_device(self.rdev())
                .map_or(block::BackingDevInfo::DEFAULT_RA_PAGES, |device| {
                    device.disk().backing_dev_info().readahead_pages()
                });
        }
        self.super_block()
            .ok()
            .and_then(|sb| {
                sb.block_device()
                    .map(|device| device.disk().backing_dev_info().readahead_pages())
            })
            .unwrap_or(block::BackingDevInfo::DEFAULT_RA_PAGES)
    }

fn new(record: FileLock) -> Self {
        Self {
            owner: record.owner,
            kind: record.kind,
            pid: record.pid,
            bounds: UnsafeCell::new(record.bounds),
            links: LinkedListLink::new(),
            blocked: UnsafeCell::new(FileLockBlocked {
                blocker: None,
                requests: LinkedList::new(LockAdapter::new()),
                wait: None,
            }),
            waiter_count: AtomicUsize::new(0),
        }
    }

fn test(&self, request: &FileLock) -> Option<FileLock> {
        let state = self.state.lock();
        state.posix.iter().find(|lock| {
            if request.kind == FileLockType::Unlock {
                request.owner == lock.owner && request.overlaps(lock)
            } else {
                request.conflicts_with(lock)
            }
        })
    }

fn writable_open_lifetime_updates_inode_write_count() {
    let tree = test_tree();
    let inode = tree.target.inode().clone();
    let file_ops = inode.downcast::<TestFile>().unwrap();

    let first = dentry_open(
        tree.target.clone(),
        OpenFlags::WRITE_ONLY.bits(),
        kcred::initial_cred(),
    )
    .unwrap();
    assert_eq!(inode.write_count(), 1);
    let second = dentry_open(
        tree.target.clone(),
        OpenFlags::WRITE_ONLY.bits(),
        kcred::initial_cred(),
    )
    .unwrap();
    assert_eq!(inode.write_count(), 2);

    drop(first);
    assert_eq!(inode.write_count(), 1);
    {
        let release_write_counts = file_ops.release_write_counts.lock();
        assert_eq!(release_write_counts.as_slice(), &[2]);
    }
    drop(second);
    assert_eq!(inode.write_count(), 0);
    let release_write_counts = file_ops.release_write_counts.lock();
    assert_eq!(release_write_counts.as_slice(), &[2, 1]);
}

