fn read_dir_at(
        &self,
        dir: &Dentry,
        offset: u64,
        sink: &mut dyn DirEntrySink,
    ) -> VfsResult<usize> {
        let children = [DOT, DOTDOT]
            .into_iter()
            .map(Cow::Borrowed)
            .chain(self.ops.child_names()?);

        let mut count = 0;
        for (i, name) in children.enumerate().skip(offset as usize) {
            let metadata = match name.as_ref() {
                DOT => dir.metadata(),
                DOTDOT => dir
                    .parent()
                    .map_or_else(|| dir.metadata(), |parent| parent.metadata()),
                other => {
                    let entry = dir.lookup(other)?;
                    entry.metadata()
                }
            };
            if !sink.accept(
                &name,
                metadata.inode,
                metadata.mode.node_type(),
                i as u64 + 1,
            ) {
                break;
            }
            count += 1;
        }

        Ok(count)
    }

fn register_poll(
        &self,
        _: &VfsFile,
        context: &mut PollContext<'_>,
        events: IoEvents,
    ) -> Result<(), PollRegisterError> {
        if self.reject_registration.load(Ordering::Relaxed) {
            return Err(PollRegisterError::InvalidState);
        }
        if events.contains(IoEvents::IN) {
            context.register(&self.waiters)?;
        }
        Ok(())
    }

fn interrupted_small_pipe_write_remains_atomic() {
    let pipe = PipeObject::new_anonymous();
    pipe.resize(PIPE_BUF).unwrap();
    assert_eq!(
        pipe.write(true, false, &vec![0x21; PIPE_BUF - 2]),
        Ok(PIPE_BUF - 2)
    );
    let task = ktask::current();
    task.interrupt();
    let result = pipe.write(false, true, b"abcd");
    task.clear_interrupt();
    assert_eq!(result, Err(KError::IoWaitInterrupted));
    assert_eq!(pipe.readable_len(), PIPE_BUF - 2);
    let mut output = vec![0; PIPE_BUF];
    assert_eq!(pipe.read(true, &mut output), Ok(PIPE_BUF - 2));
    assert!(output[..PIPE_BUF - 2].iter().all(|byte| *byte == 0x21));
}

fn may_open(
        path: &Path,
        acc_mode: AccMode,
        open_flags: OpenFlags,
        cred: &Cred,
    ) -> VfsResult<MayOpenResult> {
        let f_mode = FMode::from_open_flags(open_flags);
        if f_mode.contains(FMode::PATH) || open_flags.contains(OpenFlags::PATH) {
            return Ok(MayOpenResult { truncate: false });
        }

        if d_is_symlink(path.dentry()) {
            return Err(VfsError::FilesystemLoop);
        }
        if open_flags.contains(OpenFlags::DIRECTORY) && !d_is_dir(path.dentry()) {
            return Err(VfsError::NotADirectory);
        }

        let node_type = d_inode(path.dentry()).node_type();
        let truncate =
            open_flags.contains(OpenFlags::TRUNCATE) && node_type == NodeType::RegularFile;
        if d_is_dir(path.dentry())
            && (acc_mode.requires_write() || open_flags.contains(OpenFlags::TRUNCATE))
        {
            return Err(VfsError::IsADirectory);
        }
        if matches!(node_type, NodeType::CharacterDevice | NodeType::BlockDevice)
            && path.mount().flags().contains(MountFlags::NODEV)
        {
            return Err(VfsError::PermissionDenied);
        }
        if f_mode.contains(FMode::EXEC)
            && path.mount().flags().contains(MountFlags::NOEXEC)
            && node_type == NodeType::RegularFile
        {
            return Err(VfsError::PermissionDenied);
        }
        if acc_mode.requires_write() || open_flags.contains(OpenFlags::APPEND) || truncate {
            path.check_writable_mount()?;
        }
        path.permission(crate::Permission::MAY_OPEN | acc_mode.permission(), cred)?;
        Ok(MayOpenResult { truncate })
    }

