fn from_access_mode(access_mode: u32) -> Self {
        match access_mode {
            O_RDONLY => Self(Permission::MAY_READ),
            O_WRONLY => Self(Permission::MAY_WRITE),
            O_RDWR => Self(Permission::MAY_READ | Permission::MAY_WRITE),
            _ => Self(Permission::MAY_READ | Permission::MAY_WRITE),
        }
    }

fn compare_exchange(
            &self,
            old: Status,
            new: Status,
            success: Ordering,
            failure: Ordering,
        ) -> Result<Status, Status> {
            // Try to atomically swap old state with new state
            let old_raw = old as u8;
            let new_raw = new as u8;
            let result = self.0.compare_exchange(old_raw, new_raw, success, failure);

            // Convert result values back to Status enum
            match result {
                Ok(current) => Ok(Status::from_raw(current)),
                Err(actual) => Err(Status::from_raw(actual)),
            }
        }

fn get_link(
        &self,
        _dentry: Option<&crate::Dentry>,
        _inode: &crate::VfsInode,
        _done: &mut crate::DelayedCall,
    ) -> VfsResult<String> {
        let data = self.ops.read_all()?;
        core::str::from_utf8(&data)
            .map(ToOwned::to_owned)
            .map_err(|_| VfsError::InvalidData)
    }

fn swap_locations(left: &Dentry, right: &Dentry) {
        if left.as_ptr() < right.as_ptr() {
            let mut left_location = left.0.location.write();
            let mut right_location = right.0.location.write();
            mem::swap(&mut *left_location, &mut *right_location);
        } else {
            let mut right_location = right.0.location.write();
            let mut left_location = left.0.location.write();
            mem::swap(&mut *left_location, &mut *right_location);
        }
    }

fn rename_with<F>(
        &self,
        src_name: &str,
        dst_dir: &Self,
        dst_name: &str,
        flags: RenameFlags,
        may_rename_fn: F,
    ) -> VfsResult<()>
    where
        F: FnOnce(&Dentry, &Dentry) -> VfsResult<()>,
    {
        if flags.has_conflicting_modes() {
            return Err(VfsError::InvalidInput);
        }
        self.as_dir()?;
        dst_dir.as_dir()?;
        Self::verify_child_name(src_name)?;
        Self::verify_child_name(dst_name)?;
        let supported_flags = RenameFlags::NOREPLACE | RenameFlags::EXCHANGE;
        if !supported_flags.contains(flags) {
            return Err(VfsError::InvalidInput);
        }
        RenameData {
            old_parent: self,
            old_name: src_name,
            new_parent: dst_dir,
            new_name: dst_name,
            flags,
        }
        .execute(may_rename_fn)
    }

fn buffered_read_stops_on_short_or_zero_copy() {
    for limit in [0, 23] {
        let inode = read_inode(&READ_OPS, PAGE_SIZE_4K * 40);
        let mapping = inode.address_space();
        let mut sink = ShortSink { copied: 0, limit };
        let mut iter = iov_iter_dest(&mut sink);
        assert_eq!(mapping.read_from_page_cache(&mut iter, 0), Ok(limit));
        assert_eq!(sink.copied, limit);
        // A short copy retains completed prefetch within the 128 KiB window.
        assert_eq!(mapping.nrpages(), 32);
    }
}

fn open_character_device(
    inode: &VfsInode,
    file: &mut VfsFileBuilder,
    ops: Arc<dyn DeviceFileOps>,
) -> VfsResult<()> {
    // Linux derives the device type from the inode mode
    // (`devcgroup_inode_permission`), so an open reports READ/WRITE plus the
    // node's type half of `access_type`.
    let access = device_access_for_mode(file)
        | match inode.node_type() {
            NodeType::BlockDevice => DeviceAccess::TYPE_BLOCK,
            _ => DeviceAccess::TYPE_CHAR,
        };
    check_device_access(inode.rdev(), access)?;
    let fops = Arc::new(ChrdevFileOperations::new(ops));
    file.replace_fops(fops.clone());
    fops.open(inode, file)
}

