fn bind_super_block(&self, super_block: &Arc<SuperBlock>) {
        let inode = self.0.inode.lock().clone();
        if let Some(inode) = &inode {
            inode.bind_super_block(super_block);
        }
        let requested = Arc::downgrade(super_block);
        let bound = self.0.super_block.call_once(|| requested.clone());
        // Linux assigns `d_sb` at allocation and never rebinds a dentry.
        assert!(
            Weak::ptr_eq(bound, &requested),
            "one VFS dentry identity must not belong to multiple superblocks"
        );
        if let Some(default_operations) = super_block.default_dentry_operations() {
            let installed = self.0.operations.call_once(|| default_operations);
            assert!(
                core::ptr::eq(*installed, default_operations),
                "one VFS dentry identity must not change operation tables"
            );
        }

        // Only publish children into the dcache when they are cacheable,
        // mirroring `insert_cache`. `bind_super_block` must not defeat
        // `NON_CACHEABLE` filesystems (e.g. procfs), where every child dentry
        // would otherwise be retained by the superblock dcache forever.
        // Negative dentries carry no inode; `can_cache_children` requires one,
        // so check the already-held inode's flags directly instead.
        let cache_children = inode
            .as_ref()
            .is_some_and(|inode| !inode.flags().contains(NodeFlags::NON_CACHEABLE));
        let children: Vec<_> = self.0.children.lock().values().cloned().collect();
        for child in children {
            if let Some(child) = child.upgrade().map(Dentry) {
                child.bind_super_block(super_block);
                if cache_children && child.can_cache_as_child() {
                    super_block.cache_dentry(child);
                }
            }
        }
    }

fn try_read(&self) -> Option<SpinRwLockReadGuard<'_, G, T>> {
        let guard_state = G::acquire();
        let state = self.state.load(Ordering::Relaxed);
        let acquired = state & WRITE_LOCKED == 0
            && state != READER_MASK
            && self
                .state
                .compare_exchange(state, state + 1, Ordering::Acquire, Ordering::Relaxed)
                .is_ok();

        if acquired {
            #[cfg(feature = "stats")]
            self.record_read_acquisition(false);
            Some(SpinRwLockReadGuard {
                lock: self,
                guard_state,
            })
        } else {
            G::release(guard_state);
            None
        }
    }

fn read_folio(&self, mapping: &AddressSpace, mut folio: FolioRead) -> VfsResult<()> {
        let inode = mapping.inode().ok_or(VfsError::InvalidInput)?;
        let data = inode.private::<MockFileOps>()?.data.lock();
        let start = folio
            .index()
            .checked_mul(PAGE_SIZE_4K as u64)
            .and_then(|offset| usize::try_from(offset).ok())
            .ok_or(VfsError::InvalidInput)?;
        if start >= data.len() {
            folio.data().fill(0);
            return folio.complete(Ok(()));
        }
        let buf = folio.data();
        let count = buf.len().min(data.len() - start);
        buf[..count].copy_from_slice(&data[start..start + count]);
        buf[count..].fill(0);
        folio.complete(Ok(()))
    }

fn write_iter_with_checks(
        &self,
        iocb: &mut Kiocb<'_>,
        iter: &mut IovIterSource<'_>,
        checks: impl FnOnce(u64, &mut usize) -> VfsResult<()>,
    ) -> VfsResult<usize> {
        let inode = self.inode().ok_or(VfsError::InvalidInput)?;
        let _data_guard = inode.lock_data();
        let mut count = iter.count();
        self.generic_write_check_limits(iocb, &mut count)?;
        if count != 0 {
            checks(iocb.ki_pos(), &mut count)?;
        }
        iter.truncate(count);
        let count = iter.count();
        if count == 0 {
            return Ok(0);
        }

        // Filesystems may defer persistence, but writes must publish timestamps
        // before taking folio locks or exposing modified data.
        iocb.file().file_update_time()?;
        let written = self.perform_write(iocb.ki_pos(), iter, count)?;
        iocb.advance(written);
        Ok(written)
    }

fn character_replacement_opens_once_and_releases_only_final_backend() {
    for can_read in [false, true] {
        for can_write in [false, true] {
            let backend = CharacterBackend::new(can_read, can_write, false);
            let multiplexer = Arc::new(CharacterMultiplexer {
                backend: backend.clone(),
                opens: AtomicUsize::new(0),
                releases: AtomicUsize::new(0),
            });
            let file = open_test_character(multiplexer.clone()).unwrap();
            assert_eq!(multiplexer.opens.load(Ordering::Relaxed), 1);
            assert_eq!(backend.opens.load(Ordering::Relaxed), 1);
            assert_eq!(file.mode().contains(FMode::CAN_READ), can_read);
            assert_eq!(file.mode().contains(FMode::CAN_WRITE), can_write);
            let alias = file.clone();
            drop(file);
            assert_eq!(backend.releases.load(Ordering::Relaxed), 0);
            drop(alias);
            assert_eq!(backend.releases.load(Ordering::Relaxed), 1);
            assert_eq!(multiplexer.releases.load(Ordering::Relaxed), 0);
        }
    }
    let backend = CharacterBackend::new(true, true, true);
    let multiplexer = Arc::new(CharacterMultiplexer {
        backend: backend.clone(),
        opens: AtomicUsize::new(0),
        releases: AtomicUsize::new(0),
    });
    assert!(matches!(
        open_test_character(multiplexer.clone()),
        Err(VfsError::NoSuchDevice)
    ));
    assert_eq!(multiplexer.opens.load(Ordering::Relaxed), 1);
    assert_eq!(backend.opens.load(Ordering::Relaxed), 1);
    assert_eq!(backend.releases.load(Ordering::Relaxed), 0);
    assert_eq!(multiplexer.releases.load(Ordering::Relaxed), 0);
}

