                CommandFile::new(move |operation| match operation {
                    SimpleFileOperation::Read => Ok(Some(Vec::new())),
                    SimpleFileOperation::Write { data, .. } => {
                        observed.lock().push(data.to_vec());
                        Ok(None)
                    }
                }),
