fn test_lookup_non_cacheable_negative_retracts() {
    let fs = Arc::new(MockFilesystem);
    let (dir, _) = make_non_cacheable_dir(fs.clone(), 2, None, "dir");
    let sb = SuperBlock::new(&MOCK_FILE_SYSTEM_TYPE, &MOCK_SUPER_OPERATIONS, |_| {
        dir.clone()
    });

