fn add(&mut self, entry: &Arc<ChrdevEntry>) -> VfsResult<()> {
        // Named insertion is a cold publication path. A second live number
        // with the same class/name would collide in every filesystem view.
        if let Some(identity) = &entry.identity
            && self.entries.values().any(|existing| {
                existing
                    .identity
                    .as_ref()
                    .is_some_and(|other| other.matches(identity))
            })
        {
            return Err(VfsError::ResourceBusy);
        }
        let major = entry.first.major();
        if self
            .entries
            .range(..=(major, entry.last_minor))
            .next_back()
            .is_some_and(|(_, previous)| {
                previous.first.major() == major && previous.last_minor >= entry.first.minor()
            })
        {
            return Err(VfsError::ResourceBusy);
        }
        self.entries
            .insert((major, entry.first.minor()), entry.clone());
        Ok(())
    }

fn update_metadata(&self, dentry: &Dentry, mut update: MetadataUpdate) -> VfsResult<()> {
        let changed = update.size.is_some()
            || update.mode.is_some()
            || update.owner.is_some()
            || update.atime.is_some()
            || update.mtime.is_some();
        update.atime = update.atime.map(|time| self.truncate_timestamp(time));
        update.mtime = update.mtime.map(|time| self.truncate_timestamp(time));
        update.ctime = update.ctime.map(|time| self.truncate_timestamp(time));
        if changed && update.ctime.is_none() {
            update.ctime = Some(self.current_time());
        }
        let applied = self
            .inode_operations
            .as_ref()
            .setattr(&MountIdmap, dentry, update)?;
        if let Some(size) = applied.size {
            self.update_size_after_backing_change(size)?;
        }
        if let Some(atime) = applied.atime {
            self.set_accessed_at(atime);
        }
        if let Some(mtime) = applied.mtime {
            self.set_modified_at(mtime);
        }
        if let Some(ctime) = applied.ctime {
            self.set_changed_at(ctime);
        }
        if let Some(mode) = applied.mode {
            self.attributes.set_permission(mode);
        }
        if let Some((uid, gid)) = applied.owner {
            self.attributes.set_owner(uid, gid);
        }
        Ok(())
    }

fn copy_to_iter(&mut self, src: &[u8]) -> KResult<usize> {
        self.output.extend_from_slice(src);
        if self.output.len() == PAGE_SIZE_4K {
            // Remove only future pages: the current folio is still locked by
            // the copy callback. This models residency changing during a read.
            if self.truncate {
                // The sink borrows the mapping of a live test inode.
                self.mapping.inode().unwrap().set_len(PAGE_SIZE_4K as u64)?;
            } else {
                self.mapping
                    .i_pages
                    .resize_cached_folios((PAGE_SIZE_4K * 3) as u64, PAGE_SIZE_4K as u64)
                    .unwrap();
            }
        }
        Ok(src.len())
    }

fn named_identity_exists_only_for_successful_live_registration() {
    let mut registry = ChrdevRegistry::new();
