fn finish_initialization(&self) {
        assert!(
            self.ops.get().is_some()
                && self.root.get().is_some()
                && self.block_size.get().is_some()
                && self.max_file_size.get().is_some()
                && self.timestamp_limits.get().is_some(),
            "fill_super must install operations, capabilities, and a root"
        );
        let mut lifecycle = self.lifecycle.lock();
        assert!(
            matches!(*lifecycle, SuperBlockLifecycle::Nascent),
            "only a nascent superblock can finish initialization"
        );
        *lifecycle = SuperBlockLifecycle::Available { active_mounts: 0 };
        drop(lifecycle);
        self.lifecycle_waiters.notify_all(false);
    }

fn symlink_at_entry(
        &self,
        root: &Path,
        base: &Path,
        target: &str,
        cred: &Cred,
    ) -> VfsResult<CreatedEntry> {
        let (parent, last, has_trailing_slash) = self
            .parent_at(root, base, LookupIntent::Open, cred)?
            .into_create()?;
        let name = last.as_str();

        let path = parent
            .dentry()
            .as_dir()?
            .create_exclusive_with(name, |candidate| {
                if has_trailing_slash {
                    return Err(VfsError::NotFound);
                }
                parent.vfs_symlink(candidate, target, cred)
            })
            .map(|entry| parent.with_dentry(entry))?;
        Ok(CreatedEntry {
            path,
            name: String::from(name),
            parent: parent.inode(),
        })
    }

