fn mount_new(
        &self,
        mountpoint: &Path,
        mount_flags: MountFlags,
        context: &mut FsContext<'_>,
        lookup_root: &Path,
        lookup_pwd: &Path,
    ) -> VfsResult<Arc<Mount>> {
        loop {
            let super_block = context.get_tree(lookup_root, lookup_pwd)?;
            let result = self.attach_with_requested_superblock_flags(
                mountpoint,
                &super_block,
                mount_flags,
                context.source(),
                Some(context.sb_flags()),
            );
            if matches!(&result, Err(VfsError::ResourceBusy)) && !super_block.is_available() {
                continue;
            }
            return result;
        }
    }

fn write(&self, _file: &VfsFile, buf: &[u8], offset: u64) -> VfsResult<usize> {
        let offset = offset as usize;
        let mut data = self.data.lock();
        if offset + buf.len() > data.len() {
            data.resize(offset + buf.len(), 0);
        }
        data[offset..offset + buf.len()].copy_from_slice(buf);
        Ok(buf.len())
    }

fn next_path_component<'p>(
        pathname: &mut &'p str,
        at_start: &mut bool,
    ) -> Option<(LastType, &'p str)> {
        loop {
            if (*pathname).is_empty() {
                return None;
            }
            let current = *pathname;
            let (component, rest) = match current.find('/') {
                Some(index) => (&current[..index], &current[index + 1..]),
                None => (current, ""),
            };
            *pathname = rest;
            let result = match component {
                "" if *at_start => Some((LastType::Root, "/")),
                "" => None,
                // A "." is a component wherever it appears: Linux keeps it (leading or
                // not), so the walk still verifies that the component it follows
                // sits in a directory (`d_can_lookup` -> ENOTDIR). Dropping a
                // non-leading "." made `file/.` resolve as `file` and succeed.
                "." => Some((LastType::Dot, ".")),
                ".." => Some((LastType::Dotdot, "..")),
                name => Some((LastType::Norm, name)),
            };
            *at_start = false;
            if let Some(result) = result {
                return Some(result);
            }
        }
    }

fn walk_component(
        &mut self,
        name: &str,
        component: WalkComponent,
        cred: &Cred,
    ) -> VfsResult<()> {
        let qstr = self.hash_name(name);
        let name = qstr.as_str();
        // The container's directory-ness is owned by `link_path_walk`'s
        // `d_can_lookup` check, which runs for every component before it is
        // walked (and before the search permission), mirroring Linux.
        let containing_dir = self.path.clone();
        let next = match self.lookup_fast(name) {
            Some(dentry) => dentry?,
            None => self.lookup_slow(name)?,
        }
        .resolve_final_mount();
        let next = self.step_into(&containing_dir, next, component, cred)?;
        self.set_path(next);
        Ok(())
    }

fn invalidate_cached_child(&self, name: &str) -> VfsResult<()> {
        self.as_dir()?;
        Self::verify_child_name(name)?;
        let dir_inode = self.vfs_inode();
        let _namespace_guard = dir_inode.lock_namespace_exclusive();
        self.forget_cache_entry(name);
        Ok(())
    }

fn file_wait_rechecks_readiness_published_while_registering() {
    let _cleanup = InterruptCleanup;
    ktask::current().clear_interrupt();
    let input = Input::new();
    input.publish_on_register.set(true);
    let mut wait = Box::pin(poll_file_io(&input, IoEvents::IN, false, || input.read()));
    let mut cx = Context::from_waker(Waker::noop());
    // No wake is sent: only the post-registration recheck can see the data.
