fn replace_flags(&self, mask: OpenFlags, flags: OpenFlags) {
        let mask = mask.bits();
        let flags = flags.bits();
        // The closure always returns Some; callers need only the updated flags.
        let _ = self
            .flags
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |current| {
                Some((flags & mask) | (current & !mask))
            });
    }

fn readahead_completes_full_windows_across_batch_boundaries() {
    let window_bytes = 128 * 1024;
    for offset in [0, 1] {
        let inode = read_inode(&WINDOW_READ_OPS, window_bytes + PAGE_SIZE_4K);
        let mapping = inode.address_space();
        let _invalidate = mapping.invalidate_lock.read();
        let end = offset + window_bytes as u64;
        assert_eq!(
            mapping.sync_readahead(offset, window_bytes, inode.size()),
            end
        );
        let pages = end.div_ceil(PAGE_SIZE_4K as u64);
        assert_eq!(mapping.nrpages(), pages);
        for index in 0..pages {
            mapping
                .with_folio(index, |folio| {
                    assert!(
                        folio
                            .expect("window tail must be initialized before demand read")
                            .data()
                            .iter()
                            .all(|&byte| byte == index as u8)
                    );
                })
                .unwrap();
        }
    }
}

fn record_lock_split_merge_and_failed_upgrade() {
    let context = FileLockContext::new();
    let owner = FileLockOwner::Posix(1);
    let second = FileLockOwner::Posix(2);
    context
        .apply(
            &FileLock::new(owner, 1, FileLockType::Write, 0, 100).unwrap(),
            false,
        )
        .unwrap();
    context
        .apply(
            &FileLock::new(owner, 1, FileLockType::Unlock, 20, 20).unwrap(),
            false,
        )
        .unwrap();
    let ranges = context
        .state
        .lock()
        .posix
        .iter()
        .map(|lock| (lock.start(), lock.end()))
        .collect::<Vec<_>>();
    assert_eq!(ranges, [(0, 19), (40, 99)]);
    context
        .apply(
            &FileLock::new(owner, 1, FileLockType::Write, 20, 20).unwrap(),
            false,
        )
        .unwrap();
    assert_eq!(context.state.lock().posix.iter().count(), 1);
    context
        .apply(
            &FileLock::new(owner, 1, FileLockType::Read, 0, 100).unwrap(),
            false,
        )
        .unwrap();
    context
        .apply(
            &FileLock::new(second, 2, FileLockType::Read, 0, 100).unwrap(),
            false,
        )
        .unwrap();
    assert_eq!(
        context.apply(
            &FileLock::new(owner, 1, FileLockType::Write, 0, 100).unwrap(),
            false
        ),
        Err(KError::WouldBlock)
    );
    assert!(
        context
            .state
            .lock()
            .posix
            .iter()
            .all(|lock| lock.kind == FileLockType::Read)
    );
}

fn test_remount_updates_mount_and_shared_superblock_flags() {
    let root_fs = mock_filesystem(StatFsFlags::empty());
    let child_fs = mock_filesystem(StatFsFlags::empty());
    let namespace = MntNamespace::new_root(&root_fs, kcred::initial_user_namespace());
    let root = namespace.root_path();
    let mountpoint = lookup_child_in_mount(&root, "mnt").unwrap();
    let cred = kcred::initial_cred();
    let mut readonly_context = FsContext::new_reconfigure(
        child_fs.as_ref(),
        None,
        None,
        SuperBlockFlags::RDONLY,
        SuperBlockFlags::RDONLY,
        &cred,
    )
    .unwrap();

    assert_eq!(
        namespace.remount(&mountpoint, &mut readonly_context, MountFlags::RDONLY),
        Err(VfsError::InvalidInput)
    );

    let child = namespace.attach(&mountpoint, &child_fs).unwrap();
    let child_root = child.root_path();
    let mut mount_context = FsContext::new(
        &MOCK_FILE_SYSTEM_TYPE,
        None,
        None,
        SuperBlockFlags::RDONLY,
        &cred,
    )
    .unwrap();
    assert_eq!(
        namespace.remount(&child_root, &mut mount_context, MountFlags::RDONLY),
        Err(VfsError::InvalidInput)
    );
    assert_eq!(child.flags(), MountFlags::empty());
    assert_eq!(child.super_block_flags(), SuperBlockFlags::empty());

    let bind_mountpoint = lookup_child_in_mount(&child_root, "mnt").unwrap();
    let bind = namespace
        .attach_bind(&child_root, &bind_mountpoint)
        .unwrap();
    let bind_root = bind.root_path();

    namespace
        .remount(
            &child_root,
            &mut readonly_context,
            MountFlags::RDONLY | MountFlags::NOEXEC,
        )
        .unwrap();

    assert_eq!(child.flags(), MountFlags::RDONLY | MountFlags::NOEXEC);
    assert!(!bind.flags().contains(MountFlags::RDONLY));
    assert_eq!(
        child_root.check_writable_mount(),
        Err(VfsError::ReadOnlyFilesystem)
    );
    assert_eq!(
        bind_root.check_writable_mount(),
        Err(VfsError::ReadOnlyFilesystem)
    );

    let mut writable_context = FsContext::new_reconfigure(
        child_fs.as_ref(),
        None,
        None,
        SuperBlockFlags::empty(),
        SuperBlockFlags::RDONLY,
        &cred,
    )
    .unwrap();
    namespace
        .remount(&child_root, &mut writable_context, MountFlags::NOEXEC)
        .unwrap();
    assert!(child_root.check_writable_mount().is_ok());
    assert!(bind_root.check_writable_mount().is_ok());

    namespace
        .reconfigure_mount(&bind_root, MountFlags::RDONLY)
        .unwrap();
    assert!(child_root.check_writable_mount().is_ok());
    assert_eq!(
        bind_root.check_writable_mount(),
        Err(VfsError::ReadOnlyFilesystem)
    );
}

fn move_blocked(&self, target: &Arc<Self>, blocked: &mut MutexGuard<'_, BlockedOwners>) {
        while let Some(waiter) = self.state(blocked).requests.pop_front() {
            self.note_pop();
            waiter.state(blocked).blocker = Some(Arc::downgrade(target));
            target.state(blocked).requests.push_back(waiter);
            target.note_push();
        }
    }

