                self.vfs_mkdir(candidate, permission, NodePermission::empty(), cred)
            })
            .map(|entry| self.with_dentry(entry))
    }

fn expansion_preserves_identity_and_close_hands_off_readers() {
    use alloc::task::Wake;
    use core::sync::atomic::{AtomicUsize, Ordering};

    struct WakeCount {
        context: Arc<FileLockContext>,
        count: AtomicUsize,
    }
    impl Wake for WakeCount {
        fn wake(self: Arc<Self>) {
            assert!(self.context.state.try_lock().is_some());
            assert!(node::wait_tree_unlocked());
            self.count.fetch_add(1, Ordering::Relaxed);
        }
    }
    let context = Arc::new(FileLockContext::new());
    let count = Arc::new(WakeCount {
        context: context.clone(),
        count: AtomicUsize::new(0),
    });
    let waker = Waker::from(count.clone());
    let holder = FileLockOwner::Posix(400);
    context
        .apply(
            &FileLock::new(holder, 0, FileLockType::Write, 10, 10).unwrap(),
            false,
        )
        .unwrap();
    let original = context
        .state
        .lock()
        .posix
        .find(|_| true)
        .unwrap()
        .downgrade();
    let mut readers = Vec::new();
    let mut wake = WakeQueue::new();
    for id in 401..465 {
        let request =
            FileLock::new(FileLockOwner::Posix(id), 0, FileLockType::Read, 10, 10).unwrap();
        let mut waiter = None;
        assert_eq!(
            context.try_apply(&request, true, &mut waiter, &mut wake),
            Ok(true)
        );
        let waiter = waiter.unwrap();
        assert!(waiter.poll_wait(&waker).is_pending());
        readers.push(waiter);
    }
    context
        .apply(
            &FileLock::new(holder, 0, FileLockType::Write, 0, 40).unwrap(),
            false,
        )
        .unwrap();
    {
        let state = context.state.lock();
        let installed = state.posix.find(|_| true).unwrap();
        assert!(original.upgrade().unwrap().ptr_eq(&installed));
        assert_eq!(state.posix.iter().next().unwrap().bounds(), (0, 39));
        assert_eq!(installed.children_count(), 64);
        for reader in &readers {
            assert!(reader.is_blocked_by_node(&installed));
        }
    }
    let mut waiter = None;
    assert_eq!(
        context.try_apply(&FileLock::unlock(holder), false, &mut waiter, &mut wake),
        Ok(false)
    );
    assert_eq!(wake.len(), 64);
    assert!(context.state.lock().posix.is_empty());
    assert!(original.upgrade().is_none());
    assert!(readers[0].poll_wait(&waker).is_pending());
    // A signal may cancel a request whose notification is already in
    // flight. Its existing node must remain alive until the handoff ends.
    let cancelled = readers.pop().unwrap();
    cancelled.cancel_waiter(&mut WakeQueue::new());
    drop(cancelled);
    wake.wake();
    assert_eq!(count.count.load(Ordering::Relaxed), 64);
    assert!(
        readers
            .iter()
            .all(|reader| reader.poll_wait(&waker).is_ready())
    );
}

fn copy_file_range(
    input: &Arc<VfsFile>,
    input_position: TransferPosition<'_>,
    output: &Arc<VfsFile>,
    output_position: TransferPosition<'_>,
    len: usize,
    _nonblocking: bool,
) -> KResult<usize> {
    input.verify_mode(FMode::READ)?;
    output.verify_mode(FMode::WRITE)?;

    let mut input_scratch = 0;
    let mut output_scratch = 0;
    let mut positions = resolve_pair_positions(
        input,
        input_position,
        output,
        output_position,
        &mut input_scratch,
        &mut output_scratch,
    );
    let (input_start, output_start) = positions.starts();
    let count = verify_copy_file_range(input, output, input_start, output_start, len as u64)?;
    let mut input_pos = input_start;
    let mut output_pos = output_start;
    let result = pump(count as usize, |buf, chunk, _total| {
        match output.copy_chunk_from(input, input_pos, output_pos, chunk) {
            Some(native) => {
                let confirmed = native?;
                if confirmed > chunk {
                    return Err(KError::Io);
                }
                input_pos += confirmed as u64;
                output_pos += confirmed as u64;
                Ok(Step::Data {
                    confirmed,
                    stop: confirmed < chunk,
                })
            }
            None => file_pair_step(input, output, &mut input_pos, &mut output_pos, buf, chunk),
        }
    });

    // Position commit belongs to the completion protocol: publish only
    // after real progress — a zero-byte return leaves `f_pos` alone.
    if matches!(result, Ok(count) if count > 0) {
        positions.commit(input_pos, output_pos);
    }
    result
}

fn remove_access(state: &mut PipeState, access: PipeAccess) -> (bool, bool) {
    let readers_became_zero = if access.can_read() {
        assert!(state.readers > 0, "pipe reader count underflow");
        state.readers -= 1;
        state.readers == 0
    } else {
        false
    };
    let writers_became_zero = if access.can_write() {
        assert!(state.writers > 0, "pipe writer count underflow");
        state.writers -= 1;
        state.writers == 0
    } else {
        false
    };
    let peers_remain = state.readers != 0 || state.writers != 0;
    let wake_both = peers_remain && (readers_became_zero || writers_became_zero);
    (wake_both, wake_both)
}

fn del(&mut self, first: DeviceId, count: u32) -> Option<Arc<ChrdevEntry>> {
        let last_minor = first.minor().checked_add(count.checked_sub(1)?)?;
        let key = (first.major(), first.minor());
        if self.entries.get(&key)?.last_minor != last_minor {
            return None;
        }
        let entry = self.entries.remove(&key)?;
        entry.is_registered.store(false, Ordering::Release);
        Some(entry)
    }

fn pipe_poll(file: &VfsFile) -> IoEvents {
    let Ok(pipe) = PipeObject::from_file(file) else {
        return IoEvents::ERR;
    };
    let state = pipe.state.lock();
    let mode = file.mode();
    let mut events = IoEvents::empty();
    if mode.contains(FMode::READ) {
        events.set(IoEvents::IN, !state.buffer.is_empty());
        events.set(
            IoEvents::HUP,
            // Zero is the Linux-compatible uninitialized `f_pipe` snapshot
            // used by anonymous pipes and blocking FIFO opens.
            state.writers == 0
                && (file.pipe_generation() == 0 || file.pipe_generation() != state.w_counter),
        );
    }
    if mode.contains(FMode::WRITE) {
        events.set(IoEvents::OUT, state.buffer.len() < state.capacity);
        events.set(IoEvents::ERR, state.readers == 0);
    }
    events
}

fn block_open_mode(mode: FMode, flags: crate::OpenFlags) -> BlockOpenMode {
    let mut block_mode = BlockOpenMode::empty();
    if mode.contains(FMode::READ) {
        block_mode.insert(BlockOpenMode::READ);
    }
    if mode.contains(FMode::WRITE) {
        block_mode.insert(BlockOpenMode::WRITE);
    }
    block_mode.set(
        BlockOpenMode::EXCLUSIVE,
        flags.contains(crate::OpenFlags::EXCLUSIVE),
    );
    block_mode.set(
        BlockOpenMode::NONBLOCK,
        flags.contains(crate::OpenFlags::NONBLOCK),
    );
    // Linux file_to_blk_mode() preserves ioctl-only access mode 3.
    block_mode.set(
        BlockOpenMode::WRITE_IOCTL,
        flags.contains(crate::OpenFlags::READ_WRITE | crate::OpenFlags::WRITE_ONLY),
    );
    block_mode
}

fn character_adapter_forwards_readiness_event_mask_and_registration_error() {
    let backend = CharacterBackend::new(true, true, false);
    let file = open_test_character(backend.clone()).unwrap();
    assert!(file.poll().is_empty());
    let wake = Arc::new(CharacterWake(AtomicBool::new(false)));
    let waker = Waker::from(wake.clone());
    let cx = Context::from_waker(&waker);
    let mut registrations = PollRegistrations::new();
    file.register_poll(&mut registrations.context(&cx), IoEvents::OUT)
        .unwrap();
    backend.waiters.wake();
    assert!(!wake.0.load(Ordering::Acquire));
    file.register_poll(&mut registrations.context(&cx), IoEvents::IN)
        .unwrap();
    backend.is_ready.store(true, Ordering::Release);
    backend.waiters.wake();
    assert!(wake.0.load(Ordering::Acquire));
    assert_eq!(file.poll().bits(), IoEvents::IN.bits());
    backend.is_ready.store(false, Ordering::Release);
    assert!(file.poll().is_empty());
    backend.reject_registration.store(true, Ordering::Relaxed);
    assert_eq!(
        file.register_poll(&mut registrations.context(&cx), IoEvents::IN),
        Err(PollRegisterError::InvalidState)
    );
}

