    assert!(super_block.flags().contains(SuperBlockFlags::RDONLY));

    super_block.deactivate_mount();
    block::del_gendisk(disk.device_number()).expect("remove read-only remount disk");
}

fn detach_tree(&self, path: &Path) -> VfsResult<()> {
        let mut mounts = self.mounts.lock();
        let root = Self::registered_mount_at(&mounts, path)?.clone();
        let removed = root.collect_subtree();
        for mount in &removed {
            Self::require_mount(&mounts, mount)?;
        }

        path.detach_mount_subtree(&removed)?;
        for mount in &removed {
            mounts.remove(&mount.mount_id());
        }
        drop(mounts);
        Ok(())
    }

fn open(self: Arc<Self>, inode: &VfsInode, file: &mut VfsFileBuilder) -> VfsResult<()> {
        let access = PipeAccess::from_mode(file.mode())?;
        let pipe = inode.acquire_fifo_pipe()?;
        let pipe_generation = match pipe.open_fifo(access, file.is_nonblocking()) {
            Ok(pipe_generation) => pipe_generation,
            Err(error) => {
                inode.release_fifo_pipe(&pipe);
                return Err(error);
            }
        };
        file.stream_open();
        file.set_pipe_generation(pipe_generation);
        file.set_private_data(pipe);
        Ok(())
    }

fn lock(&self, file: &VfsFile, request: &crate::FileLock, is_blocking: bool) -> VfsResult<()> {
        if request.kind() == crate::FileLockType::Unlock
            && file.inode().existing_file_locks().is_none()
        {
            return Ok(());
        }
        file.inode().file_locks()?.apply(request, is_blocking)
    }

