fn try_write(&self) -> Option<SpinRwLockWriteGuard<'_, G, T>> {
        let guard_state = G::acquire();
        let acquired = self
            .state
            .compare_exchange(0, WRITE_LOCKED, Ordering::Acquire, Ordering::Relaxed)
            .is_ok();

        if acquired {
            #[cfg(feature = "stats")]
            self.record_write_acquisition(false);
            Some(SpinRwLockWriteGuard {
                lock: self,
                guard_state,
            })
        } else {
            G::release(guard_state);
            None
        }
    }

fn lookup_or_create_with<F>(
        &self,
        name: &str,
        exclusive: bool,
        create_fn: F,
    ) -> VfsResult<LookupCreateResult>
    where
        F: FnOnce(&Dentry) -> VfsResult<()>,
    {
        self.with_locked_child(name, |candidate| {
            if candidate.is_really_positive() {
                return if exclusive {
                    Err(VfsError::AlreadyExists)
                } else {
                    Ok(LookupCreateResult::Existing(candidate.clone()))
                };
            }

            create_fn(candidate)?;
            if candidate.is_negative() {
                return Err(VfsError::InvalidInput);
            }
            Ok(LookupCreateResult::Created(candidate.clone()))
        })
    }

