fn snapshot_partial_reads_are_stable_across_source_changes() {
    let source = Arc::new(crate::Mutex::new(b"abcdefgh".to_vec()));
    let observed = source.clone();
    let generations = Arc::new(crate::Mutex::new(0usize));
    let generated = generations.clone();
    let super_block = SimpleFs::new_with(&TEST_FILE_SYSTEM_TYPE, 0, move |fs| {
        let mut root = DirMapping::new();
        root.add(
            "snapshot",
            SimpleFile::new_snapshot(fs.clone(), move || {
                *generated.lock() += 1;
                Ok(observed.lock().clone())
            }),
        );
        SimpleDir::new_maker(fs, Arc::new(root))
    })
    .unwrap();
    let root = Mount::new_root(&super_block).root_path();
    let open = |flags| {
        Filename::new("/snapshot")
            .open_with_flags_at(
                &root,
                &root,
                flags,
                NodePermission::empty(),
                NodePermission::empty(),
                kcred::initial_cred(),
            )
            .unwrap()
    };
    let first = open(linux_raw_sys::general::O_RDONLY);
    let mut prefix = [0; 3];
    assert_eq!(first.read(&mut prefix), Ok(3));
    assert_eq!(&prefix, b"abc");
    *source.lock() = b"CHANGED-LONG".to_vec();
    let mut tail = [0; 5];
    assert_eq!(first.read(&mut tail), Ok(5));
    assert_eq!(&tail, b"defgh");
    let mut next = [0; 12];
    assert_eq!(
        open(linux_raw_sys::general::O_RDONLY).read(&mut next),
        Ok(12)
    );
    assert_eq!(&next, b"CHANGED-LONG");
    assert_eq!(first.llseek(0, crate::file::SEEK_END), Ok(8));
    assert_eq!(first.read(&mut next), Ok(0));
    assert_eq!(first.llseek(-2, crate::file::SEEK_END), Ok(6));
    assert_eq!(first.read(&mut next), Ok(2));
    assert_eq!(&next[..2], b"gh");
    assert_eq!(
        first.llseek(-9, crate::file::SEEK_END),
        Err(VfsError::InvalidInput)
    );
    assert_eq!(first.llseek(0, crate::file::SEEK_CUR), Ok(8));
    assert_eq!(
        first.llseek(i64::MAX, crate::file::SEEK_END),
        Err(VfsError::InvalidInput)
    );
    assert_eq!(first.llseek(0, -1), Err(VfsError::InvalidInput));
    assert_eq!(first.llseek(0, crate::file::SEEK_CUR), Ok(8));
    assert_eq!(first.llseek(0, crate::file::SEEK_SET), Ok(0));
    assert_eq!(
        open(linux_raw_sys::general::O_RDONLY).llseek(0, crate::file::SEEK_END),
        Ok(12)
    );
    assert_eq!(first.write(b"x"), Err(VfsError::BadFileDescriptor));
    assert_eq!(*generations.lock(), 3);
    let write_opened = open(linux_raw_sys::general::O_WRONLY);
    assert_eq!(*generations.lock(), 3);
    assert_eq!(
        write_opened
            .private_data_get::<SimpleFileSnapshot>()
            .is_none(),
        true
    );
    assert_eq!(write_opened.llseek(3, crate::file::SEEK_SET), Ok(3));
    assert_eq!(write_opened.llseek(2, crate::file::SEEK_CUR), Ok(5));
    assert_eq!(write_opened.llseek(-1, crate::file::SEEK_CUR), Ok(4));
    assert_eq!(
        write_opened.llseek(-5, crate::file::SEEK_CUR),
        Err(VfsError::InvalidInput)
    );
    assert_eq!(
        write_opened.llseek(0, crate::file::SEEK_END),
        Err(VfsError::InvalidData)
    );
    assert_eq!(write_opened.llseek(0, crate::file::SEEK_CUR), Ok(4));
    assert_eq!(*generations.lock(), 3);
    assert_eq!(write_opened.write(b"x"), Err(VfsError::InvalidInput));
    assert_eq!(*source.lock(), b"CHANGED-LONG".to_vec());
    let read_write = open(linux_raw_sys::general::O_RDWR);
    assert_eq!(*generations.lock(), 4);
    assert_eq!(read_write.read(&mut next), Ok(12));
    assert_eq!(&next, b"CHANGED-LONG");
    assert_eq!(read_write.write(b"x"), Err(VfsError::InvalidInput));
    source.lock().clear();
    let empty = open(linux_raw_sys::general::O_RDONLY);
    assert_eq!(empty.llseek(0, crate::file::SEEK_END), Ok(0));
    assert_eq!(empty.read(&mut next), Ok(0));
    assert_eq!(empty.llseek(2, crate::file::SEEK_SET), Ok(2));
    assert_eq!(empty.read(&mut next), Ok(0));
    assert_eq!(first.llseek(0, crate::file::SEEK_END), Ok(8));
}

fn submit_bio(&self, mut bio: block::Bio) {
        let block_id = bio.sector() / (block::BlockDeviceOperations::block_size(self) as u64 / 512);
        let result = match bio.operation() {
            block::BioOperation::Read => {
                bio.read_contiguous(|bytes| self.read_block(block_id, bytes))
            }
            block::BioOperation::Write => {
                bio.write_contiguous(|bytes| self.write_block(block_id, bytes))
            }
            block::BioOperation::Flush => self.flush(),
        };
        bio.end_io(result);
    }

async fn poll_file_io<P: Pollable, F: FnMut() -> KResult<T>, T>(
    pollable: &P,
    events: IoEvents,
    is_nonblocking: bool,
    mut operation_fn: F,
) -> KResult<T> {
    match operation_fn() {
        Err(KError::WouldBlock) if !is_nonblocking => {}
        result => return result,
    }

    match poll_io_with_cause(pollable, events, false, &mut operation_fn).await {
        Ok(result) => result,
        Err(interrupted) if interrupted.is_task_interrupt() => match operation_fn() {
            Err(KError::WouldBlock) => Err(KError::IoWaitInterrupted),
            result => result,
        },
        Err(error) => Err(error.into()),
    }
}

fn parent(&self) -> Option<Pathname<'a>> {
        let mut end = self.inner.len();
        loop {
            while end > 0 && self.inner.as_bytes()[end - 1] == b'/' {
                end -= 1;
            }
            if end == 0 {
                return None;
            }
            let start = self.inner[..end]
                .rfind('/')
                .map(|index| index + 1)
                .unwrap_or(0);
            let name = &self.inner[start..end];
            if name == "." && start > 0 {
                end = if start == 1 { 0 } else { start - 1 };
                continue;
            }
            let parent_end = if start == 0 {
                0
            } else if start == 1 {
                1
            } else {
                start - 1
            };
            return Some(Pathname::new(&self.inner[..parent_end]));
        }
    }

fn read(&self) -> SpinRwLockReadGuard<'_, G, T> {
        let guard_state = G::acquire();
        #[cfg(feature = "stats")]
        let mut did_wait = false;

        loop {
            let state = self.state.load(Ordering::Acquire);
            if state & WRITE_LOCKED != 0 {
                #[cfg(feature = "stats")]
                {
                    did_wait = true;
                }
                core::hint::spin_loop();
                continue;
            }
            if state == READER_MASK {
                panic!("too many spin rwlock readers");
            }
            if self
                .state
                .compare_exchange_weak(state, state + 1, Ordering::Acquire, Ordering::Relaxed)
                .is_ok()
            {
                #[cfg(feature = "stats")]
                self.record_read_acquisition(did_wait);
                return SpinRwLockReadGuard {
                    lock: self,
                    guard_state,
                };
            }
        }
    }

fn lookup_fast_for_open(&mut self, flags: &OpenParams) -> VfsResult<Option<Path>> {
        if flags.will_create() {
            if self.has_trailing_slashes() {
                return Err(VfsError::IsADirectory);
            }
            if flags.is_exclusive_create() {
                return Ok(None);
            }
        }

        if self.has_trailing_slashes() {
            self.flags |= LookupFlags::FOLLOW_FINAL | LookupFlags::DIRECTORY;
        }

        let name = self
            .last
            .as_ref()
            .map(Qstr::as_str)
            .ok_or(VfsError::InvalidInput)?;
        let Some(result) = self.lookup_fast(name) else {
            return Ok(None);
        };
        match result {
            Ok(path) => Ok(Some(path)),
            Err(err) if err.canonicalize() == VfsError::NotFound && flags.will_create() => Ok(None),
            Err(err) => Err(err),
        }
    }

fn iterate_shared(&self, file: &VfsFile, ctx: &mut DirContext<'_>) -> VfsResult<usize> {
        let dentry = file.path().dentry();
        let entries = [
            (DOT, NULLFS_ROOT_INO),
            (
                DOTDOT,
                dentry
                    .parent()
                    .map_or(NULLFS_ROOT_INO, |parent| parent.metadata().inode),
            ),
        ];

        let mut count = 0;
        for (index, (name, inode)) in entries.into_iter().enumerate().skip(ctx.pos() as usize) {
            if !ctx.emit(name, inode, NodeType::Directory, index as u64 + 1) {
                break;
            }
            count += 1;
        }
        Ok(count)
    }

