    assert_eq!(iter.count(), 19);
    assert_eq!(iocb.ki_pos(), 3 + memaddr::PAGE_SIZE_4K as u64);
    assert!(
        bytes[..memaddr::PAGE_SIZE_4K]
            .iter()
            .all(|byte| *byte == 0x37)
    );
    assert!(bytes[memaddr::PAGE_SIZE_4K..].iter().all(|byte| *byte == 0));
    let file = sync_test_file(
        Arc::new(InterruptedAfterBlock(AtomicU32::new(0))),
        FMode::WRITE,
    );
    bytes.fill(0x37);
    let mut iter = iov_iter_kvec_source(&bytes);
    let mut iocb = Kiocb::new(&file, 3);
    assert_eq!(
        file.operations().write_iter(&mut iocb, &mut iter),
        Ok(memaddr::PAGE_SIZE_4K)
    );
    assert_eq!(iter.count(), 19);
    assert_eq!(iocb.ki_pos(), 3 + memaddr::PAGE_SIZE_4K as u64);
}

fn verify_io_area(&self, pos: u64, count: usize) -> VfsResult<()> {
        if count > isize::MAX as usize {
            return Err(VfsError::InvalidInput);
        }
        let count = u64::try_from(count).map_err(|_| VfsError::InvalidInput)?;
        pos.checked_add(count).ok_or(VfsError::InvalidInput)?;
        if self.inode().node_type() == NodeType::Directory {
            return Err(VfsError::IsADirectory);
        }
        Ok(())
    }

fn wait_interruptible(&self) -> KResult<()> {
        block_on_interruptible(poll_fn(|cx| self.poll_wait(cx.waker()))).map_err(
            |error| -> KError {
                if error.is_task_interrupt() {
                    LinuxError::ERESTARTSYS.into()
                } else {
                    error.into()
                }
            },
        )
    }

fn symlink(
        &self,
        _idmap: &crate::MountIdmap,
        dir: &VfsInode,
        dentry: &LockedDentry<'_>,
        target: &str,
        cred: &kcred::Cred,
    ) -> VfsResult<()> {
        let parent = dentry.parent().ok_or(VfsError::InvalidInput)?;
        let (mode, uid, gid) = inode_init_owner(
            dir,
            Umode::new(NodeType::Symlink, NodePermission::from_bits_truncate(0o777)),
            cred,
        );
        let node = Arc::new(SimpleFsNode::new_with_owner(
            self.dir.node.filesystem(),
            NodeType::Symlink,
            mode.permission(),
            uid,
            gid,
        ));
        node.metadata.lock().size = target.len() as u64;
        let init = node.inode_init();
        let inode = VfsInode::new_cached_symlink(node, NodeFlags::empty(), init, target.to_owned());
        let entry =
            self.dir
                .ops
                .create_inode_child(SimpleDirLookup::new(&parent), dentry.name(), inode)?;
        let inode = entry.vfs_inode();
        drop(entry);
        dentry.instantiate(inode)
    }

fn drop(&mut self) {
        if self.is_published {
            return;
        }
        let mut inodes = self.cache.inodes.lock();
        let waiters = if matches!(
            inodes.get(&self.key),
            Some(entry) if matches!(entry.state, CachedInodeState::New)
        ) {
            inodes.remove(&self.key).map(|entry| entry.waiters)
        } else {
            None
        };
        drop(inodes);
        if let Some(waiters) = waiters {
            waiters.notify_all(false);
        }
    }

fn register(
        &self,
        context: &mut PollContext<'_>,
        _: IoEvents,
    ) -> Result<(), PollRegisterError> {
        context.register(&self.events)?;
        if self.publish_on_register.replace(false) {
            self.value.set(11);
        }
        Ok(())
    }

fn mknod(
        &self,
        _idmap: &crate::MountIdmap,
        _dir: &VfsInode,
        dentry: &LockedDentry<'_>,
        mode: Umode,
        device: DeviceId,
        _cred: &Cred,
    ) -> VfsResult<()> {
        self.creations.lock().push(CreateRecord {
            mode,
            exclusive: true,
            device,
        });
        self.instantiate_created(dentry, mode, device)
    }

fn nullfs_root_dentry() -> Dentry {
    let root = Arc::new(NullFsRoot);
    let private_data: Arc<dyn core::any::Any + Send + Sync> = root.clone();
    let inode_operations: Arc<dyn InodeOperations> = root.clone();
    let file_operations: Arc<dyn FileOperations> = root;
    let inode = VfsInode::new_dir_with_operations(
        private_data,
        inode_operations,
        file_operations,
        NodeFlags::PRIVATE,
        NullFsRoot::inode_init(),
    );
    Dentry::new_dir_from_inode(inode, None, alloc::string::String::new())
}

fn move_cached_dentry(
        &self,
        old_key: &DentryKey,
        new_key: &DentryKey,
        source: &Dentry,
    ) {
        let mut cache = self.dentry_cache.lock();
        let removed = cache.remove(old_key);
        if let Some(target_slot) = cache.get_mut(new_key) {
            *target_slot = source.clone();
        }
        drop(cache);
        drop(removed);
    }

fn perform_write(
        &self,
        offset: u64,
        iter: &mut IovIterSource<'_>,
        len: usize,
    ) -> VfsResult<usize> {
        if !ktask::is_sleepable_context() {
            return Err(VfsError::InvalidInput);
        }
        let mut written = 0usize;
        let mut visible_len = self.visible_len()?;
        while written < len {
            let pos = offset
                .checked_add(written as u64)
                .ok_or(VfsError::InvalidInput)?;
            let index = pos / memaddr::PAGE_SIZE_4K as u64;
            let page_off = (pos % memaddr::PAGE_SIZE_4K as u64) as usize;
            let step = (len - written).min(memaddr::PAGE_SIZE_4K - page_off);
            let prepared_end = pos.checked_add(step as u64).ok_or(VfsError::InvalidInput)?;
            if let Err(error) = self
                .ops
                .write_begin(self, WriteBeginRequest::new(pos, step))
            {
                return write_prefix_or_error(written, error);
            }
            let grew_cache = prepared_end > visible_len;
            if grew_cache {
                self.i_pages
                    .resize_cached_folios(visible_len, prepared_end)?;
            }
            let mut copied = 0;
            let copy_result = self.with_folio_or_create(index, |folio| {
                let data = folio.data();
                copied = iter.copy_from_iter(&mut data[page_off..page_off + step])?;
                if copied != 0 {
                    self.dirty_folio(folio)?;
                }
                Ok(())
            });
            if let Err(error) = copy_result {
                iter.revert(copied)?;
                if let Err(cancel_error) =
                    self.ops.write_end(self, WriteEndRequest::new(pos, step, 0))
                {
                    log::warn!(
                        "failed to cancel buffered write at {pos} (len {step}): {cancel_error:?}"
                    );
                }
                if grew_cache {
                    self.i_pages
                        .resize_cached_folios(prepared_end, visible_len)?;
                }
                return write_prefix_or_error(written, error);
            }
            let accepted = match self
                .ops
                .write_end(self, WriteEndRequest::new(pos, step, copied))
            {
                Ok(accepted) => accepted,
                Err(error) => {
                    iter.revert(copied)?;
                    if grew_cache {
                        self.i_pages
                            .resize_cached_folios(prepared_end, visible_len)?;
                    }
                    return write_prefix_or_error(written, error);
                }
            };
            if accepted > copied {
                return Err(VfsError::InvalidInput);
            }
            if accepted < copied {
                iter.revert(copied - accepted)?;
            }
            // `write_end` publishes EOF as `pos + accepted`; roll the cache back
            // to that same end so unaccepted bytes are not left cached and dirty
            // beyond the visible size.
            let accepted_end = pos
                .checked_add(accepted as u64)
                .ok_or(VfsError::InvalidInput)?;
            if grew_cache && accepted_end < prepared_end {
                self.i_pages
                    .resize_cached_folios(prepared_end, accepted_end)?;
            }
            visible_len = visible_len.max(accepted_end);
            if accepted == 0 {
                break;
            }
            written += accepted;
            if accepted < step {
                break;
            }
        }

        Ok(written)
    }

