fn link_path_walk(&mut self, base: &Path, cred: &Cred) -> VfsResult<Path> {
        if self.pathname.is_empty() {
            if self.flags.contains(LookupFlags::EMPTY_PATH) {
                return Ok(base.clone());
            }
            return Err(VfsError::NotFound);
        }

        self.path_init(base);
        let mut pathname = self.pathname;
        let mut at_start = true;

        while let Some((last_type, name)) = Self::next_path_component(&mut pathname, &mut at_start)
        {
            let has_more = Self::has_more_path_components(pathname, at_start);
            if last_type != LastType::Root {
                // The component being resolved must sit in a directory, and
                // Linux checks that before the search permission: `d_can_lookup`
                // reports ENOTDIR first, `may_lookup` only then EACCES
                // (fs/namei.c `link_path_walk`). Without this ordering a path
                // like `file/child` or `file/.` failed the MAY_EXEC check on the
                // regular file itself and surfaced EACCES instead.
                if !self.path.dentry().can_lookup() {
                    return Err(VfsError::NotADirectory);
                }
                self.path.permission(crate::Permission::MAY_EXEC, cred)?;
            }
            if !has_more {
                self.walk_path_component(last_type, name, WalkComponent::Final, cred)?;
                return Ok(self.path.clone());
            }
            self.walk_path_component(last_type, name, WalkComponent::More, cred)?;
        }

        Ok(self.path.clone())
    }

fn read_folio(&self, mapping: &AddressSpace, mut folio: FolioRead) -> VfsResult<()> {
        let index = folio.index();
        folio.data().fill((index % 251) as u8);
        let len = mapping
            .visible_len()?
            .saturating_sub(folio.index() * PAGE_SIZE_4K as u64)
            .min(PAGE_SIZE_4K as u64) as usize;
        folio.data()[len..].fill(0);
        folio.complete(Ok(()))
    }

fn child_names<'a>(&'a self) -> VfsResult<KBox<dyn Iterator<Item = Cow<'a, str>> + 'a>> {
        let names: Vec<Cow<'a, str>> = self
            .entries
            .lock()
            .keys()
            .map(|name| Cow::Owned(name.clone()))
            .collect();
        Ok(KBox::new(names.into_iter())?)
    }

fn mod_test(_attr: TokenStream, item: TokenStream) -> TokenStream {
    let mut module = parse_macro_input!(item as ItemMod);

    // An inline module takes the allowances as inner attributes, a file module
    // (`mod foo;`) as outer ones. rustc currently rejects attribute macros on
    // file modules (E0658), so the outer form is not reachable on stable.
    let mut allows: [Attribute; 3] = [
        parse_quote! {
            #[allow(
                clippy::unwrap_used,
                clippy::expect_used,
                clippy::panic,
                reason = "CG-021-no-panic-on-reachable-failure: unittest module: test helpers may panic on failure"
            )]
        },
        parse_quote! {
            #[allow(missing_docs, reason = "CG-024-lint-exceptions: missing_docs: unittest module: test code is outside rustdoc scope")]
        },
        parse_quote! {
            #[allow(
                clippy::too_many_lines,
                reason = "CG-028-focused-functions: unittest module: a test scenario reads as one linear script"
            )]
        },
    ];
    if module.content.is_some() {
        for attr in &mut allows {
            attr.style = AttrStyle::Inner(Token![!](Span::call_site()));
        }
    }
    module.attrs.extend(allows);

    quote! {
        #[cfg(unittest)]
        #module
    }
    .into()
}

