fn file_wait_preserves_io_registration_errors() {
    struct InvalidPoll;
    impl Pollable for InvalidPoll {
        fn poll(&self) -> IoEvents {
            IoEvents::empty()
        }

        fn register(&self, _: &mut PollContext<'_>, _: IoEvents) -> Result<(), PollRegisterError> {
            Err(PollRegisterError::InvalidState)
        }
    }
    let _cleanup = InterruptCleanup;
    ktask::current().clear_interrupt();
    let result: KResult<usize> =
        ktask::future::block_on(poll_file_io(&InvalidPoll, IoEvents::IN, false, || {
            Err(KError::WouldBlock)
        }));
    assert_eq!(result, Err(KError::InvalidInput));
}

fn add_alias(&self, dentry: &Dentry, is_directory: bool) -> bool {
        let mut aliases = self.aliases.lock();
        aliases.retain(DentryAlias::is_live);
        if aliases.iter().any(|alias| alias.points_to(dentry)) {
            return true;
        }
        if is_directory && !aliases.is_empty() {
            return false;
        }
        aliases.push(DentryAlias::new(dentry));
        true
    }

fn render_components(&self, root: Option<&Self>) -> VfsResult<(bool, Vec<String>)> {
        let mut components = Vec::new();
        let mut current = self.clone();
        loop {
            if root.is_some_and(|root| current.ptr_eq(root)) {
                return Ok((true, components));
            }

            if !current.dentry.ptr_eq(&current.mnt.mnt.mnt_root) {
                components.push(current.name());
                let Some(parent) = current.dentry.parent() else {
                    return Ok((root.is_none(), components));
                };
                current = current.with_dentry(parent);
                continue;
            }

            let Some(mountpoint) = current.mnt.location() else {
                return Ok((root.is_none(), components));
            };
            if root.is_some_and(|root| mountpoint.ptr_eq(root)) {
                return Ok((true, components));
            }
            components.push(mountpoint.name());
            let Some(parent) = mountpoint.parent() else {
                return Ok((root.is_none(), components));
            };
            current = parent;
        }
    }

fn check_device_access(&self, device: DeviceId, access: DeviceAccess) -> VfsResult<()> {
        self.consulted
            .lock()
            .push((device.major(), device.minor(), access.bits()));
        if device.major() == 1 && device.minor() == 3 {
            Err(VfsError::OperationNotPermitted)
        } else {
            Ok(())
        }
    }

fn test_rename_moves_cache_entry_without_changing_inode_identity() {
    let fs = Arc::new(MockFilesystem);
    let root = make_renamable_dir_entry(30, None, "");
    let (source, _) = make_file_entry(fs, 31, Some(root.clone()), "tmp");

    root.insert_cache(String::from("tmp"), source.clone());
    root.rename("tmp", &root, "final", RenameFlags::empty())
        .unwrap();

    assert!(root.lookup_cache("tmp").is_none());
    let moved = root.lookup_cache("final").unwrap();
    assert!(moved.ptr_eq(&source));
