fn close(&self, mode: FMode) -> KResult<()> {
        let access = PipeAccess::from_mode(mode)?;
        let (wake_readers, wake_writers) = remove_access(&mut self.state.lock(), access);
        self.wake(wake_readers, wake_writers);
        Ok(())
    }

fn copy_to_iter(&mut self, src: &[u8]) -> KResult<usize> {
            assert_eq!(src[0], 1);
            let mut ra = self.file.readahead.lock();
            while ra.is_enabled() {
                ra.shrink_after_io_error();
            }
            let copied = self.remaining.min(src.len());
            self.remaining -= copied;
            Ok(copied)
        }

fn uncontended_operations_do_not_take_wait_tree_lock() {
    let blocked = node::hold_wait_tree();
    for owner in [FileLockOwner::Posix(500), FileLockOwner::Flock(500)] {
        let context = FileLockContext::new();
        for (kind, start, length) in [
            (FileLockType::Write, 0, 10),
            (FileLockType::Write, 0, 20),
            (FileLockType::Write, 30, 10),
            (FileLockType::Write, 0, 40),
            (FileLockType::Unlock, 10, 10),
            (FileLockType::Read, 0, 40),
            (FileLockType::Unlock, 0, 0),
        ] {
            context
                .apply(
