fn simple_rename_timestamp(
    old_dir: &VfsInode,
    old_dentry: &Dentry,
    new_dir: &VfsInode,
    new_dentry: &Dentry,
) {
    let timestamp = old_dir.set_changed_at_to_now();
    old_dir.set_modified_at(timestamp);
    if !ptr::eq(old_dir, new_dir) {
        let timestamp = new_dir.set_changed_at_to_now();
        new_dir.set_modified_at(timestamp);
    }
    old_dentry.set_changed_at_to_now();
    if d_really_is_positive(new_dentry) {
        new_dentry.set_changed_at_to_now();
    }
}

fn pipe_read_iter(iocb: &mut Kiocb<'_>, iter: &mut IovIterDest<'_>) -> VfsResult<usize> {
    let read = {
        let file = iocb.file();
        file.verify_mode(FMode::READ)?;
        PipeObject::from_file(file)?.read_iter(file.is_nonblocking(), iter)?
    };
    iocb.advance(read);
    Ok(read)
}

fn poll(&self) -> IoEvents {
        let state = self.state.lock();
        let mut events = IoEvents::empty();
        events.set(IoEvents::IN, !state.buffer.is_empty());
        events.set(IoEvents::OUT, state.buffer.len() < state.capacity);
        events.set(IoEvents::HUP, state.writers == 0);
        events.set(IoEvents::ERR, state.readers == 0);
        events
    }

