    drop(old_entry);
    assert!(Arc::ptr_eq(&character_operations(&inode).unwrap(), &ops));
}

fn is_ancestor_of(&self, other: &Self) -> VfsResult<bool> {
        let mut current = other.clone();
        loop {
            if current.ptr_eq(self) {
                return Ok(true);
            }
            if let Some(parent) = current.parent() {
                current = parent;
            } else {
                break;
            }
        }
        Ok(false)
    }

fn detach(&self, path: &Path) -> VfsResult<()> {
        let mut mounts = self.mounts.lock();
        let removed = Self::registered_mount_at(&mounts, path)?.clone();
        path.unmount()?;
        mounts.remove(&removed.mount_id());
        drop(mounts);
        Ok(())
    }

fn truncate_pagecache(&self, old_len: u64, len: u64) -> VfsResult<()> {
        let invalid_start = (len < old_len).then(|| {
            len.div_ceil(PAGE_SIZE_4K as u64)
                .saturating_mul(PAGE_SIZE_4K as u64)
        });
        if let Some(start) = invalid_start {
            self.invalidate_mappings_from(start);
        }
        self.i_pages.resize_cached_folios(old_len, len)?;
        if let Some(start) = invalid_start {
            self.invalidate_mappings_from(start);
        }
        Ok(())
    }

fn is_reachable_from(path: &Path, from: &Path) -> bool {
        let mut current = path.clone();
        loop {
            if current.ptr_eq(from) {
                return true;
            }
            match current.parent() {
                Some(parent) => current = parent,
                None => return false,
            }
        }
    }

fn add_child(
        &mut self,
        name: impl Into<String>,
        factory: impl for<'a, 'b> Fn(SimpleDirLookup<'a>, &'b str) -> VfsResult<Dentry>
        + Send
        + Sync
        + 'static,
    ) {
        self.entries.lock().insert(
            name.into(),
            Arc::new(move |parent, name| {
                let parent = parent.as_ref().ok_or(VfsError::InvalidInput)?;
                factory(SimpleDirLookup::new(parent), name)
            }),
        );
    }

fn lookup_bdev(
        &mut self,
        file_system_type: &'static FileSystemType,
        block_device: &Arc<block::BlockDevice>,
        live_refs: &mut Vec<Arc<SuperBlock>>,
    ) -> Option<Arc<SuperBlock>> {
        let mut matching = None;
        self.super_blocks
            .retain(|registered| match registered.upgrade() {
                Some(super_block) => {
                    if matching.is_none()
                        && core::ptr::eq(super_block.file_system_type(), file_system_type)
                        && super_block.block_device().is_some_and(|registered_device| {
                            Arc::ptr_eq(registered_device, block_device)
                        })
                    {
                        matching = Some(super_block.clone());
                    }
                    // A temporary Weak upgrade can become the final owner.
                    // Defer its drop so driver release cannot reenter this lock.
                    live_refs.push(super_block);
                    true
                }
                None => false,
            });
        matching
    }

