fn user_namespace_follows_inode_type_and_dac() {
    let name = XattrName::new(b"user.test".to_vec()).unwrap();
    let owner = Cred::new(1000, 1000);
    let other = Cred::new(2000, 2000);
    let regular = inode(NodeType::RegularFile, 0o600, 1000);
