fn step_into(
        &mut self,
        containing_dir: &Path,
        next: Path,
        component: WalkComponent,
        cred: &Cred,
    ) -> VfsResult<Path> {
        if d_inode(next.dentry()).magic_link().is_some() {
            if self.flags.rejects_magic_links() {
                return Err(VfsError::FilesystemLoop);
            }
            if component == WalkComponent::More || self.flags.follows_final() {
                return self.follow_magic_link(next);
            }
            return Ok(next);
        }

        if d_is_symlink(next.dentry())
            && (component == WalkComponent::More || self.flags.follows_final())
        {
            return self.follow_symlink(containing_dir, next, cred);
        }
        Ok(next)
    }

fn add_access(state: &mut PipeState, access: PipeAccess) -> KResult<(bool, bool)> {
    let readers = access
        .can_read()
        .then(|| state.readers.checked_add(1).ok_or(KError::ResourceBusy))
        .transpose()?;
    let writers = access
        .can_write()
        .then(|| state.writers.checked_add(1).ok_or(KError::ResourceBusy))
        .transpose()?;
    let wake_writers = readers.is_some() && state.readers == 0;
    let wake_readers = writers.is_some() && state.writers == 0;

    if let Some(readers) = readers {
        state.readers = readers;
        state.r_counter = state.r_counter.wrapping_add(1);
    }
    if let Some(writers) = writers {
        state.writers = writers;
        state.w_counter = state.w_counter.wrapping_add(1);
    }
    Ok((wake_readers, wake_writers))
}

