fn static_entries_preserve_inode_identity_after_dentry_invalidation() {
    let super_block = SimpleFs::new_with(&TEST_FILE_SYSTEM_TYPE, 0, |fs| {
        let mut entries = DirMapping::new();
        entries.add(
            "file",
