fn panic() {
    use std::panic;

    static INIT: Once = Once::new();

    // poison the once
    let t = panic::catch_unwind(|| {
        INIT.call_once(|| panic!());
    });
    assert!(t.is_err());

    // poisoning propagates
    let t = panic::catch_unwind(|| {
        INIT.call_once(|| {});
    });
    assert!(t.is_err());
}

fn register_inode(&self, inode: &Arc<VfsInode>) {
        let mut inodes = self.inodes.lock();
        inodes.retain(|existing| match existing.upgrade() {
            Some(existing) => !Arc::ptr_eq(&existing, inode),
            None => false,
        });
        inodes.push(Arc::downgrade(inode));
    }

fn read(&self, _file: &VfsFile, buf: &mut [u8], offset: u64) -> VfsResult<usize> {
        let data = self.data.lock();
        let offset = offset as usize;
        if offset >= data.len() {
            return Ok(0);
        }
        let count = buf.len().min(data.len() - offset);
        buf[..count].copy_from_slice(&data[offset..offset + count]);
        Ok(count)
    }

fn test_chown_without_new_ids_requires_fowner_to_clear_setid() {
    let regular = || {
        let fs = mock_regular_file_filesystem(NodePermission::from_bits_truncate(0o6666));
        Mount::new_root(&fs).root_path()
    };
    let unprivileged = Cred::new(2000, 200);

    let denied = regular();
    assert_eq!(
        denied.chown(None, None, &unprivileged),
        Err(VfsError::OperationNotPermitted)
    );
    assert_eq!(denied.metadata().mode.permission().bits(), 0o6666);

    let mut fowner = Cred::root();
    fowner.set_fsuid(2000);
    let fowner_set = kcred::CapSet::from_bits(1u64 << kcred::CAP_FOWNER);
    fowner
        .set_capabilities(kcred::CapSets::new(
            fowner_set,
            fowner_set,
            kcred::CapSet::EMPTY,
        ))
        .unwrap();
    let allowed = regular();
    allowed.chown(None, None, &fowner).unwrap();
    // The caller is neither in the file's group nor holds CAP_FSETID, so the
    // SGID bit is dropped together with the always-dropped SUID bit.
    assert_eq!(allowed.metadata().mode.permission().bits(), 0o666);

    let mut chown_only = Cred::root();
    chown_only.set_fsuid(2000);
    let chown_set = kcred::CapSet::from_bits(1u64 << kcred::CAP_CHOWN);
    chown_only
        .set_capabilities(kcred::CapSets::new(
            chown_set,
            chown_set,
            kcred::CapSet::EMPTY,
        ))
        .unwrap();
    let denied = regular();
    assert_eq!(
        denied.chown(None, None, &chown_only),
        Err(VfsError::OperationNotPermitted)
    );
    assert_eq!(denied.metadata().mode.permission().bits(), 0o6666);
}

fn test_chown_new_group_drops_sgid_on_generated_mode_change() {
    let regular = || {
        let fs = mock_regular_file_filesystem(NodePermission::from_bits_truncate(0o6666));
        Mount::new_root(&fs).root_path()
    };
    let mut cap_chown = Cred::root();
    cap_chown.set_fsuid(2000);
    cap_chown.set_fsgid(100);
    let chown_set =
        kcred::CapSet::from_bits((1u64 << kcred::CAP_CHOWN) | (1u64 << kcred::CAP_FOWNER));
    cap_chown
        .set_capabilities(kcred::CapSets::new(
            chown_set,
            chown_set,
            kcred::CapSet::EMPTY,
        ))
        .unwrap();

    // CAP_CHOWN allows an arbitrary new GID and CAP_FOWNER authorizes the
    // generated mode update. Removing set-UID then also drops set-GID because
    // the caller is not a member of the new group and lacks CAP_FSETID.
    let changed = regular();
    changed.chown(None, Some(300), &cap_chown).unwrap();
    let metadata = changed.metadata();
    assert_eq!(metadata.gid, 300);
    assert_eq!(metadata.mode.permission().bits(), 0o666);

    // Membership in the new group satisfies setattr_prepare()/setattr_copy(),
    // so set-GID survives the same generated mode change.
    let mut member = Cred::root();
    member.set_fsuid(2000);
    member.set_fsgid(100);
    member.set_supplementary_groups(vec![300]);
    member
        .set_capabilities(kcred::CapSets::new(
            chown_set,
            chown_set,
            kcred::CapSet::EMPTY,
        ))
        .unwrap();
    let retained = regular();
    retained.chown(None, Some(300), &member).unwrap();
    let metadata = retained.metadata();
    assert_eq!(metadata.gid, 300);
    assert_eq!(metadata.mode.permission().bits(), 0o2666);
}

fn mknod_at_entry(
        &self,
        root: &Path,
        base: &Path,
        mode: Umode,
        device: DeviceId,
        umask: NodePermission,
        cred: &Cred,
    ) -> VfsResult<CreatedEntry> {
        let node_type = may_mknod(mode)?;
        let mode = mode.with_node_type(node_type);
        let (parent, last, has_trailing_slash) = self
            .parent_at(root, base, LookupIntent::Open, cred)?
            .into_create()?;
        let name = last.as_str();
        let device = if matches!(node_type, NodeType::CharacterDevice | NodeType::BlockDevice) {
            device
        } else {
            DeviceId::default()
        };

        let path = parent
            .dentry()
            .as_dir()?
            .create_exclusive_with(name, |candidate| {
                if has_trailing_slash {
                    return Err(VfsError::NotFound);
                }
                if node_type == NodeType::RegularFile {
                    parent.vfs_create(candidate, mode, umask, true, cred)
                } else {
                    parent.vfs_mknod(candidate, mode, device, umask, cred)
                }
            })
            .map(|entry| parent.with_dentry(entry))?;
        Ok(CreatedEntry {
            path,
            name: String::from(name),
            parent: parent.inode(),
        })
    }

fn readahead(&self, control: &mut crate::ReadaheadControl<'_>) -> VfsResult<()> {
        assert_eq!(control.index(), 5);
        assert_eq!(control.count(), 3);
        while control.count() != 0 {
            control.complete_folio(&vec![0x55; PAGE_SIZE_4K])?;
        }
        Ok(())
    }

fn _push(&mut self, path: Pathname<'_>) {
        if path.as_str().is_empty() {
            return;
        }
        if path.is_absolute() {
            self.inner.clear();
        } else if !self.inner.ends_with('/') {
            self.inner.push('/');
        }
        self.inner += path.as_str();
    }

fn has_mount_under(&self, path: &Path) -> bool {
        let source = path.mount();
        let mounts = self.mounts.lock();
        mounts.values().any(|mount| {
            !Arc::ptr_eq(mount, source)
                && mount
                    .location()
                    .is_some_and(|loc| Self::is_reachable_from(&loc, path))
        })
    }

