fn read_link(&self, dentry: &Dentry) -> VfsResult<String> {
        if self.operation_flags() & IOP_CACHED_LINK != 0
            && let Some(link) = self.cached_link()
        {
            return Ok(link);
        }
        let mut done = crate::DelayedCall;
        self.require_symlink_operations()?
            .get_link(Some(dentry), self, &mut done)
    }

fn parent_lock_order(&self) -> VfsResult<(bool, Option<Dentry>)> {
        let mut old_ancestor = self.old_parent.clone();
        while let Some(parent) = old_ancestor.parent() {
            if parent.ptr_eq(self.new_parent) {
                return Ok((false, Some(old_ancestor)));
            }
            old_ancestor = parent;
        }

        let old_root = old_ancestor;
        let mut new_ancestor = self.new_parent.clone();
        while let Some(parent) = new_ancestor.parent() {
            if parent.ptr_eq(self.old_parent) {
                return Ok((true, Some(new_ancestor)));
            }
            if parent.ptr_eq(&old_root) {
                // Unrelated directories. Order them ancestor-first then by a
                // stable pointer key, the same rule `pivot_root` uses for its
                // parent-directory locks, instead of the role-based old-first
                // order.
                return Ok((
                    self.old_parent.namespace_lock_key() < self.new_parent.namespace_lock_key(),
                    None,
                ));
            }
            new_ancestor = parent;
        }
        Err(VfsError::CrossesDevices)
    }

fn flock(&self, file: &VfsFile, request: &crate::FileLock, is_blocking: bool) -> VfsResult<()> {
        if request.kind() == crate::FileLockType::Unlock
            && file.inode().existing_file_locks().is_none()
        {
            return Ok(());
        }
        file.inode().file_locks()?.apply(request, is_blocking)
    }

fn size(&self) -> u64 {
        let inode = self.inode();
        if inode.node_type() == NodeType::BlockDevice
            && let Some(claim) = self.private_data_get::<block::BlockDeviceClaim>()
        {
            return claim.device().size();
        }
        inode.size()
    }

fn update(&mut self, request: &FileLock, waiter: Option<&Waiter>, wake: &mut WakeQueue) {
        let mut list = core::mem::take(if request.owner.is_flock() {
            &mut self.flock
        } else {
            &mut self.posix
        });
        let (mut start, mut end) = request.bounds();
        let mut remaining = LockList::new();
        let mut merged = None;
        while let Some(mut lock) = list.pop_front() {
            let record = lock.record();
            if record.owner != request.owner {
                remaining.push_back(lock);
                continue;
            }
            if record.kind == request.kind && record.end() >= start - 1 && record.start() - 1 <= end
            {
                start = start.min(record.start());
                end = end.max(record.end());
                if merged.is_none() {
                    // Preserve the first record's identity and descendants.
                    // Expansion needs neither allocation nor the global lock.
                    merged = Some(lock);
                } else {
                    lock.detach_blocked(wake);
                }
            } else if record.start() <= end && start <= record.end() {
                lock.detach_blocked(wake);
                if record.start() < start && record.end() > end {
                    let split = OwnedLock::new(FileLock::range(
                        record.owner,
                        record.pid,
                        record.kind,
                        end + 1,
                        record.end(),
                    ));
                    lock.set_bounds(record.start(), start - 1);
                    remaining.push_back(lock);
                    remaining.push_back(split);
                    Self::append_remaining(&mut list, &mut remaining);
                    break;
                }
                if record.start() < start {
                    lock.set_bounds(record.start(), start - 1);
                    remaining.push_back(lock);
                } else if record.end() > end {
                    lock.set_bounds(end + 1, record.end());
                    remaining.push_back(lock);
                }
            } else {
                remaining.push_back(lock);
            }
        }
        if request.kind != FileLockType::Unlock {
            let lock = if let Some(mut lock) = merged {
                lock.set_bounds(start, end);
                lock
            } else {
                OwnedLock::new(FileLock::range(
                    request.owner,
                    request.pid,
                    request.kind,
                    start,
                    end,
                ))
            };
            Self::install(&mut remaining, lock, waiter);
        }
        if request.owner.is_flock() {
            self.flock = remaining;
        } else {
            self.posix = remaining;
        }
    }

