fn file_wait_rechecks_after_signal_and_releases_registrations() {
    let _cleanup = InterruptCleanup;
    ktask::current().clear_interrupt();
    let input = Input::new();
    let wakes = Arc::new(WakeCount::default());
    let waker = Waker::from(wakes.clone());
    let mut cx = Context::from_waker(&waker);
    let mut wait = Box::pin(poll_file_io(&input, IoEvents::IN, false, || input.read()));
    assert_eq!(wait.as_mut().poll(&mut cx), Poll::Pending);
    input.value.set(7);
    input.events.wake();
    assert!(wakes.0.load(Ordering::Relaxed) > 0);
    ktask::current().interrupt();
    assert_eq!(wait.as_mut().poll(&mut cx), Poll::Ready(Ok(7)));
    drop(wait);
    assert_eq!(input.value.get(), 0);
    wakes.0.store(0, Ordering::Relaxed);
    input.events.wake();
    ktask::current().interrupt();
    assert_eq!(wakes.0.load(Ordering::Relaxed), 0);

    ktask::current().clear_interrupt();
    let mut wait = Box::pin(poll_file_io(&input, IoEvents::IN, false, || input.read()));
    assert_eq!(wait.as_mut().poll(&mut cx), Poll::Pending);
    drop(wait);
    wakes.0.store(0, Ordering::Relaxed);
    input.events.wake();
    ktask::current().interrupt();
    assert_eq!(wakes.0.load(Ordering::Relaxed), 0);
}

fn deactivate_mount(&self) {
        // Like Linux `deactivate_super()`, do not consume the final active
        // reference until final shutdown is serialized by `s_umount`.
        if !self.lifecycle.lock().release_unless_last() {
            return;
        }

        let _umount_guard = self.umount_lock.lock();
        // A concurrent activation may have made this reference non-final while
        // the umount lock was being acquired.
        if !self.lifecycle.lock().begin_shutdown() {
            return;
        }

        let shutdown_result = self.shutdown();
        // Keep the Dying identity visible until the driver has closed. A
        // same-filesystem sget waits; driver callbacks run outside the registry.
        self.release_block_device();
        {
            let mut super_blocks = super_block_registry().super_blocks.lock();
            *self.lifecycle.lock() = SuperBlockLifecycle::Dead;
            super_blocks.unregister(self);
        }
        self.lifecycle_waiters.notify_all(false);
        if let Err(err) = shutdown_result {
            log::warn!(
                "failed to shut down {} after its last active mount: {err:?}",
                self.name()
            );
        }
    }

