            fill_test_bdev,
        )
        .unwrap();
    let mount = crate::Mount::new_root(&sb);
    let open = || {
        let mut builder = crate::VfsFileBuilder::from_path_state(
            mount.root_path(),
            crate::FMode::READ,
            crate::OpenFlags::empty(),
            Arc::new(FileOps),
            kcred::initial_cred(),
        );
        builder.mark_opened().unwrap();
        builder.finish().unwrap()
    };
    let set = |sectors| {
        device
            .as_ref()
            .ioctl(
                block::BlockOpenMode::READ,
                linux_raw_sys::ioctl::BLKRASET,
                sectors,
                true,
                || panic!("setter uses an immediate value"),
                |_| panic!("setter has no output"),
            )
            .unwrap()
    };
    set(8);
    let first = open();
    assert_eq!(first.readahead.lock().on_miss(0, 1, |_| 0).0, 0..1);
    set(64);
    let second = open();
    assert_eq!(second.readahead.lock().on_miss(0, 1, |_| 0).0, 0..2);
    assert_eq!(first.readahead.lock().on_miss(100, 8, |_| 0).0, 100..101);
    set(0);
    assert!(!open().readahead.lock().is_enabled());
    assert!(first.readahead.lock().is_enabled());
    drop(first);
    drop(second);
    drop(mount);
    drop(sb);
    block::del_gendisk(disk.device_number()).unwrap();
}

fn rename_tracked(
        &self,
        old_name: &str,
        new_dir: &Self,
        new_name: &str,
        flags: RenameFlags,
        cred: &Cred,
    ) -> VfsResult<RenameOutcome> {
        if !Arc::ptr_eq(&self.mnt, &new_dir.mnt) {
            return Err(VfsError::CrossesDevices);
        }
        self.check_writable_mount()?;

        // The identities the event sources need are captured here, inside the
        // callback the rename runs under its namespace lock, from the very
        // dentries being moved and replaced. A path lookup afterwards could
        // describe a different object entirely. Only the replacement link
        // count needs a backend metadata query.
        let mut moved = false;
        let mut source_meta = None;
        let mut replaced_meta = None;
        let mut replaced_nlink = None;
        self.dentry.as_dir()?.rename_with(
            old_name,
            new_dir.dentry.as_dir()?,
            new_name,
            flags,
            |source, target| {
                // The callback only runs when the rename really moves an
                // entry: kvfs returns early, without calling it, for a rename
                // between two links of one inode.
                moved = true;
                self.may_modify_directory(cred)?;
                if !self.ptr_eq(new_dir) {
                    new_dir.may_modify_directory(cred)?;
                }

                let old_path = self.with_dentry(source.clone());
                self.check_sticky(&old_path, cred)?;
                old_path.check_not_mountpoint()?;
                // The source's type is all the move halves need, and the
                // cached copy has it; the replaced target's `nlink` drives a
                // retirement decision, so it is read authoritatively.
                source_meta = Some(old_path.inode());
                if target.is_really_positive() {
                    let new_path = new_dir.with_dentry(target.clone());
                    new_dir.check_sticky(&new_path, cred)?;
                    new_path.check_not_mountpoint()?;
                    replaced_meta = Some(new_path.inode());
                    replaced_nlink = Some(
                        new_path
                            .getattr()
                            .map_or_else(|_| new_path.identity().nlink, |meta| meta.nlink),
                    );
                }
                Ok(())
            },
        )?;
        Ok(RenameOutcome {
            moved,
            source: source_meta,
            replaced: replaced_meta,
            replaced_nlink,
        })
    }

fn install(list: &mut LockList, lock: OwnedLock, waiter: Option<&Waiter>) {
        if let Some(waiter) = waiter {
            lock.accept_waiters(waiter);
        }
        let record = lock.record();
        let key = (record.owner, record.start());
        let mut sorted = LockList::new();
        while list
            .iter()
            .next()
            .is_some_and(|entry| (entry.owner, entry.start()) < key)
        {
            if let Some(entry) = list.pop_front() {
                sorted.push_back(entry);
            }
        }
        sorted.push_back(lock);
        Self::append_remaining(list, &mut sorted);
        *list = sorted;
    }

fn set_times(
        &self,
        atime: Option<SetattrTime>,
        mtime: Option<SetattrTime>,
        cred: &Cred,
    ) -> VfsResult<()> {
        if atime.is_none() && mtime.is_none() {
            return Ok(());
        }

        self.check_writable_mount()?;
        let metadata = self.metadata();
        let is_owner = cred.fsuid() == metadata.uid;
        let is_touch = matches!(
            (atime, mtime),
            (Some(SetattrTime::Current(_)), Some(SetattrTime::Current(_)))
        );
        if !is_touch {
            if !is_owner && !cred.has_cap_fowner() {
                return Err(VfsError::OperationNotPermitted);
            }
        } else if !is_owner && !cred.has_cap_fowner() {
            self.permission(Permission::MAY_WRITE, cred)?;
        }

        self.dentry.update_metadata(MetadataUpdate {
            atime: atime.map(SetattrTime::value),
            mtime: mtime.map(SetattrTime::value),
            ..Default::default()
        })
    }

fn sync_readahead(&self, offset: u64, count: usize, file_len: u64) -> u64 {
        let end = offset.saturating_add(count as u64).min(file_len);
        self.prepare_readahead(
            offset / PAGE_SIZE_4K as u64..end.div_ceil(PAGE_SIZE_4K as u64),
            None,
            file_len,
        );
        end
    }

fn new(name: Vec<u8>) -> VfsResult<Self> {
        if name.is_empty() || name.len() > XATTR_NAME_MAX || name.contains(&0) {
            return Err(VfsError::from(LinuxError::ERANGE));
        }
        Ok(Self(name))
    }

fn readahead(&self, control: &mut crate::ReadaheadControl<'_>) -> VfsResult<()> {
        assert!(
            control.count() > 1,
            "single reservations must use read_folio"
        );
        while control.count() != 0 {
            let page = vec![control.index() as u8; PAGE_SIZE_4K];
            control.complete_folio(&page)?;
        }
        Ok(())
    }

const fn from_mode_type(value: u8) -> Self {
        match value {
            0o1 => Self::Fifo,
            0o2 => Self::CharacterDevice,
            0o4 => Self::Directory,
            0o6 => Self::BlockDevice,
            0o10 => Self::RegularFile,
            0o12 => Self::Symlink,
            0o14 => Self::Socket,
            _ => Self::Unknown,
        }
    }

fn mknod(
        &self,
        _idmap: &crate::MountIdmap,
        dir: &VfsInode,
        dentry: &LockedDentry<'_>,
        mode: Umode,
        device: DeviceId,
        cred: &kcred::Cred,
    ) -> VfsResult<()> {
        if !matches!(
            mode.node_type(),
            NodeType::CharacterDevice | NodeType::BlockDevice | NodeType::Fifo | NodeType::Socket
        ) {
            return Err(VfsError::InvalidInput);
        }

        let parent = dentry.parent().ok_or(VfsError::InvalidInput)?;
        let (mode, uid, gid) = inode_init_owner(dir, mode, cred);
        let node = Arc::new(SimpleFsNode::new_with_owner(
            self.dir.node.filesystem(),
            mode.node_type(),
            mode.permission(),
            uid,
            gid,
        ));
        node.set_rdev(device);
        let init = node.inode_init();
        let inode = VfsInode::new_special(node, NodeFlags::empty(), init);
        let entry =
            self.dir
                .ops
                .create_inode_child(SimpleDirLookup::new(&parent), dentry.name(), inode)?;
        let inode = entry.vfs_inode();
        drop(entry);
        dentry.instantiate(inode)
    }

