fn lookup(&self, super_block: &Arc<SuperBlock>, inode_number: u64) -> Option<Arc<VfsInode>> {
        let key = InodeCacheKey::from_super_block(super_block, inode_number);
        loop {
            let waiters = {
                let inodes = self.inodes.lock();
                match inodes.get(&key) {
                    None => return None,
                    Some(entry) => match &entry.state {
                        CachedInodeState::Live(inode) => match inode.upgrade() {
                            Some(inode) => return Some(inode),
                            None => entry.waiters.clone(),
                        },
                        CachedInodeState::New | CachedInodeState::Freeing(_) => {
                            entry.waiters.clone()
                        }
                    },
                }
            };
            self.wait_for_transition(&key, &waiters);
        }
    }

fn read_folios(
        &mut self,
        mut read: impl FnMut(&AddressSpace, FolioRead) -> VfsResult<()>,
    ) -> VfsResult<()> {
        let mut result = Ok(());
        while let Some(folio) = self.next_folio() {
            let attempt = read(self.address_space, folio);
            // Attempt every reserved page, preserving the first read error.
            result = result.and(attempt);
        }
        result
    }

