fn splice_to(
        &self,
        destination: &Self,
        len: usize,
        nonblocking: bool,
    ) -> KResult<usize> {
        if len == 0 {
            return Ok(0);
        }
        if core::ptr::eq(self, destination) {
            return Err(KError::InvalidInput);
        }
        let wait = PipeTransferWait {
            source: self,
            destination,
        };
        let result = block_on(poll_file_io(
            &wait,
            IoEvents::IN | IoEvents::OUT,
            nonblocking,
            || {
                let (mut source, mut target) =
                    if core::ptr::from_ref(self) < core::ptr::from_ref(destination) {
                        let source = self.state.lock();
                        (source, destination.state.lock())
                    } else {
                        let target = destination.state.lock();
                        (self.state.lock(), target)
                    };
                if target.readers == 0 {
                    drop(target);
                    drop(source);
                    let _ = send_sig_current(Signo::SIGPIPE);
                    return Err(KError::BrokenPipe);
                }
                if source.buffer.is_empty() && source.writers == 0 {
                    return Ok(0);
                }
                let count = len.min(source.buffer.len()).min(target.available());
                if count == 0 {
                    return Err(KError::WouldBlock);
                }
                target.buffer.extend(source.buffer.drain(..count));
                Ok(count)
            },
        ));
        if matches!(result, Ok(count) if count > 0) {
            ktask::with_wake_sync(|| {
                self.wr_wait.wake();
                destination.rd_wait.wake();
            });
        }
        result
    }

fn get_or_try_init_bdev<F>(
        &self,
        file_system_type: &'static FileSystemType,
        block_device: Arc<block::BlockDevice>,
        flags: SuperBlockFlags,
        fill_super: F,
    ) -> VfsResult<Arc<SuperBlock>>
    where
        F: FnOnce(&Arc<SuperBlock>) -> VfsResult<()>,
    {
        let mut fill_super = Some(fill_super);
        loop {
            let mut live_refs = Vec::new();
            let (super_block, is_new) = {
                let mut super_blocks = self.super_blocks.lock();
                match super_blocks.lookup_bdev(file_system_type, &block_device, &mut live_refs) {
                    Some(super_block) => (super_block, false),
                    None => {
                        let candidate = SuperBlock::allocate(
                            file_system_type,
                            Some(block_device.clone()),
                            flags,
                        );
                        super_blocks.register(&candidate);
                        (candidate, true)
                    }
                }
            };
            drop(live_refs);
            if is_new {
                let fill_super = fill_super
                    .take()
                    .expect("a fill callback is consumed only by a new superblock");
                let initialize = || -> VfsResult<()> {
                    let mut mode = block::BlockOpenMode::READ | block::BlockOpenMode::EXCLUSIVE;
                    mode.set(
                        block::BlockOpenMode::WRITE,
                        !flags.contains(SuperBlockFlags::RDONLY),
                    );
                    let claim = block_device.open(mode, Some(super_block.clone()))?;
                    super_block.block_device_claim.call_once(|| claim);
                    validate_block_device_flags(&block_device, flags)?;
                    fill_super(&super_block)
                };
                match initialize() {
                    Ok(()) => super_block.finish_initialization(),
                    Err(error) => {
                        super_block.release_block_device();
                        {
                            let mut super_blocks = self.super_blocks.lock();
                            super_block.fail_initialization();
                            super_blocks.unregister(&super_block);
                        }
                        super_block.lifecycle_waiters.notify_all(false);
                        return Err(error);
                    }
                }
                return Ok(super_block);
            }

            if !super_block.wait_until_available_or_dead() {
                continue;
            }
            if bdev_readonly_mismatch(super_block.flags(), flags) {
                return Err(VfsError::ResourceBusy);
            }
            return Ok(super_block);
        }
    }

fn try_call_once_err() {
    let once = Once::<_>::new();
    let shared = Arc::new((once, AtomicU32::new(0)));

    let (tx, rx) = channel();

    let t0 = {
        let shared = shared.clone();
        thread::spawn(move || {
            let (once, called) = &*shared;

            let result = once.try_call_once(|| {
                called.fetch_add(1, Ordering::AcqRel);
                tx.send(()).unwrap();
                thread::sleep(std::time::Duration::from_millis(50));
                Err(())
            });
            assert_eq!(result, Err(()));
        })
    };

    let t1 = {
        let shared = shared.clone();
        thread::spawn(move || {
            rx.recv().unwrap();
            let (once, called) = &*shared;
            assert_eq!(
                called.load(Ordering::Acquire),
                1,
                "leader thread did not run first"
            );

            once.call_once(|| {
                called.fetch_add(1, Ordering::AcqRel);
            });
        })
    };

    t0.join().unwrap();
    t1.join().unwrap();

    assert_eq!(shared.1.load(Ordering::Acquire), 2);
}

