fn cdev_ranges_validate_bounds_overlap_and_exact_removal() {
    let mut registry = ChrdevRegistry::new();
    let ops: Arc<dyn DeviceFileOps> = Arc::new(TestDeviceOps);
    assert_eq!(
        add_test_range(&mut registry, DeviceId::new(240, 10), 0, &ops),
        Err(VfsError::InvalidInput)
    );
    assert_eq!(
        add_test_range(&mut registry, DeviceId::new(240, u32::MAX), 2, &ops),
        Err(VfsError::InvalidInput)
    );
    add_test_range(&mut registry, DeviceId::new(240, u32::MAX), 1, &ops).unwrap();
    assert!(registry.get(DeviceId::new(240, u32::MAX)).is_some());
    add_test_range(&mut registry, DeviceId::new(240, 10), 3, &ops).unwrap();
    for minor in [10, 11, 12] {
        assert!(Arc::ptr_eq(
            &registry.get(DeviceId::new(240, minor)).unwrap().ops,
            &ops
        ));
    }
    for minor in [9, 13] {
        assert!(registry.get(DeviceId::new(240, minor)).is_none());
    }
    assert!(registry.get(DeviceId::new(241, 10)).is_none());
    for (first, count) in [(9, 2), (10, 3), (11, 1), (12, 2), (9, 5)] {
        assert_eq!(
            add_test_range(&mut registry, DeviceId::new(240, first), count, &ops),
            Err(VfsError::ResourceBusy)
        );
    }
    add_test_range(&mut registry, DeviceId::new(240, 13), 1, &ops).unwrap();
    add_test_range(&mut registry, DeviceId::new(241, 10), 3, &ops).unwrap();
    for (first, count) in [(10, 0), (10, 2), (10, 4), (11, 2)] {
        assert!(registry.del(DeviceId::new(240, first), count).is_none());
    }
    let entry = registry.get(DeviceId::new(240, 11)).unwrap();
    drop(registry.del(DeviceId::new(240, 10), 3).unwrap());
    assert!(entry.live_operations().is_none());
    assert!(registry.get(DeviceId::new(240, 11)).is_none());
    assert!(registry.get(DeviceId::new(240, 13)).is_some());
    assert!(registry.get(DeviceId::new(241, 11)).is_some());
}

fn read(&mut self, output: &mut [u8], offset: u64) -> VfsResult<usize> {
        if offset == 0 {
            self.reset();
        } else if offset != self.last_file_offset {
            self.reset();
            self.seek_to(offset)?;
        }

        let mut total_written = 0;
        let mut output_cursor = 0;

        while output_cursor < output.len() {
            let available = self.buf.len().saturating_sub(self.buf_read_pos);
            if available > 0 {
                let to_copy = min(available, output.len() - output_cursor);
                output[output_cursor..output_cursor + to_copy].copy_from_slice(
                    &self.buf.as_bytes()[self.buf_read_pos..self.buf_read_pos + to_copy],
                );
                output_cursor += to_copy;
                self.buf_read_pos += to_copy;
                self.last_file_offset += to_copy as u64;
                total_written += to_copy;
                continue;
            }

            if self.is_eof {
                break;
            }

            if !self.fill_next_entry()? {
                break;
            }
        }

        Ok(total_written)
    }

fn d_move(
        &self,
        src: &Dentry,
        dst_dir: &Self,
        dst: &Dentry,
        destination_name: String,
        keys: (&DentryKey, &DentryKey),
    ) {
        dst.mark_unlinked();
        if dst.is_really_positive()
            && let Ok(dir) = dst.as_dir()
        {
            dir.forget();
        }

        let source_location = src.0.location.read();
        let target_location = dst.0.location.read();
        if self.ptr_eq(dst_dir) {
            let mut children = self.0.children.lock();
            children.remove(source_location.name.as_str());
            if let Some(target_slot) = children.get_mut(target_location.name.as_str()) {
                *target_slot = Arc::downgrade(&src.0);
            }
        } else {
            self.0.children.lock().remove(source_location.name.as_str());
            if let Some(target_slot) = dst_dir
                .0
                .children
                .lock()
                .get_mut(target_location.name.as_str())
            {
                *target_slot = Arc::downgrade(&src.0);
            }
        }
        drop(target_location);
        drop(source_location);

        if let Some(super_block) = src.super_block() {
            super_block.move_cached_dentry(keys.0, keys.1, src);
        }
        src.rebind(Some(dst_dir.clone()), destination_name);
    }

