fn new_with_dentry_operations(
        file_system_type: &'static FileSystemType,
        ops: &'static dyn SuperBlockOperations,
        dentry_operations: &'static dyn DentryOperations,
        magic: u32,
        block_size: u64,
        max_file_size: u64,
        init_root_fn: impl FnOnce(&Arc<Self>) -> Dentry,
    ) -> Arc<Self> {
        let super_block = Self::allocate(file_system_type, None, SuperBlockFlags::empty());
        super_block.magic.call_once(|| magic);
        match super_block.initialize_inner(
            ops,
            Some(dentry_operations),
            None,
            block_size,
            max_file_size,
            |super_block| Ok::<_, core::convert::Infallible>(init_root_fn(super_block)),
        ) {
            Ok(()) => {}
            Err(error) => match error {},
        }
        super_block.finish_initialization();
        super_block_registry().register(&super_block);
        super_block
    }

fn open(self: Arc<Self>, inode: &VfsInode, file: &mut VfsFileBuilder) -> VfsResult<()> {
        // The device controller gates block opens too (`devcgroup_inode_
        // permission` covers every device inode), reporting the open mode's
        // access bits with the block type.
        let access = device_access_for_mode(file) | DeviceAccess::TYPE_BLOCK;
        check_device_access(inode.rdev(), access)?;
        let device = block::lookup_block_device(inode.rdev())
            .ok_or_else(|| VfsError::from(LinuxError::ENXIO))?;
        let mode = block_open_mode(file.mode(), file.flags());
        let claim = device.open(mode, None)?;
        file.set_private_data(claim);
        Ok(())
    }

