fn call_once_test() {
    for _ in 0..20 {
        use std::{
            sync::{Arc, atomic::AtomicUsize},
            time::Duration,
        };
        let share = Arc::new(AtomicUsize::new(0));
        let once = Arc::new(Once::<_>::new());
        let mut hs = Vec::new();
        for _ in 0..8 {
            let h = thread::spawn({
                let share = share.clone();
                let once = once.clone();
                move || {
                    thread::sleep(Duration::from_millis(10));
                    once.call_once(|| {
                        share.fetch_add(1, Ordering::SeqCst);
                    });
                }
            });
            hs.push(h);
        }
        for h in hs {
            h.join().unwrap();
        }
        assert_eq!(1, share.load(Ordering::SeqCst));
    }
}

fn llseek(&self, file: &VfsFile, offset: i64, whence: i32) -> VfsResult<u64> {
        if file.is_stream() || matches!(file.inode().node_type(), NodeType::Fifo | NodeType::Socket)
        {
            return Err(VfsError::from(LinuxError::ESPIPE));
        }

        let mut position = file.position_lock();
        let base = match whence {
            SEEK_SET => 0,
            SEEK_CUR => *position as i64,
            // The capacity view: `blkdev_llseek` reads `bd_inode`'s size
            // (block/fops.c:533), unlike record locks which read the node
            // inode (locks.c:465) — the two SEEK_END bases differ by design.
            SEEK_END => file.size() as i64,
            _ => return Err(VfsError::InvalidInput),
        };
        let new_offset = base.checked_add(offset).ok_or(VfsError::InvalidInput)?;
        if new_offset < 0 {
            return Err(VfsError::InvalidInput);
        }
        let new_offset = new_offset as u64;
        // Block devices bound seeks to the capacity (`blkdev_llseek` uses
        // `fixed_size_llseek`, EINVAL past the end); regular files may seek
        // past EOF.
        if file.inode().node_type() == NodeType::BlockDevice && new_offset > file.size() {
            return Err(VfsError::from(LinuxError::EINVAL));
        }
        *position = new_offset;
        Ok(new_offset)
    }

fn truncate_partial_page_growth_zeros_cached_old_eof() {
    let old_len = (PAGE_SIZE_4K / 4) as u64;
    let new_len = (PAGE_SIZE_4K / 2) as u64;
    let inode = VfsInode::new_file_with_address_space_and_flags(
        Arc::new(TruncateOps),
        NodeFlags::ALWAYS_CACHE,
        &TRUNCATE_OPERATIONS,
        VfsInodeInit::new(
            3,
            old_len,
            Umode::new(NodeType::RegularFile, NodePermission::default()),
        ),
    );
    let address_space = inode.address_space();
    let stale = vec![0x5a; PAGE_SIZE_4K];
    address_space
        .i_pages
        .filemap_add_folio(super::folio_from_bytes(0, &stale))
        .unwrap_or_else(|_| panic!("fixture index is absent"));

    inode
        .set_len(new_len)
        .expect("partial-page growth succeeds");

    assert_eq!(inode.size(), new_len);
    address_space
        .with_folio(0, |folio| {
            let data = folio.expect("EOF folio remains cached").data();
            assert!(data[..old_len as usize].iter().all(|byte| *byte == 0x5a));
            assert!(
                data[old_len as usize..new_len as usize]
                    .iter()
                    .all(|byte| *byte == 0)
            );
        })
        .unwrap();
}

