fn path_lookupat(&mut self, base: &Path, cred: &Cred) -> VfsResult<Path> {
        let path = self.link_path_walk(base, cred)?;
        if self.pathname.is_empty() {
            return self.complete_path_lookup(path);
        }
        if self.last_type == LastType::Norm && self.has_trailing_slashes() {
            self.flags |= LookupFlags::FOLLOW_FINAL | LookupFlags::DIRECTORY;
        }
        match self.last_type {
            LastType::Root | LastType::Dot | LastType::Dotdot => {
                self.handle_dots(self.last_type);
            }
            LastType::Norm => {
                let name = self
                    .last
                    .as_ref()
                    .map(Qstr::as_str)
                    .ok_or(VfsError::InvalidInput)?
                    .to_owned();
                self.walk_component(&name, WalkComponent::Final, cred)?;
            }
        }
        self.complete_path_lookup(self.path.clone())
    }

fn cancel_waiter(&self, wake: &mut WakeQueue) {
        let discarded = {
            let mut blocked = BLOCKED_OWNERS.lock();
            let parent = self
                .0
                .state(&mut blocked)
                .blocker
                .take()
                .and_then(|weak| weak.upgrade());
            let discarded = if let Some(parent) = parent {
                // SAFETY: the blocker relation records membership in this
                // exact list, and the global guard serializes all list edits.
                let removed = unsafe {
                    parent
                        .state(&mut blocked)
                        .requests
                        .cursor_mut_from_ptr(Arc::as_ptr(&self.0))
                        .remove()
                };
                if removed.is_some() {
                    parent.note_pop();
                }
                self.0.state(&mut blocked).wait.take()
            } else {
                // A detached request may already belong to a notification
                // list. Leave its registration for that list's consumer.
                None
            };
            remove_blocked_owner(&mut blocked, &self.0);
            self.0.wake_blocked(&mut blocked, wake);
            discarded
        };
        drop(discarded);
    }

