fn pipe_readiness_and_eof_precede_interrupt_but_empty_wait_is_marked() {
    let pipe = PipeObject::new_anonymous();
    let task = ktask::current();
    let mut output = [0; 4];
    task.interrupt();
    let waiting = pipe.read(false, &mut output);
    task.clear_interrupt();
    assert_eq!(waiting, Err(KError::IoWaitInterrupted));
    assert_eq!(pipe.write(true, true, b"data"), Ok(4));
    task.interrupt();
    let ready = pipe.read(false, &mut output);
    let preserved = task.is_interrupted();
    task.clear_interrupt();
    assert_eq!(ready, Ok(4));
    assert_eq!(&output, b"data");
    assert!(preserved);
    pipe.state.lock().writers = 0;
    task.interrupt();
    let eof = pipe.read(false, &mut output);
    task.clear_interrupt();
    assert_eq!(eof, Ok(0));
}

fn update_time(
        &self,
        dentry: &Dentry,
        timestamp: SystemTime,
        update: InodeUpdateTime,
    ) -> VfsResult<()> {
        let applied = self
            .inode_operations
            .update_time(&MountIdmap, dentry, timestamp, update)?;
        if let Some(atime) = applied.atime {
            self.set_accessed_at(atime);
        }
        if let Some(mtime) = applied.mtime {
            self.set_modified_at(mtime);
        }
        if let Some(ctime) = applied.ctime {
            self.set_changed_at(ctime);
        }
        Ok(())
    }

fn touch_atime(&self) {
        if self.is_effectively_readonly() {
            return;
        }

        let mount_flags = self.mnt.flags();
        let super_block_flags = self.super_block().flags();
        if mount_flags.contains(MountFlags::NOATIME)
            || super_block_flags.contains(SuperBlockFlags::NOATIME)
            || (self.inode().node_type() == NodeType::Directory
                && (mount_flags.contains(MountFlags::NODIRATIME)
                    || super_block_flags.contains(SuperBlockFlags::NODIRATIME)))
        {
            return;
        }

        let inode = self.inode();
        let now = inode.current_time();
        let times = inode.times();
        if mount_flags.contains(MountFlags::RELATIME)
            && times.modified_at < times.accessed_at
            && times.changed_at < times.accessed_at
            && now
                .duration_since(times.accessed_at)
                .unwrap_or(TimeSpan::ZERO)
                < TimeSpan::from_secs(24 * 60 * 60)
        {
            return;
        }
        if times.accessed_at == now {
            return;
        }

        // Linux treats atime persistence as best effort so a read that already
        // completed is never converted into an update-time failure.
        let _ = inode.update_time(self.dentry(), now, InodeUpdateTime::Access);
    }

fn fallocate(&self, flags: FallocateFlags, offset: u64, len: u64) -> VfsResult<()> {
        let inode = self.inode();
        let operations = self.operations();
        if !operations.supported_fallocate_modes().contains(flags) {
            return Err(VfsError::from(LinuxError::EOPNOTSUPP));
        }
        let _data_guard = inode.lock_data();
        let _invalidate_guard = self.mapping().lock_invalidate_exclusive();
        operations.fallocate(self, flags, offset, len)
    }

