fn update_attributes_after_backing_change(&self, metadata: &Metadata) -> VfsResult<()> {
        let expected_block_size = 1_u64 << self.attributes.block_bits();
        if metadata.inode != self.inode()
            || metadata.mode.node_type() != self.node_type()
            || metadata.block_size != expected_block_size
            || metadata.rdev != self.attributes.rdev()
        {
            return Err(VfsError::InvalidInput);
        }

        self.attributes.set_permission(metadata.mode.permission());
        self.attributes.set_owner(metadata.uid, metadata.gid);
        self.attributes.set_link_count(metadata.nlink);
        self.attributes.set_accessed_at(metadata.atime);
        self.attributes.set_modified_at(metadata.mtime);
        self.attributes.set_changed_at(metadata.ctime);
        self.attributes
            .set_allocated_bytes(metadata.blocks.saturating_mul(INODE_BYTES_PER_BLOCK));
        Ok(())
    }

fn read_folio(&self, mapping: &AddressSpace, mut folio: FolioRead) -> VfsResult<()> {
        // Initialize the isolated miss or retry the consumed, incomplete EOF page.
        assert!(mapping.invalidate_lock.try_write().is_none());
        let byte = match folio.index() {
            0 => 0x11,
            3 => 0x33,
            _ => panic!("completed readahead pages must not be read again"),
        };
        folio.data().fill(byte);
        let len = mapping
            .visible_len()?
            .saturating_sub(folio.index() * PAGE_SIZE_4K as u64)
            .min(PAGE_SIZE_4K as u64) as usize;
        folio.data()[len..].fill(0);
        folio.complete(Ok(()))
    }

fn cdev_del(first: DeviceId, count: u32) -> Option<Arc<dyn DeviceFileOps>> {
    let (entry, subscribers) = {
        let mut registry = CHRDEV_MAP.lock();
        let entry = registry.del(first, count)?;
        let subscribers = if entry.identity.is_some() {
            registry.subscribers.clone()
        } else {
            Vec::new()
        };
        (entry, subscribers)
    };
    // Projection callbacks may acquire filesystem locks; never run them under
    // the registry lock. The retired identity is already unavailable.
    for subscriber in subscribers {
        subscriber();
    }
    Some(entry.ops.clone())
}

fn seek_to(&mut self, offset: u64) -> VfsResult<()> {
        while self.last_file_offset < offset {
            if self.buf.len().saturating_sub(self.buf_read_pos) == 0 && !self.fill_next_entry()? {
                break;
            }

            let available = self.buf.len().saturating_sub(self.buf_read_pos);
            let to_skip = min((offset - self.last_file_offset) as usize, available);
            self.buf_read_pos += to_skip;
            self.last_file_offset += to_skip as u64;
        }
        Ok(())
    }

