fn write(&self, _file: &VfsFile, buf: &[u8], offset: u64) -> VfsResult<usize> {
        let mut data = self.data.lock();
        let start = offset as usize;
        if start + buf.len() > data.len() {
            data.resize(start + buf.len(), 0);
        }
        data[start..start + buf.len()].copy_from_slice(buf);
        Ok(buf.len())
    }

fn write_extent(
        &mut self,
        index: u32,
        logical: u64,
        physical: u64,
        length: u64,
        flags: FiemapExtentFlags,
    ) -> VfsResult<()> {
        assert_eq!(usize::try_from(index).ok(), Some(self.extents.len()));
        self.extents.push((logical, physical, length, flags));
        Ok(())
    }

fn link_at_entry(
        &self,
        root: &Path,
        base: &Path,
        source: &Path,
        cred: &Cred,
    ) -> VfsResult<CreatedEntry> {
        let (parent, last, has_trailing_slash) = self
            .parent_at(root, base, LookupIntent::Open, cred)?
            .into_create()?;
        let name = last.as_str();

        let path = parent
            .dentry()
            .as_dir()?
            .create_exclusive_with(name, |candidate| {
                if has_trailing_slash {
                    return Err(VfsError::NotFound);
                }
                parent.vfs_link(candidate, source, cred)
            })
            .map(|entry| parent.with_dentry(entry))?;
        Ok(CreatedEntry {
            path,
            name: String::from(name),
            parent: parent.inode(),
        })
    }

