fn register_pipe_poll(
    file: &VfsFile,
    context: &mut PollContext<'_>,
    _events: IoEvents,
) -> Result<(), PollRegisterError> {
    if let Ok(pipe) = PipeObject::from_file(file) {
        let mode = file.mode();
        if mode.contains(FMode::READ) {
            context.register(&pipe.rd_wait)?;
        }
        if mode.contains(FMode::WRITE) {
            context.register(&pipe.wr_wait)?;
        }
    }
    Ok(())
}

fn lookup_cache_entry(&self, name: &str) -> Option<Dentry> {
        let mut children = self.0.children.lock();
        let entry = children
            .get(name)
            .and_then(|entry| entry.upgrade().map(Dentry));
        if entry.is_none() {
            children.remove(name);
        }
        entry.filter(|entry| !entry.is_parallel_lookup())
    }

fn check_resolved_open(
        path: &Path,
        flags: &OpenParams,
        lookup_flags: LookupFlags,
        was_created: bool,
    ) -> VfsResult<()> {
        if flags.will_create() {
            if flags.is_exclusive_create() && !was_created {
                return Err(VfsError::AlreadyExists);
            }
            if d_is_dir(path.dentry()) {
                return Err(VfsError::IsADirectory);
            }
        }
        // The trailing-slash demand rides the lookup flags across symlink
        // expansion (see [`Self::open_path`]) and is consumed here exactly as
        // [`Self::complete_path_lookup`] consumes it for plain lookups.
        if lookup_flags.contains(LookupFlags::DIRECTORY) && !path.dentry().can_lookup() {
            return Err(VfsError::NotADirectory);
        }
        Ok(())
    }

fn instantiate_or_alias(&self, inode: Arc<VfsInode>) -> VfsResult<Option<Dentry>> {
        if inode.is_dir()
            && let Some(alias) = inode.directory_alias()
        {
            return Ok(Some(alias));
        }
        self.dentry.instantiate(inode)?;
        Ok(None)
    }

fn resolve_pair_positions<'a>(
    input: &'a Arc<VfsFile>,
    input_position: TransferPosition<'a>,
    output: &'a Arc<VfsFile>,
    output_position: TransferPosition<'a>,
    input_scratch: &'a mut u64,
    output_scratch: &'a mut u64,
) -> PairPositions<'a> {
    let input_at = match input_position {
        TransferPosition::Managed => None,
        TransferPosition::At(offset) => Some(offset),
    };
    let output_at = match output_position {
        TransferPosition::Managed => None,
        TransferPosition::At(offset) => Some(offset),
    };
    // A `Managed` side needs a lock exactly when its file is seekable.
    let input_lockable = input_at.is_none() && !input.is_stream();
    let output_lockable = output_at.is_none() && !output.is_stream();

    let same_description = Arc::ptr_eq(input, output);
    let (mut first_guard, mut second_guard) = if same_description {
        // One open file description: at most one lock, recorded where either
        // side can claim it. Two `Managed` sides are one logical position.
        let lockable = input_lockable || output_lockable;
        (lockable.then(|| input.position_lock()), None)
    } else {
        // Distinct descriptions lock in address order.
        let input_first = Arc::as_ptr(input) <= Arc::as_ptr(output);
        let (first, second) = if input_first {
            (input, output)
        } else {
            (output, input)
        };
        let (first_lockable, second_lockable) = if input_first {
            (input_lockable, output_lockable)
        } else {
            (output_lockable, input_lockable)
        };
        let first_guard = first_lockable.then(|| first.position_lock());
        let second_guard = second_lockable.then(|| second.position_lock());
        (first_guard, second_guard)
    };

    // Both sides `Managed` on one description: a single logical position
    // served by the single lock.
    if same_description && input_lockable && output_lockable {
        let guard = first_guard
            .take()
            .expect("shared description took one lock");
        return PairPositions::Shared(PositionSlot::Managed(guard));
    }

    // Which stored guard each side claims. One description: the single lock
    // sits in `first_guard` and either lockable side claims it. Distinct
    // files: the address-order placement, disjoint between the sides.
    let input_first = Arc::as_ptr(input) <= Arc::as_ptr(output);
    let input_claims_first = same_description || input_first;
    let output_claims_first = same_description || !input_first;
    let mut claim = |first: bool| -> MutexGuard<'a, u64> {
        let stored = if first {
            &mut first_guard
        } else {
            &mut second_guard
        };
        stored.take().expect("a lockable side owns its lock")
    };
    let input_slot = match (input_at, input_lockable) {
        (Some(offset), _) => PositionSlot::At(offset),
        (None, true) => PositionSlot::Managed(claim(input_claims_first)),
        (None, false) => PositionSlot::At(input_scratch),
    };
    let output_slot = match (output_at, output_lockable) {
        (Some(offset), _) => PositionSlot::At(offset),
        (None, true) => PositionSlot::Managed(claim(output_claims_first)),
        (None, false) => PositionSlot::At(output_scratch),
    };
    PairPositions::Distinct {
        input: input_slot,
        output: output_slot,
    }
}

fn create(&self, name: &str, permission: NodePermission, cred: &Cred) -> VfsResult<Self> {
        let mode = Umode::new(NodeType::RegularFile, permission);
        self.dentry
            .as_dir()?
            .create_exclusive_with(name, |candidate| {
                self.vfs_create(candidate, mode, NodePermission::empty(), true, cred)
            })
            .map(|entry| self.with_dentry(entry))
    }

fn read_iter(&self, iocb: &mut Kiocb<'_>, iter: &mut IovIterDest<'_>) -> VfsResult<usize> {
        let read = pipe_read_iter(iocb, iter)?;
        if read > 0 {
            iocb.file().file_accessed();
        }
        Ok(read)
    }

fn normalize(&self) -> Option<PathBuf> {
        let mut ret = PathBuf::new();
        let mut rest = self.inner;
        let mut at_start = true;
        while !rest.is_empty() {
            let (component, next) = match rest.find('/') {
                Some(index) => (&rest[..index], &rest[index + 1..]),
                None => (rest, ""),
            };
            rest = next;
            match component {
                "" if at_start => {
                    ret.push("/");
                }
                "" => {}
                "." => {}
                ".." => {
                    if !ret.pop() {
                        return None;
                    }
                }
                name => {
                    ret.push(name);
                }
            }
            at_start = false;
        }
        Some(ret)
    }

fn test_sticky_directory_rejects_unrelated_user_delete() {
    let fs = mock_filesystem(StatFsFlags::empty());
    let mount = Mount::new_root(&fs);
    let root = mount.root_path();
    root.dentry
        .update_metadata(MetadataUpdate {
            mode: Some(NodePermission::from_bits_truncate(0o1777)),
            owner: Some((1000, 1000)),
            ..Default::default()
        })
        .unwrap();
    let victim = lookup_child_in_mount(&root, "mnt").unwrap();
    victim
        .dentry
        .update_metadata(MetadataUpdate {
            owner: Some((2000, 2000)),
            ..Default::default()
        })
        .unwrap();

    assert_eq!(
        root.rmdir("mnt", &kcred::Cred::new(3000, 3000)),
        Err(VfsError::OperationNotPermitted)
    );
    assert_eq!(
        root.check_sticky(&victim, &kcred::Cred::new(3000, 3000)),
        Err(VfsError::OperationNotPermitted)
    );
    // Linux exempts the victim owner, the directory owner, and `CAP_FOWNER`.
    assert_eq!(
        root.check_sticky(&victim, &kcred::Cred::new(2000, 2000)),
        Ok(())
    );
    assert_eq!(
        root.check_sticky(&victim, &kcred::Cred::new(1000, 1000)),
        Ok(())
    );
    assert_eq!(root.check_sticky(&victim, &kcred::Cred::new(0, 0)), Ok(()));
}

