fn splice_read(
        &self,
        nonblocking: bool,
        scratch: &mut [u8],
        mut write_fn: impl FnMut(&[u8]) -> KResult<usize>,
    ) -> KResult<usize> {
        if scratch.is_empty() {
            return Ok(0);
        }
        let result = block_on(poll_file_io(self, IoEvents::IN, nonblocking, || {
            let mut state = self.state.lock();
            let count = scratch.len().min(state.buffer.len());
            if count == 0 {
                return if state.writers == 0 {
                    Ok(Ok(0))
                } else {
                    Err(KError::WouldBlock)
                };
            }
            state.copy_prefix(&mut scratch[..count]);
            let result = write_fn(&scratch[..count]);
            if let Ok(written) = result {
                if written > count {
                    return Ok(Err(KError::Io));
                }
                drop(state.buffer.drain(..written));
            }
            Ok(result)
        }))?;
        if matches!(result, Ok(count) if count > 0) {
            ktask::with_wake_sync(|| self.wr_wait.wake());
        }
        result
    }

fn new_inner(inode: Arc<VfsInode>, parent: Option<Dentry>, name: String) -> Self {
        let flags = DentryFlags::for_inode(&inode);
        let dentry = Self(Arc::new(DentryInner::new(
            flags,
            Some(inode.clone()),
            parent,
            name,
        )));
        if !inode.add_dentry_alias(&dentry) {
            let alias = inode
                .directory_alias()
                .expect("directory alias disappeared while constructing dentry");
            let requested_location = dentry.0.location.read();
            let location = alias.0.location.read();
            let has_same_parent = match (&location.parent, &requested_location.parent) {
                (Some(existing), Some(requested)) => existing.ptr_eq(requested),
                (None, None) => true,
                _ => false,
            };
            assert!(
                has_same_parent && location.name == requested_location.name,
                "directory inode already has a live dentry alias"
            );
            drop(location);
            drop(requested_location);
            return alias;
        }
        if let Some(super_block) = dentry.super_block() {
            inode.bind_super_block(&super_block);
        }
        dentry
    }

fn single_folio_failure_preserves_control_progress_for_retry() {
    let input = vec![0x6d; PAGE_SIZE_4K * 3];
    let inode = VfsInode::new_file_with_address_space_and_flags(
        Arc::new(TruncateOps),
        NodeFlags::ALWAYS_CACHE,
        &super::TRUNCATE_OPERATIONS,
        VfsInodeInit::new(
            4,
            input.len() as u64,
            Umode::new(NodeType::RegularFile, NodePermission::default()),
        ),
    );
    let mapping = inode.address_space();
    mapping.write_cached_bytes(0, &input).unwrap();
    let mut control = WritebackControl::all(false).with_nr_to_write(3);
    let _invalidate_guard = mapping.invalidate_lock.read();
    let result = mapping.writeback_cached_folios(&mut control, |index, _, _| {
        if index == 1 {
            Err(VfsError::InvalidInput)
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Err(VfsError::InvalidInput));
    assert_eq!(control.nr_to_write(), 2);
    assert_eq!(control.pages_skipped(), 0);
    let mut retried = Vec::new();
    mapping
        .writeback_cached_folios(&mut control, |index, _, _| {
            retried.push(index);
            Ok(())
        })
        .unwrap();
    assert_eq!(retried, vec![1, 2]);
    assert_eq!(control.nr_to_write(), 0);
    for index in 0..3 {
        mapping
            .i_pages
            .with_folio(index, |folio| {
                let folio = folio.unwrap();
                assert!(!folio.is_dirty());
                assert!(!folio.is_under_writeback());
            })
            .unwrap();
    }
}

