fn check_sticky(&self, victim: &Self, cred: &Cred) -> VfsResult<()> {
        let dir = self.metadata();
        if !dir.mode.permission().contains(NodePermission::STICKY) {
            return Ok(());
        }

        // Linux `__check_sticky()` exempts the victim owner, the directory
        // owner, and `CAP_FOWNER`.
        if cred.has_cap(kcred::CAP_FOWNER)
            || cred.fsuid() == dir.uid
            || cred.fsuid() == victim.metadata().uid
        {
            Ok(())
        } else {
            Err(VfsError::OperationNotPermitted)
        }
    }

fn read_iter_from(&self, iter: &mut IovIterDest<'_>, pos: &mut u64) -> VfsResult<usize> {
        if self.is_stream() {
            self.verify_read_area(0, iter.count())?;
            let mut iocb = Kiocb::new(self, 0);
            self.operations().read_iter(&mut iocb, iter)
        } else {
            self.verify_read_area(*pos, iter.count())?;
            let mut iocb = Kiocb::new(self, *pos);
            let read = self.operations().read_iter(&mut iocb, iter)?;
            *pos = iocb.ki_pos();
            Ok(read)
        }
    }

fn pump_pipe_to_file(
    pipe: &PipeObject,
    input: &Arc<VfsFile>,
    output: &Arc<VfsFile>,
    output_position: TransferPosition<'_>,
    len: usize,
    nonblocking: bool,
) -> KResult<usize> {
    let output_offset = match output_position {
        TransferPosition::Managed => None,
        TransferPosition::At(offset) => Some(offset),
    };
    let mut output_pos = output_offset.as_deref().copied().unwrap_or(0);
    let output_managed = output_offset.is_none();
    let result = pump(len, |buf, chunk, total| {
        let wait = nonblocking || input.is_nonblocking() || total > 0;
        let confirmed = pipe.splice_read(wait, &mut buf[..chunk], |staged| {
            if output_managed && !output.is_stream() {
                output.write_from(staged, &mut output.position_lock())
            } else {
                output.write_from(staged, &mut output_pos)
            }
        })?;
        Ok(Step::Data {
            confirmed,
            stop: confirmed < chunk,
        })
    });
    if let Some(offset) = output_offset {
        *offset = output_pos;
    }
    result
}

fn new_len(name: &str, len: usize) -> Self {
        debug_assert!(len <= name.len());
        let mut hash = 0xcbf29ce484222325u64;
        for byte in &name.as_bytes()[..len] {
            hash ^= u64::from(*byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
        Self {
            name: String::from(name),
            len,
            hash,
        }
    }

fn from_parts_with_attributes(parts: InodeParts, attributes: InodeAttributes) -> Arc<Self> {
        let InodeParts {
            private_data,
            inode_operations,
            file_operations,
            flags: _,
            address_space_operations,
            init,
        } = parts;
        let residency = inode_operations.cache_residency();
        Arc::new_cyclic(move |this| Self {
            identity: InodeIdentity::new(init.number),
            attributes,
