fn read_block(&self, block_id: u64, buf: &mut [u8]) -> block::DriverResult {
        self.reads
            .fetch_add(1, core::sync::atomic::Ordering::Relaxed);
        if self.fail_io.load(core::sync::atomic::Ordering::Relaxed) {
            return Err(DriverError::Io);
        }
        let start = block_id as usize * self.block_size;
        let end = start + buf.len();
        buf.copy_from_slice(&self.storage.lock()[start..end]);
        Ok(())
    }

fn test_chown_without_new_ids_is_a_noop_when_mode_does_not_change() {
    let fs = mock_regular_file_filesystem(NodePermission::from_bits_truncate(0o666));
    let root = Mount::new_root(&fs).root_path();

    // Linux turns chown's set-ID cleanup into ATTR_MODE only when a bit must
    // actually be cleared. An unrelated caller may therefore chown(-1, -1) on
    // a file without set-ID bits.
    root.chown(None, None, &Cred::new(2000, 200)).unwrap();

    let metadata = root.metadata();
    assert_eq!((metadata.uid, metadata.gid), (1000, 100));
    assert_eq!(metadata.mode.permission().bits(), 0o666);
}

fn execute_locked<F>(
        &self,
        old_dir_inode: &Arc<VfsInode>,
        new_dir_inode: &Arc<VfsInode>,
        source: &Dentry,
        target: &Dentry,
        may_rename_fn: F,
    ) -> VfsResult<()>
    where
        F: FnOnce(&Dentry, &Dentry) -> VfsResult<()>,
    {
        self.validate_locked(source, target)?;
        let source_key = source.key();
        let target_key = target.key();
        let destination_name =
            (!self.flags.contains(RenameFlags::EXCHANGE)).then(|| target.name_snapshot());
        may_rename_fn(source, target)?;
        old_dir_inode.rename(source, new_dir_inode, target, self.flags)?;
        if self.flags.contains(RenameFlags::EXCHANGE) {
            self.old_parent.d_exchange(
                self.old_name,
                source,
                self.new_parent,
                self.new_name,
                target,
                (&source_key, &target_key),
            );
        } else {
            self.old_parent.d_move(
                source,
                self.new_parent,
                target,
                destination_name.expect("non-exchange rename has a destination name"),
                (&source_key, &target_key),
            );
        }
        Ok(())
    }

fn update_time(
        &self,
        idmap: &MountIdmap,
        dentry: &Dentry,
        timestamp: SystemTime,
        update: InodeUpdateTime,
    ) -> VfsResult<MetadataUpdate> {
        let (atime, mtime, ctime) = match update {
            InodeUpdateTime::Access => (Some(timestamp), None, None),
            InodeUpdateTime::ChangeAndModification => (None, Some(timestamp), Some(timestamp)),
        };
        self.setattr(
            idmap,
            dentry,
            MetadataUpdate {
                atime,
                mtime,
                ctime,
                ..Default::default()
            },
        )
    }

fn character_operations(inode: &VfsInode) -> Option<Arc<dyn DeviceFileOps>> {
    if let Some(entry) = inode.character_device()
        && let Some(ops) = entry.live_operations()
    {
        return Some(ops);
    }
    // Selection linearizes under the registry lock. Removal does not revoke an
    // already selected backend; drivers enforce their own open-admission rules.
    let entry = CHRDEV_MAP.lock().get(inode.rdev())?;
    inode.set_character_device(Arc::downgrade(&entry));
    Some(entry.ops.clone())
}

