fn pump_file_to_pipe(
    pipe: &PipeObject,
    output: &Arc<VfsFile>,
    input: &Arc<VfsFile>,
    input_position: TransferPosition<'_>,
    len: usize,
    nonblocking: bool,
) -> KResult<usize> {
    let input_offset = match input_position {
        TransferPosition::Managed => None,
        TransferPosition::At(offset) => Some(offset),
    };
    let mut input_pos = input_offset.as_deref().copied().unwrap_or(0);
    let input_managed = input_offset.is_none();
    let result = pump(len, |buf, chunk, total| {
        let wait = nonblocking || output.is_nonblocking() || total > 0;
        let confirmed = pipe.splice_write(wait, &mut buf[..chunk], |staged| {
            if input_managed && !input.is_stream() {
                input.read_from(staged, &mut input.position_lock())
            } else {
                input.read_from(staged, &mut input_pos)
            }
        })?;
        // Do not start a second blocking source read after publishing
        // stream data into the pipe; return that completed prefix.
        Ok(Step::Data {
            confirmed,
            stop: confirmed < chunk || input.is_stream(),
        })
    });
    if let Some(offset) = input_offset {
        *offset = input_pos;
    }
    result
}

fn page_mkwrite<R>(
        &self,
        index: PageIndex,
        prepare: impl FnOnce(u64, usize) -> VfsResult<()>,
        f: impl FnOnce(&mut FolioGuard<'_>) -> VfsResult<R>,
    ) -> VfsResult<R> {
        let inode = self.inode().ok_or(VfsError::InvalidInput)?;
        let pos = index
            .checked_mul(PAGE_SIZE_4K as u64)
            .ok_or(VfsError::InvalidInput)?;
        let _invalidate_guard = self.invalidate_lock.read();
        self.with_folio_or_create(index, |folio| {
            let file_len = inode.size();
            if pos >= file_len {
                return Err(VfsError::BadAddress);
            }
            let len = usize::try_from((file_len - pos).min(PAGE_SIZE_4K as u64))
                .map_err(|_| VfsError::InvalidInput)?;
            prepare(pos, len)?;
            self.dirty_folio(folio)?;
            f(folio)
        })
    }

fn failed_block_file_open_leaves_no_holder_or_release_callback() {
    use core::sync::atomic::Ordering::Relaxed;
    let backend = OpenBlockDevice::new(8);
    let disk = block::Gendisk::alloc(
        String::from("open-fail"),
        242,
        0,
        1,
        Box::new(backend.clone()),
    )
    .unwrap();
    let device = block::add_disk(disk).unwrap();
    let flags = crate::OpenFlags::EXCLUSIVE;
    backend.fail_open.store(true, Relaxed);
    assert!(matches!(
        open_block_device_file_with(device.device_number(), flags),
        Err(VfsError::Io)
    ));
    assert_eq!(backend.releases.load(Relaxed), 0);
    backend.fail_open.store(false, Relaxed);
    let (file, _) = open_block_device_file_with(device.device_number(), flags).unwrap();
    drop(file);
    assert_eq!(backend.releases.load(Relaxed), 1);
    block::del_gendisk(device.device_number()).unwrap();
}

fn write_block(&self, block_id: u64, buf: &[u8]) -> block::DriverResult {
        self.writes
            .fetch_add(1, core::sync::atomic::Ordering::Relaxed);
        if self.fail_io.load(core::sync::atomic::Ordering::Relaxed) {
            return Err(DriverError::Io);
        }
        let start = block_id as usize * self.block_size;
        let prefix = self
            .fail_after_write_bytes
            .load(core::sync::atomic::Ordering::Relaxed);
        if prefix != usize::MAX {
            let written = prefix.min(buf.len());
            self.storage.lock()[start..start + written].copy_from_slice(&buf[..written]);
            return Err(DriverError::Io);
        }
        let end = start + buf.len();
        self.storage.lock()[start..end].copy_from_slice(buf);
        Ok(())
    }

fn mock_reconfigure(context: &mut FsContext<'_>) -> VfsResult<()> {
    let super_block = context.super_block()?;
    if context.private::<FsContextPurpose>()? != &FsContextPurpose::Reconfigure
        || context.super_private::<SuperBlockFlags>()? != &context.sb_flags()
    {
        return Err(VfsError::InvalidInput);
    }
    if super_block
        .private::<MockSuperPrivate>()?
        .mount_flags
        .contains(StatFsFlags::RDONLY)
        && !context.sb_flags().contains(SuperBlockFlags::RDONLY)
    {
        return Err(VfsError::ReadOnlyFilesystem);
    }
    Ok(())
}

fn splice_between_pipes_retains_untransferred_suffix() {
    let source = PipeObject::new_anonymous();
    let destination = PipeObject::new_anonymous();
    destination.resize(PIPE_BUF).unwrap();
    let data = [vec![1; PIPE_BUF], vec![2; PIPE_BUF]].concat();
    source.write(true, false, &data).unwrap();
    assert_eq!(
        source.splice_to(&destination, data.len(), true),
        Ok(PIPE_BUF)
    );
    assert_eq!(
        source.splice_to(&destination, data.len(), true),
        Err(KError::WouldBlock)
    );
    let mut bytes = vec![0; PIPE_BUF];
    assert_eq!(source.read(true, &mut bytes), Ok(PIPE_BUF));
    assert!(bytes.iter().all(|byte| *byte == 2));
    assert_eq!(destination.read(true, &mut bytes), Ok(PIPE_BUF));
    assert!(bytes.iter().all(|byte| *byte == 1));
    assert_eq!(
        source.splice_to(&source, 1, true),
        Err(KError::InvalidInput)
    );
}

