        &root,
        linux_raw_sys::general::O_CREAT | linux_raw_sys::general::O_RDONLY,
        NodePermission::empty(),
        NodePermission::empty(),
        kcred::initial_cred(),
    );
    assert_eq!(existing.map(|_| ()), Ok(()));

    let tree = test_tree();
    let mount = Mount::new_root_with_flags(&tree.fs, crate::MountFlags::RDONLY);
    let root = mount.root_path();
    let exclusive = Filename::new("/target").open_with_flags_at(
        &root,
        &root,
        linux_raw_sys::general::O_CREAT
            | linux_raw_sys::general::O_EXCL
            | linux_raw_sys::general::O_RDONLY,
        NodePermission::empty(),
        NodePermission::empty(),
        kcred::initial_cred(),
    );
    assert!(matches!(exclusive, Err(VfsError::AlreadyExists)));
}

fn readahead_after_copy(
        &self,
        folio: &mut FolioGuard<'_>,
        offset: u64,
        count: usize,
        ra: &Mutex<FileRaState>,
    ) -> Option<(core::ops::Range<PageIndex>, Option<PageIndex>)> {
        if !folio.is_readahead() {
            return None;
        }
        // The caller holds the folio lock. Serialize eligibility, consumption
        // and window selection with EIO retreat; no policy holder waits for a
        // folio or performs I/O.
        let mut policy = ra.lock();
        if !policy.is_enabled() || !folio.take_readahead() {
            return None;
        }
        let index = folio.index();
        let request_pages = (offset
            .saturating_add(count as u64)
            .div_ceil(PAGE_SIZE_4K as u64)
            - index)
            .max(1);
        policy.on_marker(index, request_pages, |limit| {
            self.i_pages
                .next_miss_range(index + 1..index + 1 + limit)
                .map(|run| run.start)
        })
    }

fn release_unless_last(&mut self) -> bool {
        #[expect(
            clippy::panic,
            reason = "CG-021-no-panic-on-reachable-failure: Each release pairs with a successful \
                      try_acquire_mount, which succeeds only in Available and keeps the state \
                      there until the last release"
        )]
        let Self::Available { active_mounts } = self else {
            panic!("every active mount release must match an acquisition");
        };
        match *active_mounts {
            #[expect(
                clippy::panic,
                reason = "CG-021-no-panic-on-reachable-failure: Each release pairs with a \
                          successful try_acquire_mount, so an Available state being released \
                          holds at least one active mount"
            )]
            0 => panic!("every active mount release must match an acquisition"),
            1 => true,
            _ => {
                *active_mounts -= 1;
                false
            }
        }
    }

