fn check_dac_permission(metadata: &Metadata, permission: Permission, cred: &Cred) -> KResult<()> {
    let permission = permission
        .intersection(Permission::MAY_READ | Permission::MAY_WRITE | Permission::MAY_EXEC);
    let mode = metadata.mode.permission();
    if permission.is_empty() || has_all_requested_bits(mode, permission) {
        return Ok(());
    }

    // A regular file without any execute bit remains non-executable even for
    // `CAP_DAC_OVERRIDE`/`CAP_DAC_READ_SEARCH`; Linux rejects that case before
    // considering either capability.
    if permission.contains(Permission::MAY_EXEC)
        && metadata.mode.node_type() != NodeType::Directory
        && !has_any_exec_bit(metadata)
    {
        return Err(KError::PermissionDenied);
    }

    if cred.has_cap(CAP_DAC_OVERRIDE) {
        return Ok(());
    }

    if cred.has_cap(CAP_DAC_READ_SEARCH) {
        let readable = Permission::MAY_READ
            | if metadata.mode.node_type() == NodeType::Directory {
                Permission::MAY_EXEC
            } else {
                Permission::empty()
            };
        if permission.difference(readable).is_empty() {
            return Ok(());
        }
    }

    let is_allowed = if cred.fsuid() == metadata.uid {
        owner_allows(mode, permission)
    } else if cred.in_group(metadata.gid) {
        group_allows(mode, permission)
    } else {
        other_allows(mode, permission)
    };

    if !is_allowed {
        return Err(KError::PermissionDenied);
    }

    Ok(())
}

fn test_chown_setid_cleanup_matches_linux() {
    let regular = |mode| {
        Umode::new(
            NodeType::RegularFile,
            NodePermission::from_bits_truncate(mode),
        )
    };
    let directory = |mode| {
        Umode::new(
            NodeType::Directory,
            NodePermission::from_bits_truncate(mode),
        )
    };
    let owner = Cred::new(1000, 100);

    // chown_common() excludes directories from set-ID cleanup entirely.
    assert_eq!(
        Path::chown_mode(directory(0o6666), 100, None, &owner).bits(),
        0o6666
    );

    // Set-UID is always cleared for non-directories. Without a GID argument,
    // set-GID depends only on the old GID, group-execute, and CAP_FSETID.
    assert_eq!(
        Path::chown_mode(regular(0o6666), 100, None, &owner).bits(),
        0o2666
    );
    assert_eq!(
        Path::chown_mode(regular(0o2666), 100, None, &owner).bits(),
        0o2666
    );
    // A pre-chown non-member group or group-execute clears set-GID.
    assert_eq!(
        Path::chown_mode(regular(0o2666), 200, None, &owner).bits(),
        0o666
    );
    assert_eq!(
        Path::chown_mode(regular(0o2670), 100, None, &owner).bits(),
        0o670
    );

    let mut fsetid = Cred::new(0, 0);
    fsetid.set_securebits(0x4).unwrap();
    fsetid.set_fsuid(1000);
    let set = kcred::CapSet::from_bits(1u64 << kcred::CAP_FSETID);
    fsetid
        .set_capabilities(kcred::CapSets::new(set, set, kcred::CapSet::EMPTY))
        .unwrap();
    assert_eq!(
        Path::chown_mode(regular(0o6666), 100, None, &fsetid).bits(),
        0o2666
    );
}

fn blocking_lock_wakeup_deadlock_and_signal_cleanup() {
    let first = Arc::new(FileLockContext::new());
    let second = Arc::new(FileLockContext::new());
    let owner_a = FileLockOwner::Posix(101);
    let owner_b = FileLockOwner::Posix(102);
    first
        .apply(
            &FileLock::new(owner_a, 101, FileLockType::Write, 0, 0).unwrap(),
            false,
        )
        .unwrap();
    second
        .apply(
            &FileLock::new(owner_b, 102, FileLockType::Write, 0, 0).unwrap(),
            false,
        )
        .unwrap();
    // A waiter registered on owner_b's lock makes the blocked owner visible
    // without any cross-task observation.
    let mut waiter = None;
    let mut wake = WakeQueue::new();
    assert_eq!(
        second.try_apply(
            &FileLock::new(owner_a, 101, FileLockType::Write, 0, 0).unwrap(),
            true,
            &mut waiter,
            &mut wake,
        ),
        Ok(true)
    );
    assert!(node::has_blocked_owner(owner_a));
    // Attach a waker so the unlock notification becomes observable, exactly
    // like a parked waiter would.
    assert!(waiter.as_ref().unwrap().poll_wait(Waker::noop()).is_pending());
    // The reverse request closes the cycle and must deadlock instead of
    // parking the caller.
    assert_eq!(
        first.apply(
            &FileLock::new(owner_b, 102, FileLockType::Write, 0, 0).unwrap(),
            true
        ),
        Err(LinuxError::EDEADLK.into())
    );
    // Unlocking hands the registration to the wake queue; the retry reuses
    // the same request node and now succeeds. try_apply is required here:
    // the apply() wrapper owns its internal wake queue, so the notification
    // would never reach ours.
    let mut unlock_waiter = None;
    assert_eq!(
        second.try_apply(
            &FileLock::unlock(owner_b),
            false,
            &mut unlock_waiter,
            &mut wake,
        ),
        Ok(false)
    );
    assert_eq!(wake.len(), 1);
    wake.wake();
    assert!(waiter.as_ref().unwrap().poll_wait(Waker::noop()).is_ready());
    assert_eq!(
        second.try_apply(
            &FileLock::new(owner_a, 101, FileLockType::Write, 0, 0).unwrap(),
            true,
            &mut waiter,
            &mut wake,
        ),
        Ok(false)
    );
    assert!(!node::has_blocked_owner(owner_a));
    // End-to-end signal path: the waiter parks on owner_a's installed lock
    // and the interrupt resolves it with ERESTARTSYS, cancelling its own
    // registration.
    let waiting = second.clone();
    let task = ktask::spawn(move || {
        assert_eq!(
            waiting.apply(
                &FileLock::new(owner_b, 102, FileLockType::Write, 0, 0).unwrap(),
                true
            ),
            Err(LinuxError::ERESTARTSYS.into())
        );
    });
    ktask::interrupt_task(&task, true);
    assert_eq!(task.join(), 0);
    assert!(!node::has_blocked_owner(owner_b));
    assert!(second.state.lock().posix.has_no_waiters());
}

fn complete_folio(&mut self, src: &[u8]) -> VfsResult<()> {
        let mut folio = self.next_folio().ok_or(VfsError::InvalidInput)?;
        if src.len() != PAGE_SIZE_4K {
            return Err(VfsError::InvalidInput);
        }
        folio.data().copy_from_slice(src);
        folio.complete(Ok(()))
    }

