fn map(&self, info: &mut FiemapExtentInfo<'_>, start: u64, length: u64) -> VfsResult<()> {
        match self.inode.node_type() {
            NodeType::RegularFile => {
                let _data_guard = self.inode.data_lock.read();
                self.operations.fiemap(self.inode, info, start, length)
            }
            NodeType::Directory => {
                let _namespace_guard = self.inode.lock_namespace_shared();
                self.operations.fiemap(self.inode, info, start, length)
            }
            _ => Err(VfsError::OperationNotSupported),
        }
    }

fn begin_eviction(&self, inode: &VfsInode) -> Option<InodeCacheKey> {
        let key = inode.identity.cache_key()?;
        let mut inodes = self.inodes.lock();
        let entry = inodes.get_mut(&key)?;
        let CachedInodeState::Live(cached) = &entry.state else {
            return None;
        };
        if !core::ptr::eq(cached.as_ptr(), inode) {
            return None;
        }
        let cached = cached.clone();
        entry.state = CachedInodeState::Freeing(cached);
        Some(key)
    }

fn read_folio(&self, mapping: &AddressSpace, mut folio: FolioRead) -> VfsResult<()> {
        assert!(mapping.invalidate_lock.try_write().is_none());
        assert_eq!(
            folio.index(),
            31,
            "only the aligned window has a one-page tail"
        );
        folio.data().fill(31);
        folio.complete(Ok(()))
    }

fn simple_rename(
    _idmap: &MountIdmap,
    old_dir: &VfsInode,
    old_dentry: &LockedDentry<'_>,
    new_dir: &VfsInode,
    new_dentry: &LockedDentry<'_>,
    flags: RenameFlags,
) -> VfsResult<()> {
    let old_dentry = old_dentry.as_dentry();
    let new_dentry = new_dentry.as_dentry();
    let they_are_dirs = old_dentry.is_dir();

    let supported_flags = RenameFlags::NOREPLACE | RenameFlags::EXCHANGE;
    if !supported_flags.contains(flags) || flags.has_conflicting_modes() {
        return Err(VfsError::InvalidInput);
    }
    if flags.contains(RenameFlags::EXCHANGE) {
        return simple_rename_exchange(old_dir, old_dentry, new_dir, new_dentry);
    }
    if flags.contains(RenameFlags::NOREPLACE) && d_really_is_positive(new_dentry) {
        return Err(VfsError::AlreadyExists);
    }

    if !simple_empty(new_dentry)? {
        return Err(VfsError::DirectoryNotEmpty);
    }

    if d_really_is_positive(new_dentry) {
        simple_unlink(new_dir, new_dentry)?;
        if they_are_dirs {
            new_dentry.decrement_link_count();
            old_dir.decrement_link_count();
        }
    } else if they_are_dirs {
        old_dir.decrement_link_count();
        new_dir.increment_link_count();
    }

    simple_rename_timestamp(old_dir, old_dentry, new_dir, new_dentry);
    Ok(())
}

fn get_tree_bdev<F>(
    context: &FsContext<'_>,
    lookup_root: &Path,
    lookup_pwd: &Path,
    fill_super: F,
) -> VfsResult<Arc<SuperBlock>>
where
    F: FnOnce(&Arc<SuperBlock>) -> VfsResult<()>,
{
    let source = context
        .source()
        .filter(|source| !source.is_empty())
        .ok_or(VfsError::InvalidInput)?;
    let path = Filename::new(source).lookup_at(
        lookup_root,
        lookup_pwd,
        LookupIntent::Open,
        LookupFlags::follow(),
        context.cred(),
    )?;
    if path.inode().node_type() != NodeType::BlockDevice {
        return Err(VfsError::from(kerrno::LinuxError::ENOTBLK));
    }
    if path.mount().flags().contains(MountFlags::NODEV) {
        return Err(VfsError::PermissionDenied);
    }

    let device_number = path.inode().rdev();
    if device_number == crate::DeviceId::default() {
        return Err(VfsError::from(kerrno::LinuxError::ENXIO));
    }
    let device = block::lookup_block_device(device_number)
        .ok_or_else(|| VfsError::from(kerrno::LinuxError::ENXIO))?;
    super_block_registry().get_or_try_init_bdev(
        context.fs_type(),
        device,
        context.sb_flags(),
        fill_super,
    )
}

