fn into_open_params(self) -> VfsResult<OpenParams> {
        let raw_flags = u32::try_from(self.flags).map_err(|_| VfsError::InvalidInput)?;
        let mut acc_mode = AccMode::from_access_mode(raw_flags & O_ACCMODE);

        let mut flags = OpenFlags::from_bits(raw_flags).ok_or(VfsError::InvalidInput)?;

        flags.remove(OpenFlags::CLOSE_ON_EXEC);

        let mode = if is_create_like_open(flags) {
            Umode::new(NodeType::RegularFile, self.mode)
        } else {
            if !self.mode.is_empty() {
                return Err(VfsError::InvalidInput);
            }
            Umode::new(NodeType::RegularFile, NodePermission::empty())
        };

        if flags.contains(OpenFlags::DIRECTORY | OpenFlags::CREATE) {
            return Err(VfsError::InvalidInput);
        }

        if flags.contains(OpenFlags::PATH) {
            if !O_PATH_FLAGS.contains(flags) {
                return Err(VfsError::InvalidInput);
            }
            acc_mode = AccMode::empty();
        }

        if flags.contains(OpenFlags::SYNC) {
            flags.insert(OpenFlags::DSYNC);
        }
        if flags.contains(OpenFlags::TRUNCATE) {
            acc_mode.insert_write();
        }
        if flags.contains(OpenFlags::APPEND) {
            acc_mode.insert_append();
        }

        let mut intent = if flags.contains(OpenFlags::PATH) {
            OpenIntent::empty()
        } else {
            OpenIntent::OPEN
        };
        if flags.contains(OpenFlags::CREATE) {
            intent |= OpenIntent::CREATE;
            if flags.contains(OpenFlags::EXCLUSIVE) {
                intent |= OpenIntent::EXCL;
                flags.insert(OpenFlags::NO_FOLLOW);
            }
        }

        let mut lookup_flags = LookupFlags::empty();
        if flags.contains(OpenFlags::DIRECTORY) {
            lookup_flags |= LookupFlags::DIRECTORY;
        }
        if !flags.contains(OpenFlags::NO_FOLLOW) {
            lookup_flags |= LookupFlags::FOLLOW_FINAL;
        }

        Ok(OpenParams {
            flags,
            mode,
            acc_mode,
            intent,
            lookup_flags,
        })
    }

fn fill_metadata(&self, inode_number: u64, block_size: u64) -> Metadata {
        let (uid, gid) = self.owner();
        let times = *self.times.lock();
        Metadata {
            device: 0,
            inode: inode_number,
            nlink: self.link_count(),
            mode: self.mode(),
            uid,
            gid,
            size: self.size(),
            block_size,
            blocks: self.blocks(),
            rdev: self.rdev(),
            atime: times.accessed_at.as_system_time(),
            mtime: times.modified_at.as_system_time(),
            ctime: times.changed_at.as_system_time(),
        }
    }

fn replace_lookup_candidate(&self, name: &str, candidate: &Dentry, entry: &Dentry) {
        let mut children = self.0.children.lock();
        if children
            .get(name)
            .is_some_and(|cached| Weak::ptr_eq(cached, &Arc::downgrade(&candidate.0)))
        {
            *children.get_mut(name).expect("checked cache entry") = Arc::downgrade(&entry.0);
        }
        if let Some(super_block) = candidate.super_block() {
            super_block.cache_dentry(entry.clone());
        }
        drop(children);
    }

fn readahead_for_fault(&self, file_offset: u64, file_end: Option<u64>) -> VfsResult<()> {
        let start_index = file_offset / PAGE_SIZE_4K as u64;
        if self
            .i_pages
            .next_miss_range(start_index..start_index.saturating_add(1))
            .is_none()
        {
            return Ok(());
        }

        let _invalidate_guard = self.invalidate_lock.read();
        let file_len = self.visible_len()?.min(file_end.unwrap_or(u64::MAX));
        if file_offset >= file_len {
            return Ok(());
        }
        let end_index = start_index
            .saturating_add(MAX_FAULT_READAHEAD_PAGES as u64)
            .min(file_len.div_ceil(PAGE_SIZE_4K as u64));
        self.prepare_readahead(start_index..end_index, None, file_len);
        Ok(())
    }

