fn mark_opened(&mut self) -> VfsResult<()> {
        self.mode.remove(FMode::CAN_READ | FMode::CAN_WRITE);
        let operations = self.operations.as_ref().ok_or(VfsError::InvalidInput)?;
        if self.mode.contains(FMode::READ) && operations.supports_read() {
            self.mode.insert(FMode::CAN_READ);
        }
        if self.mode.contains(FMode::WRITE) && operations.supports_write() {
            self.mode.insert(FMode::CAN_WRITE);
        }
        self.mode |= FMode::OPENED;
        Ok(())
    }

fn with_stat_data(
        mut self,
        block_size: u64,
        blocks: u64,
        atime: SystemTime,
        mtime: SystemTime,
        ctime: SystemTime,
    ) -> Self {
        self.accessed_at = InodeTimestamp::from_system_time(atime);
        self.modified_at = InodeTimestamp::from_system_time(mtime);
        self.changed_at = InodeTimestamp::from_system_time(ctime);
        self.block_bits = inode_blkbits(block_size);
        self.blocks = blocks;
        self
    }

fn lookup_locked(&self, dir_inode: &VfsInode, name: &str) -> VfsResult<Dentry> {
        loop {
            if let Some(entry) = self.lookup_cache_entry(name) {
                return Ok(entry);
            }

            let candidate = Dentry::new_negative(Some(self.clone()), name.to_owned());
            let lookup_guard = candidate.0.lookup_mutex.lock();
            candidate.begin_parallel_lookup();
            if let Some(entry) = self.cache_lookup_candidate(name, &candidate) {
                candidate.end_parallel_lookup();
                drop(lookup_guard);
                if entry.is_parallel_lookup() {
                    let _lookup_guard = entry.0.lookup_mutex.lock();
                }
                continue;
            }

            let result = match dir_inode.lookup_child(&candidate) {
                Ok(Some(entry)) => {
                    let location = entry.0.location.read();
                    let has_expected_parent = location
                        .parent
                        .as_ref()
                        .is_some_and(|parent| parent.ptr_eq(self));
                    let is_valid =
                        entry.is_really_positive() && has_expected_parent && location.name == name;
                    drop(location);
                    if is_valid {
                        if self.can_cache_children() && entry.can_cache_as_child() {
                            self.replace_lookup_candidate(name, &candidate, &entry);
                        } else {
                            // Non-cacheable entry (e.g. procfs): retract the
                            // transient candidate without ever publishing the
                            // entry into the children map or the dcache, so a
                            // lookup performs no cache-then-uncache churn.
                            self.uncache_lookup_candidate(name, &candidate);
                        }
                        Ok(entry)
                    } else {
                        self.uncache_lookup_candidate(name, &candidate);
                        Err(VfsError::InvalidInput)
                    }
                }
                Ok(None) => {
                    if !self.can_cache_children() {
                        // Non-cacheable parent (e.g. procfs): do not retain
                        // negative dentries either, or every failed name
                        // lookup would accumulate a permanent dcache entry
                        // and poison later lookups of the same name.
                        self.uncache_lookup_candidate(name, &candidate);
                    }
                    Ok(candidate.clone())
                }
                Err(err) => {
                    self.uncache_lookup_candidate(name, &candidate);
                    Err(err)
                }
            };
            candidate.end_parallel_lookup();
            drop(lookup_guard);
            return result;
        }
    }

fn test_mkdir_strips_requested_setid_bits_before_owner_initialization() {
    let fs = mock_filesystem(StatFsFlags::empty());
    let root = Mount::new_root(&fs).root_path();
    let requested = NodePermission::from_bits_truncate(0o7777);

    let ordinary = root
        .mkdir("ordinary", requested, &kcred::initial_cred())
        .unwrap();
    let ordinary_permission = ordinary.metadata().mode.permission();
    assert!(!ordinary_permission.contains(NodePermission::SET_UID));
    assert!(!ordinary_permission.contains(NodePermission::SET_GID));
    assert!(ordinary_permission.contains(NodePermission::STICKY));

    root.dentry
        .update_metadata(MetadataUpdate {
            mode: Some(NodePermission::from_bits_truncate(0o2777)),
            owner: Some((0, 1234)),
            ..Default::default()
        })
        .unwrap();
    let inherited = root
        .mkdir("inherited", requested, &kcred::initial_cred())
        .unwrap();
    let inherited_metadata = inherited.metadata();
    assert!(
        !inherited_metadata
            .mode
            .permission()
            .contains(NodePermission::SET_UID)
    );
    assert!(
        inherited_metadata
            .mode
            .permission()
            .contains(NodePermission::SET_GID)
    );
    assert_eq!(inherited_metadata.gid, 1234);
}

fn lookup(&self, name: &str) -> VfsResult<Dentry> {
        self.as_dir()?;
