fn try_lock(&self) -> Option<SpinLockGuard<'_, G, T>> {
        let guard_state = G::acquire();

        #[cfg(feature = "smp")]
        let is_unlocked = self
            .flag
            .compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed)
            .is_ok();

        #[cfg(not(feature = "smp"))]
        let is_unlocked = true;

        if is_unlocked {
            #[cfg(feature = "stats")]
            self.record_acquisitions();
            Some(SpinLockGuard {
                _token: &PhantomData,
                guard_state,
                // SAFETY: successful acquisition gives this guard exclusive
                // access to the protected storage until the guard is dropped.
                ptr: unsafe { &mut *self.storage.get() },
                #[cfg(feature = "smp")]
                flag_ref: &self.flag,
            })
        } else {
            G::release(guard_state);
            None
        }
    }

